/* ---------------- App modes ---------------- */

type Mode = "mobius" | "chebyshev" | "transform" | "maps" | "surfaces" | "curves" | "topology" | "geometry";
const APP_MODE_VALUES: Mode[] = ["mobius", "chebyshev", "transform", "maps", "surfaces", "curves", "topology", "geometry"];
const isAppMode = (value: string | null | undefined): value is Mode => !!value && APP_MODE_VALUES.includes(value as Mode);
type SurfaceViewerKind = "implicit" | "graph" | "param" | "weierstrass" | "mesh" | "complex";
type MeshBooleanOperation = "union" | "difference" | "intersection" | "split" | "imprint";
type ChartMode = "auto" | "xy" | "uv" | "local";
type MeshChartGridMode = "local" | "meshFace";
type SurfaceMeshAssetPreset = {
  id: string;
  label: string;
  assetUrl: string;
  fileName: string;
};
type SurfaceMeshTopologyDemoPreset = {
  id: string;
  label: string;
  operation: SurfaceMeshTopologyOperation;
  summary: string;
  tryHint: string;
  expectedResult: string;
  workflowHint?: string;
  workflowKind?: "operation" | "round-trip";
  build: () => SurfaceMeshData;
  faceIndex: number;
  edge: [number, number];
  subdivideMode?: FaceSubdivideMode;
  splitRatio?: number;
  collapseMode?: EdgeCollapseMode;
  bevelAmount?: number;
};
type SurfaceMeshTopologyOperation =
  | "Face Subdivide"
  | "Extrude Face"
  | "Inset Face"
  | "Split Edge"
