const VARIANT_GHOST_MESH_KEY_PREFIX = "variant-ghost:";
const isVariantGhostMeshKey = (meshKey: string | null | undefined): boolean =>
  !!meshKey && meshKey.startsWith(VARIANT_GHOST_MESH_KEY_PREFIX);
const isConstructionWorkspaceTabValue = (value: string | undefined): value is ConstructionWorkspaceTab =>
  !!value && GEOMETRY_WORKSPACE_TAB_VALUES.includes(value as ConstructionWorkspaceTab);
const isSurfacesLeftTabValue = (value: string | undefined): value is (typeof SURFACES_LEFT_TAB_VALUES)[number] =>
  !!value && SURFACES_LEFT_TAB_VALUES.includes(value as (typeof SURFACES_LEFT_TAB_VALUES)[number]);
const isMobiusSubTabValue = (value: string | undefined): value is MobiusSubTab =>
  !!value && MOBIUS_SUB_TAB_VALUES.includes(value as MobiusSubTab);
const isWorkspaceModuleValue = (value: string | undefined): value is WorkspaceModule =>
  value === "surfaces" ||
  value === "mesh" ||
  value === "volume" ||
  value === "curves" ||
  value === "topology" ||
  value === "geometry" ||
  value === "mobius";
const areWorkspaceLocationsEqual = (a: WorkspaceLocationEntry, b: WorkspaceLocationEntry) =>
  a.module === b.module &&
  a.workspaceMode === b.workspaceMode &&
  a.panel === b.panel &&
  (a.selectedObjectId ?? null) === (b.selectedObjectId ?? null) &&
  (a.activeStageId ?? null) === (b.activeStageId ?? null) &&
  a.viewMode === b.viewMode &&
  (a.cameraPreset ?? null) === (b.cameraPreset ?? null) &&
  (a.sceneId ?? null) === (b.sceneId ?? null);
const SURFACE_VIEWER_KINDS: SurfaceViewerKind[] = [
  "implicit",
  "graph",
  "param",
  "weierstrass",
  "mesh",
  "complex",
];
const isSurfaceViewerKind = (value: string | undefined): value is SurfaceViewerKind =>
  !!value && SURFACE_VIEWER_KINDS.includes(value as SurfaceViewerKind);
const isSurfaceDatasetKind = (value: DatasetKind): value is "surface" | "mesh" =>
  value === "surface" || value === "mesh";
const surfaceTypeFromViewerKind = (value: SurfaceViewerKind): SurfaceType => {
  if (value === "graph") return "explicit";
  if (value === "implicit") return "implicit";
  if (value === "param") return "param";
  if (value === "weierstrass") return "weierstrass";
  return "mesh";
};
