const applySurfaceMeshOps = (mesh: SurfaceMeshData): SurfaceMeshData => {
  let next = mesh;
  if (!mesh.normals || mesh.normals.length < mesh.positions.length) {
    next = computeVertexNormals(next);
  }
  next = computeAdjacency(next);
  next = computeMeanEdgeLength(next);
  next = validateMesh(next);
  return next;
};

const buildMeshAdjacencyFromFaces = (mesh: Pick<SurfaceMeshData, "positions" | "indices">): number[][] => {
  const vertexCount = Math.floor((mesh.positions?.length ?? 0) / 3);
  const neighborSets = Array.from({ length: vertexCount }, () => new Set<number>());
  const indices = mesh.indices ?? null;
  const faceCount = indices ? Math.floor(indices.length / 3) : Math.floor(vertexCount / 3);
  const link = (a: number, b: number) => {
    if (!Number.isInteger(a) || !Number.isInteger(b)) return;
    if (a < 0 || b < 0 || a >= vertexCount || b >= vertexCount || a === b) return;
    neighborSets[a].add(b);
    neighborSets[b].add(a);
  };
  for (let faceIndex = 0; faceIndex < faceCount; faceIndex += 1) {
    let a = faceIndex * 3;
    let b = a + 1;
    let c = a + 2;
    if (indices) {
      const base = faceIndex * 3;
      a = Number(indices[base] ?? -1);
      b = Number(indices[base + 1] ?? -1);
      c = Number(indices[base + 2] ?? -1);
    }
    link(a, b);
    link(b, c);
    link(c, a);
  }
  return neighborSets.map((neighbors) => Array.from(neighbors));
};

const countMeshConnectedComponents = (mesh: SurfaceMeshData | null): number | null => {
  if (!mesh?.positions?.length) return null;
  const vertexCount = Math.floor(mesh.positions.length / 3);
  if (vertexCount <= 0) return 0;
  const adjacency =
    mesh.adjacency && mesh.adjacency.length === vertexCount
      ? mesh.adjacency
      : buildMeshAdjacencyFromFaces(mesh);
  const visited = new Uint8Array(vertexCount);
  const stack: number[] = [];
  let components = 0;
  for (let start = 0; start < vertexCount; start += 1) {
    if (visited[start]) continue;
    components += 1;
    visited[start] = 1;
    stack.push(start);
    while (stack.length) {
      const current = stack.pop() ?? -1;
      if (current < 0 || current >= vertexCount) continue;
      const row = adjacency[current] ?? [];
      for (const next of row) {
        if (next < 0 || next >= vertexCount || visited[next]) continue;
        visited[next] = 1;
        stack.push(next);
      }
    }
  }
  return components;
};

const toMeshDataset = (mesh: SurfaceMeshData | null): MeshDataset | null =>
  mesh ? { kind: "mesh", surfaceType: "mesh", mesh } : null;

const cloneSurfaceMeshData = (mesh: SurfaceMeshData, labelOverride?: string): SurfaceMeshData => ({
  ...mesh,
  label: labelOverride ?? mesh.label,
  positions: Float32Array.from(mesh.positions),
  indices: mesh.indices ? Uint32Array.from(mesh.indices) : null,
  normals: mesh.normals ? Float32Array.from(mesh.normals) : null,
  uvs: mesh.uvs ? Float32Array.from(mesh.uvs) : null,
  adjacency: mesh.adjacency ? mesh.adjacency.map((row) => row.slice()) : null,
  meanEdgeLength: mesh.meanEdgeLength ?? null,
  validation: mesh.validation
    ? {
        ...mesh.validation,
        errors: [...mesh.validation.errors],
        warnings: [...mesh.validation.warnings],
        stats: { ...mesh.validation.stats },
      }
    : null,
});

const toDetachedMeshData = (mesh: SurfaceMeshData, labelOverride?: string): SurfaceMeshData => {
  const detached = cloneSurfaceMeshData(mesh, labelOverride);
  if (mesh.source.kind === "detachedMesh") {
    return detached;
  }
  return {
    ...detached,
    source: {
      kind: "detachedMesh",
      fromKind: mesh.source.kind,
      fromLabel: formatSurfaceMeshSource(mesh.source),
    },
  };
};
const geometryVecLen = (v: { x: number; y: number; z: number }) => Math.hypot(v.x, v.y, v.z);
const geometryNormalizeVec = (v: { x: number; y: number; z: number }) => {
  const len = geometryVecLen(v);
  if (!Number.isFinite(len) || len < 1e-9) return null;
  return { x: v.x / len, y: v.y / len, z: v.z / len };
};
const geometryDot = (a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }) =>
  a.x * b.x + a.y * b.y + a.z * b.z;
const geometryCross = (a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }) => ({
  x: a.y * b.z - a.z * b.y,
  y: a.z * b.x - a.x * b.z,
  z: a.x * b.y - a.y * b.x,
});
const geometrySub = (a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }) => ({
  x: a.x - b.x,
  y: a.y - b.y,
  z: a.z - b.z,
});
const geometryAdd = (a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }) => ({
  x: a.x + b.x,
  y: a.y + b.y,
  z: a.z + b.z,
});
const geometryScale = (v: { x: number; y: number; z: number }, scale: number) => ({
  x: v.x * scale,
  y: v.y * scale,
  z: v.z * scale,
});
const geometryDistance = (a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }) =>
  Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
const geometryMeshTopologySignature = (mesh: SurfaceMeshData): string => {
  const vertCount = Math.floor(mesh.positions.length / 3);
  const triCount =
    mesh.indices && mesh.indices.length >= 3 ? Math.floor(mesh.indices.length / 3) : Math.floor(vertCount / 3);
  const posHead = Array.from(mesh.positions.slice(0, 18)).map((v) => Number(v).toFixed(5)).join(",");
  const posTail = Array.from(mesh.positions.slice(Math.max(0, mesh.positions.length - 18)))
    .map((v) => Number(v).toFixed(5))
    .join(",");
  const idxHead = mesh.indices ? Array.from(mesh.indices.slice(0, 18)).join(",") : "no-indices";
  return `${vertCount}|${triCount}|${posHead}|${posTail}|${idxHead}`;
};
const geometryFaceSignatureFromTriangle = (
  a: { x: number; y: number; z: number },
  b: { x: number; y: number; z: number },
  c: { x: number; y: number; z: number }
) => {
  const ab = geometrySub(b, a);
  const ac = geometrySub(c, a);
  const normalRaw = geometryCross(ab, ac);
  const normal = geometryNormalizeVec(normalRaw) ?? { x: 0, y: 1, z: 0 };
  const area = 0.5 * geometryVecLen(normalRaw);
  return {
    centroid: {
      x: (a.x + b.x + c.x) / 3,
      y: (a.y + b.y + c.y) / 3,
      z: (a.z + b.z + c.z) / 3,
    },
    normal,
    area,
  };
};
const geometryEdgeSignatureFromPoints = (
  a: { x: number; y: number; z: number },
  b: { x: number; y: number; z: number }
) => {
  const raw = geometrySub(b, a);
  const length = geometryVecLen(raw);
  if (!Number.isFinite(length) || length < 1e-9) {
    return {
      midpoint: { x: (a.x + b.x) * 0.5, y: (a.y + b.y) * 0.5, z: (a.z + b.z) * 0.5 },
      direction: { x: 1, y: 0, z: 0 },
      length: 0,
    };
  }
  let direction = { x: raw.x / length, y: raw.y / length, z: raw.z / length };
  if (
    direction.x < 0 ||
    (Math.abs(direction.x) < 1e-9 && direction.y < 0) ||
    (Math.abs(direction.x) < 1e-9 && Math.abs(direction.y) < 1e-9 && direction.z < 0)
  ) {
    direction = { x: -direction.x, y: -direction.y, z: -direction.z };
  }
  return {
    midpoint: { x: (a.x + b.x) * 0.5, y: (a.y + b.y) * 0.5, z: (a.z + b.z) * 0.5 },
    direction,
    length,
  };
};
const geometryFaceSignatureDistance = (
  a: { centroid: { x: number; y: number; z: number }; normal: { x: number; y: number; z: number }; area: number },
  b: { centroid: { x: number; y: number; z: number }; normal: { x: number; y: number; z: number }; area: number }
) => {
  const centroidDelta = geometryDistance(a.centroid, b.centroid);
  const normalDot = Math.abs(geometryDot(a.normal, b.normal));
  const normalDelta = 1 - clampNumber(normalDot, 0, 1);
  const areaDelta = Math.abs(a.area - b.area);
  return { centroidDelta, normalDelta, areaDelta };
};
const geometryEdgeSignatureDistance = (
  a: { midpoint: { x: number; y: number; z: number }; direction: { x: number; y: number; z: number }; length: number },
  b: { midpoint: { x: number; y: number; z: number }; direction: { x: number; y: number; z: number }; length: number }
) => {
  const midpointDelta = geometryDistance(a.midpoint, b.midpoint);
  const directionDelta = 1 - clampNumber(Math.abs(geometryDot(a.direction, b.direction)), 0, 1);
  const lengthDelta = Math.abs(a.length - b.length);
  return { midpointDelta, directionDelta, lengthDelta };
};

const serializeSurfaceMeshData = (mesh: SurfaceMeshData): WorkbookEmbeddedMesh => ({
  label: mesh.label,
  positions: Array.from(mesh.positions),
  indices: mesh.indices ? Array.from(mesh.indices) : null,
  normals: mesh.normals ? Array.from(mesh.normals) : null,
  uvs: mesh.uvs ? Array.from(mesh.uvs) : null,
  source: mesh.source,
});

const deserializeSurfaceMeshData = (mesh: WorkbookEmbeddedMesh): SurfaceMeshData => ({
  label: mesh.label,
  positions: Float32Array.from(mesh.positions),
  indices: mesh.indices ? Uint32Array.from(mesh.indices) : null,
  normals: mesh.normals ? Float32Array.from(mesh.normals) : null,
  uvs: mesh.uvs ? Float32Array.from(mesh.uvs) : null,
  source: mesh.source,
});

const cloneMeshSourceSelectionOverlay = (
  overlay:
    | {
        readonly tool: MeshEdgeSelectionTool;
        readonly seed: readonly [number, number];
        readonly edges: readonly (readonly [number, number])[];
        readonly label: string;
        readonly status: string;
      }
    | null
    | undefined
): MeshSourceSelectionOverlay | null =>
  overlay
    ? {
        tool: overlay.tool,
        seed: [Number(overlay.seed[0]), Number(overlay.seed[1])],
        edges: overlay.edges.map(([a, b]) => [Number(a), Number(b)]),
        label: overlay.label,
        status: overlay.status,
      }
    : null;

const cloneGeometryPromotionMetadata = (
  promotion: GeometryToMeshPromotionMetadata | null | undefined
): GeometryToMeshPromotionMetadata | null => {
  if (!promotion) return null;
  return {
    ...promotion,
    sourceOperationHistory: [...(promotion.sourceOperationHistory ?? [])],
    bounds: promotion.bounds
      ? { min: [...promotion.bounds.min] as [number, number, number], max: [...promotion.bounds.max] as [number, number, number] }
      : null,
    validityReport: {
      ...promotion.validityReport,
      checks: promotion.validityReport.checks.map((check) => ({ ...check })),
      stats: { ...promotion.validityReport.stats },
      suggestions: { ...promotion.validityReport.suggestions },
      notes: [...promotion.validityReport.notes],
    },
  };
};

const serializeGeometryDatasetMeshObject = (obj: GeometryDatasetMeshObject): WorkbookGeometryDatasetMeshObject => ({
  id: obj.id,
  name: obj.name,
  mesh: serializeSurfaceMeshData(obj.mesh),
  transform: {
    position: { ...obj.transform.position },
    rotation: { ...obj.transform.rotation },
    scale: { ...obj.transform.scale },
  },
  visible: obj.visible,
  material: normalizeGeometryMaterial((obj as { material?: unknown })?.material),
  promotion: cloneGeometryPromotionMetadata(obj.promotion),
  restoredGeometryPreset: obj.restoredGeometryPreset ? { ...obj.restoredGeometryPreset } : null,
  sourceSelectionOverlay: cloneMeshSourceSelectionOverlay(obj.sourceSelectionOverlay),
});

