const groupGeometryConstructEntries = <T extends { groupTitle: string }>(
  entries: T[]
): Array<{ title: string; entries: T[] }> => {
  const groups: Array<{ title: string; entries: T[] }> = [];
  for (const entry of entries) {
    const existing = groups.find((group) => group.title === entry.groupTitle);
    if (existing) {
      existing.entries.push(entry);
      continue;
    }
    groups.push({ title: entry.groupTitle, entries: [entry] });
  }
  return groups;
};
const GeometryConstructInputSlotRow: React.FC<{
  input: GeometryConstructInputSlot;
  index: number;
  testId?: string;
  compact?: boolean;
  active?: boolean;
  onActivate?: () => void;
  onClear?: () => void;
}> = ({ input, index, testId, compact = false, active = false, onActivate, onClear }) => {
  const ready = input.ok;
  const interactive = !!onActivate;
  const status = active ? "next" : input.status ?? (ready ? "selected" : "waiting");
  const statusMeta =
    status === "duplicate"
      ? { label: "Duplicate", border: "#f97316", fill: "#fff7ed", bar: "#f97316", chip: "#9a3412", badgeBg: "#ffedd5" }
      : status === "invalid"
        ? { label: "Invalid", border: "#ef4444", fill: "#fef2f2", bar: "#ef4444", chip: "#b42318", badgeBg: "#fee2e2" }
        : status === "incompatible"
          ? { label: "Blocked", border: "#dc2626", fill: "#fef2f2", bar: "#dc2626", chip: "#991b1b", badgeBg: "#fee2e2" }
          : status === "next"
            ? { label: "Next", border: "#2563eb", fill: "#eff6ff", bar: "#2563eb", chip: "#1d4ed8", badgeBg: "#dbeafe" }
            : ready
              ? { label: "Selected", border: "#22c55e", fill: "#f0fdf4", bar: "#22c55e", chip: "#15803d", badgeBg: "#ffffff" }
              : { label: "Waiting", border: "#f59e0b", fill: "#fffbeb", bar: "#f59e0b", chip: "#b45309", badgeBg: "#fff7ed" };
  return (
    <div
      data-testid={testId}
      title={`${input.label}: ${input.value}${input.detail ? ` (${input.detail})` : ""}`}
      style={{
        display: "grid",
        gridTemplateColumns: compact
          ? `20px minmax(0, 1fr) minmax(48px, auto)${onClear ? " 22px" : ""}`
          : `22px minmax(48px, 0.7fr) minmax(0, 1fr) minmax(48px, auto)${onClear ? " 22px" : ""}`,
        gap: compact ? "3px 6px" : "4px 8px",
        alignItems: "center",
        border: `1px solid ${statusMeta.border}`,
        borderRadius: 8,
        background: status === "selected" ? "linear-gradient(180deg, #f0fdf4 0%, #dcfce7 100%)" : statusMeta.fill,
        boxShadow:
          status === "next"
            ? "inset 3px 0 0 #2563eb, 0 0 0 2px rgba(37, 99, 235, 0.14)"
            : `inset 3px 0 0 ${statusMeta.bar}`,
        padding: compact ? "4px 6px" : "5px 7px",
        fontSize: compact ? 10.5 : 11,
        minWidth: 0,
        cursor: interactive ? "pointer" : "default",
      }}
      onClick={onActivate}
      role={interactive ? "button" : undefined}
      tabIndex={interactive ? 0 : undefined}
      onKeyDown={
        interactive
          ? (event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                onActivate?.();
              }
            }
          : undefined
      }
    >
      <span
        aria-hidden="true"
        style={{
          width: 18,
          height: 18,
          borderRadius: 999,
          display: "grid",
          placeItems: "center",
          border: `1px solid ${statusMeta.border}`,
          background: status === "waiting" ? "#ffffff" : statusMeta.bar,
          color: status === "waiting" ? statusMeta.chip : "#ffffff",
          fontSize: 9.5,
          fontWeight: 900,
          lineHeight: 1,
        }}
      >
        {ready && status === "selected" ? "OK" : status === "duplicate" ? "D" : status === "invalid" || status === "incompatible" ? "!" : index + 1}
      </span>
      <span style={{ color: "#334155", fontWeight: 900, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
        {input.label}
      </span>
      {!compact && (
        <span style={{ minWidth: 0, color: "#0f172a", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
          {input.value}
        </span>
      )}
      <span
        style={{
          border: `1px solid ${statusMeta.border}`,
          borderRadius: 999,
          background: statusMeta.badgeBg,
          color: statusMeta.chip,
          padding: "1px 6px",
          fontSize: 9.5,
          fontWeight: 900,
          lineHeight: 1.2,
          whiteSpace: "nowrap",
          overflow: "hidden",
          textOverflow: "ellipsis",
          minWidth: 0,
        }}
      >
        {statusMeta.label}
      </span>
      {onClear && (
        <button
          type="button"
          aria-label={`Clear ${input.label}`}
          title={`Clear ${input.label}`}
          onClick={(event) => {
            event.stopPropagation();
            onClear();
          }}
          style={{
            width: 20,
            height: 20,
            borderRadius: 999,
            border: "1px solid #cbd5e1",
            background: "#ffffff",
            color: "#475569",
            fontSize: 12,
            fontWeight: 900,
            lineHeight: 1,
            padding: 0,
            display: "grid",
            placeItems: "center",
            cursor: "pointer",
          }}
        >
          x
        </button>
      )}
      {compact && (
        <span
          style={{
            gridColumn: onClear ? "2 / -2" : "2 / -1",
            minWidth: 0,
            color: "#0f172a",
            overflow: "hidden",
            textOverflow: "ellipsis",
            whiteSpace: "nowrap",
          }}
        >
          {input.value}
        </span>
      )}
    </div>
  );
};
