const DEFAULT_GEOMETRY_MATERIAL_COLOR = 0x8aa4ff;
const DEFAULT_GEOMETRY_MATERIAL_OPACITY = 1;
const DEFAULT_GEOMETRY_MATERIAL_ROUGHNESS = 0.3;
const DEFAULT_GEOMETRY_MATERIAL_METALNESS = 0.1;
type GeometryViewerMeshOverride = NonNullable<GeometryViewerProps["meshOverrides"]>[number];

const normalizeGeometryMaterial = (material: unknown): GeometryObject["material"] => {
  const m = material && typeof material === "object" ? (material as Record<string, unknown>) : {};
  const colorRaw = m.color;
  const opacityRaw = m.opacity;
  const roughnessRaw = m.roughness;
  const metalnessRaw = m.metalness;
  return {
    color:
      typeof colorRaw === "number" && Number.isFinite(colorRaw)
        ? colorRaw
        : DEFAULT_GEOMETRY_MATERIAL_COLOR,
    opacity:
      typeof opacityRaw === "number" && Number.isFinite(opacityRaw)
        ? clampNumber(opacityRaw, 0, 1)
        : DEFAULT_GEOMETRY_MATERIAL_OPACITY,
    roughness:
      typeof roughnessRaw === "number" && Number.isFinite(roughnessRaw)
        ? clampNumber(roughnessRaw, 0, 1)
        : DEFAULT_GEOMETRY_MATERIAL_ROUGHNESS,
    metalness:
      typeof metalnessRaw === "number" && Number.isFinite(metalnessRaw)
        ? clampNumber(metalnessRaw, 0, 1)
        : DEFAULT_GEOMETRY_MATERIAL_METALNESS,
  };
};

const formatInspectorMaterialInfo = (
  material: { color?: number; opacity?: number; roughness?: number; metalness?: number } | null | undefined
): string | null => {
  if (!material) return null;
  const color = typeof material.color === "number" && Number.isFinite(material.color)
    ? `#${Math.round(material.color).toString(16).padStart(6, "0")}`
    : "default";
  const opacity = typeof material.opacity === "number" && Number.isFinite(material.opacity)
    ? material.opacity.toFixed(2)
    : "n/a";
  const roughness = typeof material.roughness === "number" && Number.isFinite(material.roughness)
    ? material.roughness.toFixed(2)
    : "n/a";
  const metalness = typeof material.metalness === "number" && Number.isFinite(material.metalness)
    ? material.metalness.toFixed(2)
    : "n/a";
  return `${color}, opacity ${opacity}, roughness ${roughness}, metalness ${metalness}`;
};

const isDefaultVec3 = (value: Vec3, expected: Vec3) =>
  Math.abs(value.x - expected.x) < 1e-9 &&
  Math.abs(value.y - expected.y) < 1e-9 &&
  Math.abs(value.z - expected.z) < 1e-9;

const isDefaultGeometryParamSet = (
  params: Record<string, number | boolean | string>,
  expected: Record<string, number | boolean | string>
) => {
  const expectedEntries = Object.entries(expected);
  if (Object.keys(params).length !== expectedEntries.length) return false;
  for (const [key, expectedValue] of expectedEntries) {
    if (params[key] !== expectedValue) return false;
  }
  return true;
};

const isSeedGeometryBoxObject = (obj: GeometryObject) => {
  if (obj.type !== "box") return false;
  if (obj.name !== GEOMETRY_OBJECT_REGISTRY.box.label) return false;
  if (!obj.visible) return false;
  if (!isDefaultGeometryParamSet(obj.params, GEOMETRY_OBJECT_REGISTRY.box.defaultParams)) return false;
  if (!isDefaultVec3(obj.transform.position, { x: 0, y: 0, z: 0 })) return false;
  if (!isDefaultVec3(obj.transform.rotation, { x: 0, y: 0, z: 0 })) return false;
  if (!isDefaultVec3(obj.transform.scale, { x: 1, y: 1, z: 1 })) return false;
  const material = normalizeGeometryMaterial(obj.material);
  const color = material.color;
  const opacity = material.opacity ?? DEFAULT_GEOMETRY_MATERIAL_OPACITY;
  if (color !== DEFAULT_GEOMETRY_MATERIAL_COLOR) return false;
  if (Math.abs(opacity - DEFAULT_GEOMETRY_MATERIAL_OPACITY) > 1e-9) return false;
  return true;
};

