const UNIFIED_SCENE_ROLE_LABELS: Record<UnifiedSceneRole, string> = {
  primaryObject: "PrimaryObject",
  overlay: "Overlay",
  derivedResult: "DerivedResult",
  referenceObject: "ReferenceObject",
};

const geometryDerivedOperationFromType = (type: string): GeometryDerivedOperation | null => {
  const normalized = type.toLowerCase();
  if (normalized.includes("wireframe")) return "wireframe";
  if (normalized.includes("bounding-box")) return "bounding-box";
  if (normalized.includes("normal")) return "normals";
  if (normalized.includes("point-cloud")) return "point-cloud";
  if (normalized.includes("convex-hull")) return "convex-hull";
  if (normalized.includes("section") || normalized.includes("slice")) return "section";
  return null;
};

const inferUnifiedSceneRole = (
  category: UnifiedObjectCategory,
  type: string,
  sourceDefinition: string
): UnifiedSceneRole => {
  if (category === "sceneObject") return "primaryObject";
  if (category === "surfaceDefinition") return "referenceObject";
  if (category === "dataset") {
    return sourceDefinition.toLowerCase().includes("import") ? "referenceObject" : "derivedResult";
  }
  if (
    type.includes("wireframe") ||
    type.includes("chart-grid") ||
    type.includes("coordinate-planes") ||
    type.includes("bounding-box") ||
    type.includes("normals") ||
    type.includes("axes") ||
    type.includes("label") ||
    type.includes("helper")
  ) {
    return "overlay";
  }
  return "derivedResult";
};

const axisPatch = (axis: keyof Vec3, value: number): Partial<Vec3> => ({ [axis]: value } as Partial<Vec3>);

const toClampedInt = (value: number, fallback: number, min: number, max: number) =>
  clampNumber(Math.round(toSafeNumber(value, fallback)), min, max);

type PolyhedronCounts = { vertices: number; edges: number; faces: number; triangles: number };

const PLATONIC_COUNTS: Record<string, PolyhedronCounts> = {
  tetra: { vertices: 4, edges: 6, faces: 4, triangles: 4 },
  cube: { vertices: 8, edges: 12, faces: 6, triangles: 12 },
  octa: { vertices: 6, edges: 12, faces: 8, triangles: 8 },
  dodeca: { vertices: 20, edges: 30, faces: 12, triangles: 36 },
  icosa: { vertices: 12, edges: 30, faces: 20, triangles: 20 },
};

const getPolyhedronCounts = (family: string, params: Record<string, number | boolean | string>): PolyhedronCounts => {
  const subdivision = toClampedInt(Number(params.subdivision ?? 0), 0, 0, 5);
  const triScale = Math.pow(4, subdivision);
  if (family === "platonic") {
    const kind = String(params.kind ?? "dodeca");
    const base = PLATONIC_COUNTS[kind] ?? PLATONIC_COUNTS.dodeca;
    return { ...base, triangles: Math.max(1, Math.round(base.triangles * triScale)) };
  }
  if (family === "geodesic") {
    const t = toClampedInt(Number(params.frequency ?? 2), 2, 1, 8);
    const faces = 20 * t * t;
    return { vertices: 10 * t * t + 2, edges: 30 * t * t, faces, triangles: faces };
  }
  const n = toClampedInt(Number(params.n ?? 6), 6, 3, 64);
  const hasCaps = Boolean(params.cap ?? true);
  if (family === "prism") {
    return {
      vertices: 2 * n,
      edges: 3 * n,
      faces: hasCaps ? n + 2 : n,
      triangles: hasCaps ? 4 * n - 4 : 2 * n,
    };
  }
  if (family === "pyramid") {
    return {
      vertices: n + 1,
      edges: 2 * n,
      faces: hasCaps ? n + 1 : n,
      triangles: hasCaps ? 2 * n - 2 : n,
    };
  }
  if (family === "frustum") {
    const topRadius = Math.max(0, Number(params.topRadius ?? 0.55));
    if (topRadius <= 1e-6) {
      return {
        vertices: n + 1,
        edges: 2 * n,
        faces: hasCaps ? n + 1 : n,
        triangles: hasCaps ? 2 * n - 2 : n,
      };
    }
    return {
      vertices: 2 * n,
      edges: 3 * n,
      faces: hasCaps ? n + 2 : n,
      triangles: hasCaps ? 4 * n - 4 : 2 * n,
    };
  }
  if (family === "bipyramid") {
    return { vertices: n + 2, edges: 3 * n, faces: 2 * n, triangles: 2 * n };
  }
  if (family === "antiprism") {
    return { vertices: 2 * n, edges: 4 * n, faces: 2 * n + 2, triangles: 4 * n - 4 };
  }
  return PLATONIC_COUNTS.dodeca;
};

const toHexColorString = (value: number | undefined, fallback = 0x8aa4ff) => {
  const color = Number.isFinite(value) ? Number(value) : fallback;
  const safe = Math.max(0, Math.min(0xffffff, Math.round(color)));
  return `#${safe.toString(16).padStart(6, "0")}`;
};

const fromHexColorString = (value: string, fallback = 0x8aa4ff) => {
  if (typeof value !== "string") return fallback;
  const raw = value.trim().replace(/^#/, "");
  if (!/^[0-9a-fA-F]{6}$/.test(raw)) return fallback;
  const parsed = Number.parseInt(raw, 16);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const closestColorPaletteForHex = (hex: number): ColorPalette => {
  const candidates: ColorPalette[] = ["blueRed", "rainbow", "grayscale", "redYellow"];
  const r = (hex >> 16) & 0xff;
  const g = (hex >> 8) & 0xff;
  const b = hex & 0xff;
  let best = candidates[0];
  let bestDist = Number.POSITIVE_INFINITY;
  for (const candidate of candidates) {
    const c = solidColorForPalette(candidate);
    const cr = (c >> 16) & 0xff;
    const cg = (c >> 8) & 0xff;
    const cb = c & 0xff;
    const d = (r - cr) ** 2 + (g - cg) ** 2 + (b - cb) ** 2;
    if (d < bestDist) {
      bestDist = d;
      best = candidate;
    }
  }
  return best;
};

