type TriangleMeshCellCounts = {
  c0: number;
  c1: number;
  c2: number;
  chi: number;
  validFaces: number;
  skippedFaces: number;
};

type FundamentalDiagramPreview = {
  width: number;
  height: number;
  boundaryWord: string;
  vertices: Array<{ id: string; x: number; y: number; label: string }>;
  edges: Array<{
    id: string;
    x1: number;
    y1: number;
    x2: number;
    y2: number;
    lx: number;
    ly: number;
    color: string;
    label: string;
    dashed: boolean;
    opacity: number;
    strokeWidth: number;
  }>;
  animatedEdges: Array<{
    id: string;
    x1: number;
    y1: number;
    x2: number;
    y2: number;
    lx: number;
    ly: number;
    color: string;
    label: string;
    dashed: boolean;
    opacity: number;
    strokeWidth: number;
  }>;
};

const boundaryLabelToken = (rawLabel: string | undefined): string => {
  const token = (rawLabel ?? "")
    .trim()
    .toLowerCase()
    .replace(/\^-1$/g, "")
    .replace(/[^a-z0-9]/g, "");
  return token;
};

const boundaryLabelColor = (token: string): string => {
  if (token === "a") return "#dc2626";
  if (token === "b") return "#2563eb";
  if (token === "c") return "#0f766e";
  if (token === "u") return "#7c3aed";
  if (token === "v") return "#ea580c";
  return "#334155";
};

const computeTriangleMeshCellCounts = (mesh: {
  positions: ArrayLike<number>;
  indices?: ArrayLike<number> | null;
}): TriangleMeshCellCounts => {
  const vertexCount = Math.floor((mesh.positions?.length ?? 0) / 3);
  if (vertexCount <= 0) {
    return { c0: 0, c1: 0, c2: 0, chi: 0, validFaces: 0, skippedFaces: 0 };
  }
  const indices = mesh.indices ?? null;
  const triCount = indices && indices.length >= 3 ? Math.floor(indices.length / 3) : Math.floor(vertexCount / 3);
  const edgeSet = new Set<string>();
  let validFaces = 0;
  let skippedFaces = 0;
  const addEdge = (a: number, b: number) => {
    const i0 = Math.min(a, b);
    const i1 = Math.max(a, b);
    edgeSet.add(`${i0}|${i1}`);
  };
  for (let t = 0; t < triCount; t += 1) {
    const base = t * 3;
    const ia = indices ? Number(indices[base]) : base;
    const ib = indices ? Number(indices[base + 1]) : base + 1;
    const ic = indices ? Number(indices[base + 2]) : base + 2;
    const allFinite = Number.isInteger(ia) && Number.isInteger(ib) && Number.isInteger(ic);
    const inRange =
      ia >= 0 && ib >= 0 && ic >= 0 && ia < vertexCount && ib < vertexCount && ic < vertexCount;
    const distinct = ia !== ib && ib !== ic && ia !== ic;
    if (!allFinite || !inRange || !distinct) {
      skippedFaces += 1;
      continue;
    }
    validFaces += 1;
    addEdge(ia, ib);
    addEdge(ib, ic);
    addEdge(ic, ia);
  }
  const c0 = vertexCount;
  const c1 = edgeSet.size;
  const c2 = validFaces;
  return {
    c0,
    c1,
    c2,
    chi: c0 - c1 + c2,
    validFaces,
    skippedFaces,
  };
};

const computeTriangleMeshEdgeTopology = (mesh: {
  positions: ArrayLike<number>;
  indices?: ArrayLike<number> | null;
}): { boundaryEdgeCount: number; nonManifoldEdgeCount: number; manifold: boolean; watertight: boolean } => {
  const vertexCount = Math.floor((mesh.positions?.length ?? 0) / 3);
  if (vertexCount <= 0) {
    return { boundaryEdgeCount: 0, nonManifoldEdgeCount: 0, manifold: true, watertight: true };
  }
  const indices = mesh.indices ?? null;
  const triCount = indices && indices.length >= 3 ? Math.floor(indices.length / 3) : Math.floor(vertexCount / 3);
  const edgeIncidence = new Map<string, number>();
  const bumpEdge = (a: number, b: number) => {
    const i0 = Math.min(a, b);
    const i1 = Math.max(a, b);
    const key = `${i0}|${i1}`;
    edgeIncidence.set(key, (edgeIncidence.get(key) ?? 0) + 1);
  };
  for (let t = 0; t < triCount; t += 1) {
    const base = t * 3;
    const ia = indices ? Number(indices[base]) : base;
    const ib = indices ? Number(indices[base + 1]) : base + 1;
    const ic = indices ? Number(indices[base + 2]) : base + 2;
    const allFinite = Number.isInteger(ia) && Number.isInteger(ib) && Number.isInteger(ic);
    const inRange =
      ia >= 0 && ib >= 0 && ic >= 0 && ia < vertexCount && ib < vertexCount && ic < vertexCount;
    const distinct = ia !== ib && ib !== ic && ia !== ic;
    if (!allFinite || !inRange || !distinct) continue;
    bumpEdge(ia, ib);
    bumpEdge(ib, ic);
    bumpEdge(ic, ia);
  }
  let boundaryEdgeCount = 0;
  let nonManifoldEdgeCount = 0;
  for (const count of edgeIncidence.values()) {
    if (count === 1) boundaryEdgeCount += 1;
    else if (count > 2) nonManifoldEdgeCount += 1;
  }
  const manifold = nonManifoldEdgeCount === 0;
  const watertight = manifold && boundaryEdgeCount === 0;
  return { boundaryEdgeCount, nonManifoldEdgeCount, manifold, watertight };
};

type TriangleMeshGeometricMetrics = {
  vertexCount: number;
  faceCount: number;
  surfaceArea: number;
  volume: number;
  bounds: BBox3 | null;
  dimensions: { x: number; y: number; z: number } | null;
};

const computeTriangleMeshGeometricMetrics = (mesh: {
  positions: ArrayLike<number>;
  indices?: ArrayLike<number> | null;
}): TriangleMeshGeometricMetrics => {
  const positions = mesh.positions;
  const vertexCount = Math.floor((positions?.length ?? 0) / 3);
  if (vertexCount <= 0) {
    return {
      vertexCount: 0,
      faceCount: 0,
      surfaceArea: 0,
      volume: 0,
      bounds: null,
      dimensions: null,
    };
  }
  const indices = mesh.indices ?? null;
  const triCount = indices && indices.length >= 3 ? Math.floor(indices.length / 3) : Math.floor(vertexCount / 3);
  let surfaceArea = 0;
  let signedVolume = 0;
  let faceCount = 0;
  for (let t = 0; t < triCount; t += 1) {
    const base = t * 3;
    const ia = indices ? Number(indices[base]) : base;
    const ib = indices ? Number(indices[base + 1]) : base + 1;
    const ic = indices ? Number(indices[base + 2]) : base + 2;
    if (!Number.isInteger(ia) || !Number.isInteger(ib) || !Number.isInteger(ic)) continue;
    if (ia < 0 || ib < 0 || ic < 0 || ia >= vertexCount || ib >= vertexCount || ic >= vertexCount) continue;
    if (ia === ib || ib === ic || ia === ic) continue;
    const a3 = ia * 3;
    const b3 = ib * 3;
    const c3 = ic * 3;
    const ax = Number(positions[a3] ?? 0);
    const ay = Number(positions[a3 + 1] ?? 0);
    const az = Number(positions[a3 + 2] ?? 0);
    const bx = Number(positions[b3] ?? 0);
    const by = Number(positions[b3 + 1] ?? 0);
    const bz = Number(positions[b3 + 2] ?? 0);
    const cx = Number(positions[c3] ?? 0);
    const cy = Number(positions[c3 + 1] ?? 0);
    const cz = Number(positions[c3 + 2] ?? 0);
    if (
      !Number.isFinite(ax) ||
      !Number.isFinite(ay) ||
      !Number.isFinite(az) ||
      !Number.isFinite(bx) ||
      !Number.isFinite(by) ||
      !Number.isFinite(bz) ||
      !Number.isFinite(cx) ||
      !Number.isFinite(cy) ||
      !Number.isFinite(cz)
    ) {
      continue;
    }
    const abx = bx - ax;
    const aby = by - ay;
    const abz = bz - az;
    const acx = cx - ax;
    const acy = cy - ay;
    const acz = cz - az;
    const crossX = aby * acz - abz * acy;
    const crossY = abz * acx - abx * acz;
    const crossZ = abx * acy - aby * acx;
    const area = 0.5 * Math.hypot(crossX, crossY, crossZ);
    if (Number.isFinite(area)) {
      surfaceArea += area;
    }
    const tetra6 = ax * (by * cz - bz * cy) + ay * (bz * cx - bx * cz) + az * (bx * cy - by * cx);
    if (Number.isFinite(tetra6)) {
      signedVolume += tetra6 / 6;
    }
    faceCount += 1;
  }
  const bounds = boundsFromPositions(positions);
  const dimensions = bounds
    ? {
        x: bounds.max[0] - bounds.min[0],
        y: bounds.max[1] - bounds.min[1],
        z: bounds.max[2] - bounds.min[2],
      }
    : null;
  return {
    vertexCount,
    faceCount,
    surfaceArea,
    volume: Math.abs(signedVolume),
    bounds,
    dimensions,
  };
};

const buildFundamentalDiagramPreview = (
  diagram: FundamentalDiagram,
  opts: { gluePhase?: number } = {}
): FundamentalDiagramPreview => {
  const width = 280;
  const height = 220;
  const pad = 24;
  const vertices = diagram.vertices;
  const gluePhase = clampNumber(opts.gluePhase ?? 0, 0, 1);
  const minX = vertices.reduce((acc, v) => Math.min(acc, v.x), Infinity);
  const maxX = vertices.reduce((acc, v) => Math.max(acc, v.x), -Infinity);
  const minY = vertices.reduce((acc, v) => Math.min(acc, v.y), Infinity);
  const maxY = vertices.reduce((acc, v) => Math.max(acc, v.y), -Infinity);
  const spanX = Math.max(1e-6, maxX - minX);
  const spanY = Math.max(1e-6, maxY - minY);
  const scale = Math.min((width - pad * 2) / spanX, (height - pad * 2) / spanY);
  const toView = (x: number, y: number) => ({
    x: pad + (x - minX) * scale,
    y: height - (pad + (y - minY) * scale),
  });
  const verticesView = vertices.map((vertex) => {
    const p = toView(vertex.x, vertex.y);
    return {
      id: vertex.id,
      x: p.x,
      y: p.y,
      label: diagram.vertexLabels[vertex.id] ?? vertex.id,
    };
  });
  const vertexById = new Map(verticesView.map((vertex) => [vertex.id, vertex]));
  const rawEdges = diagram.edges.flatMap((edge) => {
    const from = vertexById.get(edge.from);
    const to = vertexById.get(edge.to);
    if (!from || !to) return [];
    const orientation = diagram.edgeOrientations[edge.id] ?? 1;
    const start = orientation >= 0 ? from : to;
    const end = orientation >= 0 ? to : from;
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const len = Math.hypot(dx, dy);
    const nx = len > 1e-6 ? -dy / len : 0;
    const ny = len > 1e-6 ? dx / len : 0;
    const baseLabel = diagram.edgeLabels[edge.id]?.trim() || edge.id;
    const token = boundaryLabelToken(baseLabel);
    const label = orientation >= 0 ? baseLabel : `${baseLabel}^-1`;
    return [
      {
        id: edge.id,
        token,
        dx,
        dy,
        len,
        nx,
        ny,
        x1: start.x,
        y1: start.y,
        x2: end.x,
        y2: end.y,
        lx: (start.x + end.x) * 0.5 + nx * 11,
        ly: (start.y + end.y) * 0.5 + ny * 11,
        color: boundaryLabelColor(token),
        label,
        dashed: orientation < 0,
        opacity: 0.9,
        strokeWidth: 2.4,
      },
    ];
  });
  const labelCenterMap = new Map<string, { x: number; y: number; count: number }>();
  for (const edge of rawEdges) {
    if (!edge.token) continue;
    const prev = labelCenterMap.get(edge.token);
    const midX = (edge.x1 + edge.x2) * 0.5;
    const midY = (edge.y1 + edge.y2) * 0.5;
    if (!prev) {
      labelCenterMap.set(edge.token, { x: midX, y: midY, count: 1 });
      continue;
    }
    prev.x += midX;
    prev.y += midY;
    prev.count += 1;
  }
  for (const [token, center] of labelCenterMap.entries()) {
    if (center.count <= 0) continue;
    labelCenterMap.set(token, { x: center.x / center.count, y: center.y / center.count, count: center.count });
  }
  const animatedEdges =
    gluePhase <= 0
      ? []
      : rawEdges.map((edge) => {
          const center = edge.token ? labelCenterMap.get(edge.token) : null;
          if (!center || center.count <= 1) {
            return {
              id: edge.id,
              x1: edge.x1,
              y1: edge.y1,
              x2: edge.x2,
              y2: edge.y2,
              lx: edge.lx,
              ly: edge.ly,
              color: edge.color,
              label: edge.label,
              dashed: edge.dashed,
              opacity: 0.36,
              strokeWidth: 1.8,
            };
          }
          const midX = (edge.x1 + edge.x2) * 0.5;
          const midY = (edge.y1 + edge.y2) * 0.5;
          const targetMidX = midX + (center.x - midX) * gluePhase;
          const targetMidY = midY + (center.y - midY) * gluePhase;
          const dirX = edge.len > 1e-6 ? edge.dx / edge.len : 1;
          const dirY = edge.len > 1e-6 ? edge.dy / edge.len : 0;
          const edgeScale = 1 - 0.55 * gluePhase;
          const halfLen = Math.max(5, edge.len * edgeScale * 0.5);
          const x1 = targetMidX - dirX * halfLen;
          const y1 = targetMidY - dirY * halfLen;
          const x2 = targetMidX + dirX * halfLen;
          const y2 = targetMidY + dirY * halfLen;
          const nx = -dirY;
          const ny = dirX;
          return {
            id: edge.id,
            x1,
            y1,
            x2,
            y2,
            lx: targetMidX + nx * 9,
            ly: targetMidY + ny * 9,
            color: edge.color,
            label: edge.label,
            dashed: edge.dashed,
            opacity: 0.94,
            strokeWidth: 2.4,
          };
        });
  const faceId = diagram.faces[0]?.id ?? "";
  return {
    width,
    height,
    boundaryWord: diagram.faceBoundaryWords[faceId] ?? "",
    vertices: verticesView,
    edges: rawEdges.map((edge) => ({
      id: edge.id,
      x1: edge.x1,
      y1: edge.y1,
      x2: edge.x2,
      y2: edge.y2,
      lx: edge.lx,
      ly: edge.ly,
      color: edge.color,
      label: edge.label,
      dashed: edge.dashed,
      opacity: edge.opacity,
      strokeWidth: edge.strokeWidth,
    })),
    animatedEdges,
  };
};

