const formatHistoryNumber = (value: number): string => {
  if (!Number.isFinite(value)) return "0";
  const abs = Math.abs(value);
  if (abs >= 100) return value.toFixed(0);
  if (abs >= 10) return value.toFixed(1);
  return value.toFixed(2);
};

const formatHistoryVec3 = (value: { x: number; y: number; z: number }): string =>
  `(${formatHistoryNumber(value.x)}, ${formatHistoryNumber(value.y)}, ${formatHistoryNumber(value.z)})`;

const countTriangleMeshTopology = (mesh: {
  positions: ArrayLike<number>;
  indices?: ArrayLike<number> | null;
}): { vertexCount: number; faceCount: number } => {
  const vertexCount = Math.floor((mesh.positions?.length ?? 0) / 3);
  const faceCount =
    mesh.indices && mesh.indices.length >= 3
      ? Math.floor(mesh.indices.length / 3)
      : Math.floor((mesh.positions?.length ?? 0) / 9);
  return { vertexCount, faceCount };
};

const readMeshPoint = (
  mesh: { positions: ArrayLike<number> },
  index: number
): GeometryProbePoint | null => {
  const vertexCount = Math.floor((mesh.positions?.length ?? 0) / 3);
  if (!Number.isInteger(index) || index < 0 || index >= vertexCount) return null;
  const base = index * 3;
  const x = Number(mesh.positions[base]);
  const y = Number(mesh.positions[base + 1]);
  const z = Number(mesh.positions[base + 2]);
  if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) return null;
  return { x, y, z };
};

const findNearestMeshVertexIndex = (
  mesh: { positions: ArrayLike<number> },
  point: GeometryProbePoint
): number | null => {
  const vertexCount = Math.floor((mesh.positions?.length ?? 0) / 3);
  let bestIndex: number | null = null;
  let bestDistanceSq = Number.POSITIVE_INFINITY;
  for (let i = 0; i < vertexCount; i += 1) {
    const candidate = readMeshPoint(mesh, i);
    if (!candidate) continue;
    const dx = candidate.x - point.x;
    const dy = candidate.y - point.y;
    const dz = candidate.z - point.z;
    const d2 = dx * dx + dy * dy + dz * dz;
    if (d2 >= bestDistanceSq) continue;
    bestDistanceSq = d2;
    bestIndex = i;
  }
  return bestIndex;
};

const readMeshFaceVertexIndices = (
  mesh: { positions: ArrayLike<number>; indices?: ArrayLike<number> | null },
  faceIndex: number
): [number, number, number] | null => {
  const topology = countTriangleMeshTopology(mesh);
  if (!Number.isInteger(faceIndex) || faceIndex < 0 || faceIndex >= topology.faceCount) return null;
  if (mesh.indices && mesh.indices.length >= (faceIndex + 1) * 3) {
    const base = faceIndex * 3;
    const a = Number(mesh.indices[base]);
    const b = Number(mesh.indices[base + 1]);
    const c = Number(mesh.indices[base + 2]);
    if ([a, b, c].every((value) => Number.isInteger(value) && value >= 0 && value < topology.vertexCount)) {
      return [a, b, c];
    }
    return null;
  }
  const base = faceIndex * 3;
  if (base + 2 >= topology.vertexCount) return null;
  return [base, base + 1, base + 2];
};

const readMeshFacePolygon = (
  mesh: { positions: ArrayLike<number>; indices?: ArrayLike<number> | null },
  faceIndex: number
): Polygon3 | null => {
  const tri = readMeshFaceVertexIndices(mesh, faceIndex);
  if (!tri) return null;
  const vertices = tri.map((idx) => readMeshPoint(mesh, idx)).filter((point): point is GeometryProbePoint => !!point);
  return vertices.length === 3 ? { vertices } : null;
};

const findMeshEdgeIncidentFaceIndices = (
  mesh: { positions: ArrayLike<number>; indices?: ArrayLike<number> | null },
  edgeA: number,
  edgeB: number,
  maxFaces = 8
): number[] => {
  if (!Number.isInteger(edgeA) || !Number.isInteger(edgeB) || edgeA === edgeB) return [];
  const topology = countTriangleMeshTopology(mesh);
  if (edgeA < 0 || edgeB < 0 || edgeA >= topology.vertexCount || edgeB >= topology.vertexCount) return [];
  const result: number[] = [];
  for (let faceIndex = 0; faceIndex < topology.faceCount && result.length < maxFaces; faceIndex += 1) {
    const tri = readMeshFaceVertexIndices(mesh, faceIndex);
    if (!tri) continue;
    const hasA = tri[0] === edgeA || tri[1] === edgeA || tri[2] === edgeA;
    const hasB = tri[0] === edgeB || tri[1] === edgeB || tri[2] === edgeB;
    if (hasA && hasB) result.push(faceIndex);
  }
  return result;
};

type SurfaceMeshTopologyPick = {
  faceIndex: number;
  edgeA: number;
  edgeB: number;
  vertexIndex: number;
};
type SurfaceMeshTopologyPickMode = "object" | "face" | "edge" | "vertex";
type UnifiedSelectionTopologyFilterMode = "all" | "boundary" | "interior" | "non-manifold";
type UnifiedSelectionKindFilterState = Record<SurfaceMeshTopologyPickMode, boolean>;
const SURFACE_MESH_TOPOLOGY_PICK_MODES: readonly SurfaceMeshTopologyPickMode[] = ["object", "face", "edge", "vertex"];
const DEFAULT_UNIFIED_SELECTION_KIND_FILTERS: UnifiedSelectionKindFilterState = {
  object: true,
  face: true,
  edge: true,
  vertex: true,
};
const isSurfaceMeshTopologyPickMode = (value: unknown): value is SurfaceMeshTopologyPickMode =>
  value === "object" || value === "face" || value === "edge" || value === "vertex";
const normalizeSurfaceMeshTopologyPickMode = (value: unknown): SurfaceMeshTopologyPickMode | null => {
  if (value === "auto") return "object";
  return isSurfaceMeshTopologyPickMode(value) ? value : null;
};
const readStoredSurfaceMeshContextualPickMode = (): SurfaceMeshTopologyPickMode | null => {
  if (typeof window === "undefined") return null;
  try {
    const value = window.localStorage.getItem(UI_CONTEXTUAL_MESH_PICK_MODE_KEY);
    return normalizeSurfaceMeshTopologyPickMode(value);
  } catch {
    return null;
  }
};
const buildSurfaceMeshUnifiedSelectionFromPick = (
  mesh: SurfaceMeshData | null,
  meshLabel: string,
  pickMode: SurfaceMeshTopologyPickMode,
  pick: SurfaceMeshTopologyPick,
  lifecycle: "selected" | "hover" | "editing" | "preview" = "selected"
): UnifiedSelection | null => {
  const topology = mesh?.positions?.length ? countTriangleMeshTopology(mesh) : { vertexCount: 0, faceCount: 0 };
  const faceValid = pick.faceIndex >= 0 && pick.faceIndex < topology.faceCount;
  const edgeValid =
    !!mesh &&
    pick.edgeA !== pick.edgeB &&
    pick.edgeA >= 0 &&
    pick.edgeB >= 0 &&
    pick.edgeA < topology.vertexCount &&
    pick.edgeB < topology.vertexCount &&
    findMeshEdgeIncidentFaceIndices(mesh, pick.edgeA, pick.edgeB, 1).length > 0;
  const vertexValid = pick.vertexIndex >= 0 && pick.vertexIndex < topology.vertexCount;
  return unifiedSelectionFromMeshTopology(
    {
      mode: pickMode,
      objectId: `mesh:${meshLabel}`,
      objectLabel: meshLabel,
      meshKey: `mesh:${meshLabel}`,
      mesh,
      faceIndex: pick.faceIndex,
      edgeVertices: [pick.edgeA, pick.edgeB],
      vertexIndex: pick.vertexIndex,
      valid:
        pickMode === "object"
          ? Boolean(mesh)
          : pickMode === "face"
            ? faceValid
            : pickMode === "edge"
              ? edgeValid
              : vertexValid,
      selectionCleared: false,
    },
    lifecycle
  );
};
const buildSurfaceMeshShiftExpansionSelections = (
  mesh: SurfaceMeshData | null,
  meshLabel: string,
  pickMode: SurfaceMeshTopologyPickMode,
  pick: SurfaceMeshTopologyPick,
  anchor: UnifiedSelection | null | undefined
): UnifiedSelection[] => {
  const selected = buildSurfaceMeshUnifiedSelectionFromPick(mesh, meshLabel, pickMode, pick);
  if (!selected || !mesh?.positions?.length || pickMode === "object") return selected ? [selected] : [];
  const topology = countTriangleMeshTopology(mesh);
  const selections: UnifiedSelection[] = [];
  const pushPick = (nextPick: SurfaceMeshTopologyPick) => {
    const item = buildSurfaceMeshUnifiedSelectionFromPick(mesh, meshLabel, pickMode, nextPick);
    if (item) selections.push(item);
  };

  if (pickMode === "face") {
    const anchorFace = anchor?.selectionType === "face" ? anchor.faceId ?? null : null;
    if (anchorFace != null && anchorFace >= 0 && anchorFace < topology.faceCount) {
      const min = Math.max(0, Math.min(anchorFace, pick.faceIndex));
      const max = Math.min(topology.faceCount - 1, Math.max(anchorFace, pick.faceIndex));
      for (let faceIndex = min; faceIndex <= max && selections.length < 250; faceIndex += 1) {
        const tri = readMeshFaceVertexIndices(mesh, faceIndex);
        pushPick({
          faceIndex,
          edgeA: tri?.[0] ?? pick.edgeA,
          edgeB: tri?.[1] ?? pick.edgeB,
          vertexIndex: tri?.[0] ?? pick.vertexIndex,
        });
      }
      return selections.length ? selections : [selected];
    }
    pushPick(pick);
    for (const faceIndex of selected.topology.adjacentFaces.slice(0, 64)) {
      const tri = readMeshFaceVertexIndices(mesh, faceIndex);
      if (tri) pushPick({ faceIndex, edgeA: tri[0], edgeB: tri[1], vertexIndex: tri[0] });
    }
    return selections.length ? selections : [selected];
  }

  if (pickMode === "edge") {
    const incidentFaces = findMeshEdgeIncidentFaceIndices(mesh, pick.edgeA, pick.edgeB, 12);
    const seen = new Set<string>();
    for (const faceIndex of incidentFaces) {
      const tri = readMeshFaceVertexIndices(mesh, faceIndex);
      if (!tri) continue;
      for (const [edgeA, edgeB] of [[tri[0], tri[1]], [tri[1], tri[2]], [tri[2], tri[0]]] as const) {
        const key = edgeA < edgeB ? `${edgeA}:${edgeB}` : `${edgeB}:${edgeA}`;
        if (seen.has(key)) continue;
        seen.add(key);
        pushPick({ faceIndex, edgeA, edgeB, vertexIndex: edgeA });
      }
    }
    return selections.length ? selections : [selected];
  }

  if (pickMode === "vertex") {
    const vertexIds = new Set<number>([pick.vertexIndex, ...selected.topology.adjacentVertices]);
    for (const vertexIndex of Array.from(vertexIds).slice(0, 250)) {
      if (vertexIndex < 0 || vertexIndex >= topology.vertexCount) continue;
      pushPick({ faceIndex: pick.faceIndex, edgeA: pick.edgeA, edgeB: pick.edgeB, vertexIndex });
    }
    return selections.length ? selections : [selected];
  }

  return [selected];
};
type SurfaceMeshTopologyHistoryEntry = {
  id: string;
  at: number;
  actionLabel: string;
  sourceLabel: string;
  targetLabel: string;
  paramsLabel: string;
  definition: MeshTopologyEditDefinition;
  resultLabel: string;
  beforeCounts: { vertexCount: number; faceCount: number };
  afterCounts: { vertexCount: number; faceCount: number };
  selectedResultLabel: string;
  beforeSnapshot: SurfaceMeshData;
  snapshot: SurfaceMeshData;
};
type SurfaceMeshTopologyOperationTarget = {
  faceIndex: number | null;
  edge: [number, number] | null;
  vertexIndex: number | null;
};
type OperationNodeParameterDrafts = UnifiedOperationNodeParameterDrafts;
const surfaceMeshTopologyOperationFromAction = (actionLabel: string): SurfaceMeshTopologyOperation | null => {
  const normalized = actionLabel.trim().toLowerCase();
  if (normalized.includes("extrude")) return "Extrude Face";
  if (normalized.includes("inset")) return "Inset Face";
  if (normalized.includes("subdivide")) return "Face Subdivide";
  if (normalized.includes("split")) return "Split Edge";
  if (normalized.includes("collapse")) return "Collapse Edge";
  if (normalized.includes("bevel")) return "Bevel Edge";
  if (normalized.includes("move")) return "Move Vertex";
  return null;
};
const parseSurfaceMeshTopologyOperationTarget = (targetLabel: string): SurfaceMeshTopologyOperationTarget => {
  const faceMatch = targetLabel.match(/\bface\s+(\d+)/i);
  const edgeMatch = targetLabel.match(/\bedge\s+(\d+)\s*-\s*(\d+)/i);
  const vertexMatch = targetLabel.match(/\bvertex\s+(\d+)/i);
  return {
    faceIndex: faceMatch ? Number(faceMatch[1]) : null,
    edge: edgeMatch ? [Number(edgeMatch[1]), Number(edgeMatch[2])] : null,
    vertexIndex: vertexMatch ? Number(vertexMatch[1]) : null,
  };
};
const surfaceMeshTopologyParametersFromLabel = (
  operation: SurfaceMeshTopologyOperation,
  paramsLabel: string
): MeshTopologyEditParameters => {
  if (operation === "Extrude Face") {
    const distance = Number(paramsLabel.match(/distance=([+-]?(?:\d+\.?\d*|\.\d+))/)?.[1] ?? 0.08);
    return { distance: Number.isFinite(distance) ? distance : 0.08 };
  }
  if (operation === "Inset Face") {
    const ratio = Number(paramsLabel.match(/ratio=([+-]?(?:\d+\.?\d*|\.\d+))/)?.[1] ?? 0.2);
    return { ratio: clampNumber(ratio, 0.02, 0.92) };
  }
  if (operation === "Face Subdivide") {
    const mode = paramsLabel.includes("four-triangles") ? "four-triangles" : "center-fan";
    return { mode };
  }
  if (operation === "Split Edge") {
    const ratio = Number(paramsLabel.match(/ratio=([+-]?(?:\d+\.?\d*|\.\d+))/)?.[1] ?? 0.5);
    return { ratio: clampNumber(ratio, 0.01, 0.99) };
  }
  if (operation === "Collapse Edge") {
    const modeMatch = paramsLabel.match(/mode=([A-Za-z-]+)/)?.[1];
    const mode: EdgeCollapseMode =
      modeMatch === "keep-a" || modeMatch === "keep-b" || modeMatch === "midpoint" ? modeMatch : "midpoint";
    return { mode };
  }
  if (operation === "Move Vertex") {
    const amount = Number(paramsLabel.match(/amount=([+-]?(?:\d+\.?\d*|\.\d+))/)?.[1] ?? 0.06);
    const dirX = Number(paramsLabel.match(/dirX=([+-]?(?:\d+\.?\d*|\.\d+))/)?.[1] ?? NaN);
    const dirY = Number(paramsLabel.match(/dirY=([+-]?(?:\d+\.?\d*|\.\d+))/)?.[1] ?? NaN);
    const dirZ = Number(paramsLabel.match(/dirZ=([+-]?(?:\d+\.?\d*|\.\d+))/)?.[1] ?? NaN);
    const direction =
      Number.isFinite(dirX) && Number.isFinite(dirY) && Number.isFinite(dirZ)
        ? { x: dirX, y: dirY, z: dirZ }
        : null;
    return { amount: Math.max(0.001, Number.isFinite(amount) ? Math.abs(amount) : 0.06), direction };
  }
  const amount = Number(paramsLabel.match(/amount=([+-]?(?:\d+\.?\d*|\.\d+))/)?.[1] ?? 0.06);
  return { amount: Math.max(0.001, Number.isFinite(amount) ? amount : 0.06) };
};
const surfaceMeshTopologyTargetFromLabel = (
  operation: SurfaceMeshTopologyOperation,
  targetLabel: string
): MeshTopologyEditTarget => {
  const target = parseSurfaceMeshTopologyOperationTarget(targetLabel);
  if (operation === "Face Subdivide" || operation === "Extrude Face" || operation === "Inset Face") {
    return createMeshTopologyFaceTarget(target.faceIndex ?? 0);
  }
  if (operation === "Move Vertex") return createMeshTopologyVertexTarget(target.vertexIndex ?? 0);
  const edge = target.edge ?? [0, 1];
  return createMeshTopologyEdgeTarget(edge[0], edge[1]);
};
const buildSurfaceMeshTopologyDefinition = ({
  actionLabel,
  sourceLabel,
  targetLabel,
  paramsLabel,
  beforeCounts,
}: {
  actionLabel: string;
  sourceLabel: string;
  targetLabel: string;
  paramsLabel: string;
  beforeCounts: { vertexCount: number; faceCount: number };
}): MeshTopologyEditDefinition => {
  const operation = surfaceMeshTopologyOperationFromAction(actionLabel) ?? "Split Edge";
  return createMeshTopologyEditDefinition({
    operation,
    sourceMeshVersion: createMeshTopologySourceVersion({
      label: sourceLabel,
      vertexCount: beforeCounts.vertexCount,
      faceCount: beforeCounts.faceCount,
    }),
    target: surfaceMeshTopologyTargetFromLabel(operation, targetLabel),
    parameters: surfaceMeshTopologyParametersFromLabel(operation, paramsLabel),
  });
};
const surfaceMeshTopologyActionLabelFromDefinition = (definition: MeshTopologyEditDefinition): string =>
  definition.operation === "Face Subdivide"
    ? "Face subdivide"
    : definition.operation === "Extrude Face"
      ? "Extrude face"
      : definition.operation === "Inset Face"
        ? "Inset face"
        : definition.operation === "Split Edge"
          ? "Split edge"
          : definition.operation === "Collapse Edge"
            ? "Collapse edge"
            : definition.operation === "Move Vertex"
              ? "Move vertex"
              : "Bevel edge";
const surfaceMeshTopologyTraceActionFromDefinition = (definition: MeshTopologyEditDefinition): string =>
  definition.operation === "Face Subdivide"
    ? "face-subdivide"
    : definition.operation === "Extrude Face"
      ? "face-extrude"
      : definition.operation === "Inset Face"
        ? "face-inset"
        : definition.operation === "Split Edge"
          ? "edge-split"
          : definition.operation === "Collapse Edge"
            ? "edge-collapse"
            : definition.operation === "Move Vertex"
              ? "vertex-move"
              : "edge-bevel";
const surfaceMeshTopologySelectedResultLabelFromDefinition = (definition: MeshTopologyEditDefinition): string => {
  if (definition.operation === "Face Subdivide") {
    return "mode" in definition.parameters && definition.parameters.mode === "four-triangles"
      ? "four-triangle split"
      : "center fan triangles";
  }
  if (definition.operation === "Extrude Face") return `extruded ${definition.target.label}`;
  if (definition.operation === "Inset Face") return `inset ${definition.target.label}`;
  if (definition.operation === "Move Vertex") return `moved ${definition.target.label}`;
  if (definition.target.kind !== "edge") return definition.target.label;
  const edgeLabel = definition.target.label;
  if (definition.operation === "Split Edge") return `midpoint vertex on ${edgeLabel}`;
  if (definition.operation === "Collapse Edge") {
    const mode = "mode" in definition.parameters ? definition.parameters.mode : "midpoint";
    return mode === "keep-a"
      ? `merged vertex ${definition.target.edge[0]}`
      : mode === "keep-b"
        ? `merged vertex ${definition.target.edge[1]}`
        : "midpoint vertex";
  }
  return `bevel band from ${edgeLabel}`;
};
const updateSurfaceMeshTopologyDefinitionParameter = (
  definition: MeshTopologyEditDefinition,
  key: string,
  value: UnifiedCommandParameterValue
): MeshTopologyEditDefinition => {
  if (definition.operation === "Face Subdivide" && key === "mode") {
    const mode: FaceSubdivideMode = value === "four-triangles" ? "four-triangles" : "center-fan";
    return updateMeshTopologyEditDefinitionParameters(definition, { mode });
  }
  if (definition.operation === "Extrude Face" && key === "distance") {
    const distance = typeof value === "number" ? value : Number(value);
    return updateMeshTopologyEditDefinitionParameters(definition, {
      distance: Number.isFinite(distance) ? distance : 0.08,
    });
  }
  if (definition.operation === "Inset Face" && key === "ratio") {
    const ratio = typeof value === "number" ? value : Number(value);
    return updateMeshTopologyEditDefinitionParameters(definition, {
      ratio: clampNumber(Number.isFinite(ratio) ? ratio : 0.2, 0.02, 0.92),
    });
  }
  if (definition.operation === "Split Edge" && key === "ratio") {
    const ratio = typeof value === "number" ? value : Number(value);
    return updateMeshTopologyEditDefinitionParameters(definition, {
      ratio: clampNumber(Number.isFinite(ratio) ? ratio : 0.5, 0.01, 0.99),
    });
  }
  if (definition.operation === "Collapse Edge" && key === "mode") {
    const mode: EdgeCollapseMode = value === "keep-a" || value === "keep-b" || value === "midpoint" ? value : "midpoint";
    return updateMeshTopologyEditDefinitionParameters(definition, { mode });
  }
  if (definition.operation === "Bevel Edge" && key === "amount") {
    const amount = typeof value === "number" ? value : Number(value);
    return updateMeshTopologyEditDefinitionParameters(definition, {
      amount: Math.max(0.001, Number.isFinite(amount) ? amount : 0.06),
    });
  }
  if (definition.operation === "Move Vertex" && key === "amount") {
    const amount = typeof value === "number" ? value : Number(value);
    const direction = "amount" in definition.parameters ? definition.parameters.direction : null;
    return updateMeshTopologyEditDefinitionParameters(definition, {
      amount: Math.max(0.001, Number.isFinite(amount) ? Math.abs(amount) : 0.06),
      direction,
    });
  }
  return definition;
};
