const isStoredMeshTopologyEditDefinition = (value: unknown): value is MeshTopologyEditDefinition => {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Partial<MeshTopologyEditDefinition>;
  return (
    typeof candidate.operation === "string" &&
    !!candidate.sourceMeshVersion &&
    typeof candidate.sourceMeshVersion.key === "string" &&
    !!candidate.target &&
    typeof candidate.target.key === "string" &&
    !!candidate.parameters &&
    typeof candidate.selectionKey === "string" &&
    typeof candidate.replayLabel === "string"
  );
};

const isStoredGeometryTopologyEditDefinition = (value: unknown): value is GeometryTopologyEditDefinition => {
  if (!value || typeof value !== "object") return false;
  const candidate = value as Partial<GeometryTopologyEditDefinition>;
  return (
    typeof candidate.operation === "string" &&
    !!candidate.sourceObjectVersion &&
    typeof candidate.sourceObjectVersion.key === "string" &&
    typeof candidate.sourceObjectVersion.objectId === "string" &&
    !!candidate.target &&
    typeof candidate.target.key === "string" &&
    !!candidate.parameters &&
    typeof candidate.selectionKey === "string" &&
    typeof candidate.replayLabel === "string"
  );
};

const serializeTopologySurfaceMeshData = (mesh: SurfaceMeshData): TopologySerializedSurfaceMeshData => ({
  label: mesh.label,
  positions: Array.from(mesh.positions),
  indices: mesh.indices ? Array.from(mesh.indices) : null,
  normals: mesh.normals ? Array.from(mesh.normals) : null,
  uvs: mesh.uvs ? Array.from(mesh.uvs) : null,
  source: mesh.source,
  adjacency: mesh.adjacency ? mesh.adjacency.map((row) => row.slice()) : null,
  meanEdgeLength: mesh.meanEdgeLength ?? null,
  validation: mesh.validation
    ? {
        ...mesh.validation,
        errors: [...mesh.validation.errors],
        warnings: [...mesh.validation.warnings],
        stats: { ...mesh.validation.stats },
      }
    : null,
});

const deserializeTopologySurfaceMeshData = (
  mesh: TopologySerializedSurfaceMeshData | null | undefined
): SurfaceMeshData | null => {
  if (!mesh || !Array.isArray(mesh.positions) || mesh.positions.length < 9 || mesh.positions.length % 3 !== 0) {
    return null;
  }
  const indices = Array.isArray(mesh.indices) && mesh.indices.length >= 3 ? Uint32Array.from(mesh.indices) : null;
  return {
    label: typeof mesh.label === "string" && mesh.label.trim() ? mesh.label : "Surface mesh",
    positions: Float32Array.from(mesh.positions),
    indices,
    normals: Array.isArray(mesh.normals) && mesh.normals.length ? Float32Array.from(mesh.normals) : null,
    uvs: Array.isArray(mesh.uvs) && mesh.uvs.length ? Float32Array.from(mesh.uvs) : null,
    source: mesh.source ?? { kind: "detachedMesh" },
    adjacency: Array.isArray(mesh.adjacency) ? mesh.adjacency.map((row) => (Array.isArray(row) ? row.slice() : [])) : null,
    meanEdgeLength: typeof mesh.meanEdgeLength === "number" ? mesh.meanEdgeLength : null,
    validation: mesh.validation ?? null,
  };
};

const serializeSurfaceMeshTopologyHistoryEntry = (
  entry: SurfaceMeshTopologyHistoryEntry
): StoredSurfaceMeshTopologyHistoryEntry => ({
  ...entry,
  beforeSnapshot: serializeTopologySurfaceMeshData(entry.beforeSnapshot),
  snapshot: serializeTopologySurfaceMeshData(entry.snapshot),
});

const deserializeSurfaceMeshTopologyHistoryEntry = (
  entry: StoredSurfaceMeshTopologyHistoryEntry | null | undefined
): SurfaceMeshTopologyHistoryEntry | null => {
  if (!entry || typeof entry.id !== "string") return null;
  const beforeSnapshot = deserializeTopologySurfaceMeshData(entry.beforeSnapshot);
  const snapshot = deserializeTopologySurfaceMeshData(entry.snapshot);
  if (!beforeSnapshot || !snapshot) return null;
  return {
    id: entry.id,
    at: Number.isFinite(entry.at) ? entry.at : Date.now(),
    actionLabel: typeof entry.actionLabel === "string" ? entry.actionLabel : "Topology edit",
    sourceLabel: typeof entry.sourceLabel === "string" ? entry.sourceLabel : "Surface mesh",
    targetLabel: typeof entry.targetLabel === "string" ? entry.targetLabel : "target",
    paramsLabel: typeof entry.paramsLabel === "string" ? entry.paramsLabel : "params",
    definition:
      isStoredMeshTopologyEditDefinition(entry.definition)
        ? entry.definition
        : buildSurfaceMeshTopologyDefinition({
            actionLabel: typeof entry.actionLabel === "string" ? entry.actionLabel : "Topology edit",
            sourceLabel: typeof entry.sourceLabel === "string" ? entry.sourceLabel : "Surface mesh",
            targetLabel: typeof entry.targetLabel === "string" ? entry.targetLabel : "target",
            paramsLabel: typeof entry.paramsLabel === "string" ? entry.paramsLabel : "params",
            beforeCounts: entry.beforeCounts ?? {
              vertexCount: Math.floor(beforeSnapshot.positions.length / 3),
              faceCount:
                beforeSnapshot.indices && beforeSnapshot.indices.length >= 3
                  ? Math.floor(beforeSnapshot.indices.length / 3)
                  : Math.floor(Math.floor(beforeSnapshot.positions.length / 3) / 3),
            },
          }),
    resultLabel: typeof entry.resultLabel === "string" ? entry.resultLabel : "edited mesh",
    beforeCounts: entry.beforeCounts,
    afterCounts: entry.afterCounts,
    selectedResultLabel: typeof entry.selectedResultLabel === "string" ? entry.selectedResultLabel : "edited result",
    beforeSnapshot,
    snapshot,
  };
};

const serializeGeometryObjectHistoryStep = (step: GeometryObjectHistoryStep): StoredGeometryObjectHistoryStep => ({
  ...step,
  topologyDefinition: step.topologyDefinition ?? null,
  topologyDefinitionSourceSnapshot: step.topologyDefinitionSourceSnapshot
    ? serializeTopologySurfaceMeshData(step.topologyDefinitionSourceSnapshot)
    : null,
  snapshot: serializeVariantSnapshot(step.snapshot),
});

const serializeGeometryObjectHistoryById = (
  historyById: Record<string, GeometryObjectHistoryStep[]>,
  limitPerObject = 24
): StoredGeometryObjectHistoryById => {
  const stored: StoredGeometryObjectHistoryById = {};
  for (const [objectId, history] of Object.entries(historyById)) {
    if (!Array.isArray(history) || !history.length) continue;
    stored[objectId] = history.slice(0, limitPerObject).map(serializeGeometryObjectHistoryStep);
  }
  return stored;
};

const deserializeGeometryObjectHistoryStep = (
  entry: StoredGeometryObjectHistoryStep | null | undefined
): GeometryObjectHistoryStep | null => {
  if (!entry || typeof entry.id !== "string") return null;
  if (!entry.snapshot || typeof entry.snapshot !== "object") return null;
  let snapshot: GeometryObject | GeometryDatasetMeshObject;
  try {
    snapshot = deserializeVariantSnapshot(entry.snapshot);
  } catch {
    return null;
  }
  const sourceSnapshot = deserializeTopologySurfaceMeshData(entry.topologyDefinitionSourceSnapshot);
  return {
    id: entry.id,
    at: Number.isFinite(entry.at) ? entry.at : Date.now(),
    action: typeof entry.action === "string" ? entry.action : "history",
    label: typeof entry.label === "string" ? entry.label : "Geometry edit",
    operationType: typeof entry.operationType === "string" ? entry.operationType : "History",
    operationTarget: typeof entry.operationTarget === "string" ? entry.operationTarget : null,
    operationParameters: typeof entry.operationParameters === "string" ? entry.operationParameters : null,
    destructive: Boolean(entry.destructive),
    warning: typeof entry.warning === "string" ? entry.warning : null,
    objectId: typeof entry.objectId === "string" ? entry.objectId : snapshot.id,
    objectName: typeof entry.objectName === "string" ? entry.objectName : snapshot.name,
    sourceObjectId: typeof entry.sourceObjectId === "string" ? entry.sourceObjectId : null,
    sourceObjectName: typeof entry.sourceObjectName === "string" ? entry.sourceObjectName : null,
    beforeVertexCount: typeof entry.beforeVertexCount === "number" ? entry.beforeVertexCount : null,
    afterVertexCount: typeof entry.afterVertexCount === "number" ? entry.afterVertexCount : null,
    beforeFaceCount: typeof entry.beforeFaceCount === "number" ? entry.beforeFaceCount : null,
    afterFaceCount: typeof entry.afterFaceCount === "number" ? entry.afterFaceCount : null,
    beforeSummary: typeof entry.beforeSummary === "string" ? entry.beforeSummary : null,
    afterSummary: typeof entry.afterSummary === "string" ? entry.afterSummary : summarizeGeometryHistorySnapshot(snapshot),
    changeSummary: typeof entry.changeSummary === "string" ? entry.changeSummary : "Restored history step",
    topologySummary: typeof entry.topologySummary === "string" ? entry.topologySummary : null,
    retainedSelection: entry.retainedSelection ?? null,
    topologyDefinition: isStoredGeometryTopologyEditDefinition(entry.topologyDefinition) ? entry.topologyDefinition : null,
    topologyDefinitionSourceSnapshot: sourceSnapshot,
    topologyDefinitionEnabled:
      isStoredGeometryTopologyEditDefinition(entry.topologyDefinition) ? entry.topologyDefinitionEnabled !== false : undefined,
    topologyDefinitionOrder:
      isStoredGeometryTopologyEditDefinition(entry.topologyDefinition) && Number.isFinite(entry.topologyDefinitionOrder)
        ? Number(entry.topologyDefinitionOrder)
        : undefined,
    snapshot,
  };
};

const deserializeGeometryObjectHistoryById = (stored: unknown): Record<string, GeometryObjectHistoryStep[]> => {
  const result: Record<string, GeometryObjectHistoryStep[]> = {};
  if (!stored || typeof stored !== "object") return result;
  for (const [objectId, history] of Object.entries(stored as StoredGeometryObjectHistoryById)) {
    if (!Array.isArray(history)) continue;
    const restored = history
      .map(deserializeGeometryObjectHistoryStep)
      .filter((entry): entry is GeometryObjectHistoryStep => !!entry)
      .slice(0, 24);
    if (restored.length) result[objectId] = restored;
  }
  return result;
};

const remapGeometryTopologyDefinitionForObject = (
  definition: GeometryTopologyEditDefinition | null | undefined,
  objectId: string,
  objectName: string,
  sourceSnapshot: SurfaceMeshData | null | undefined
): GeometryTopologyEditDefinition | null => {
  if (!definition) return null;
  if (!sourceSnapshot) return definition;
  return createGeometryTopologyEditDefinition({
    operation: definition.operation,
    sourceObjectVersion: createGeometryTopologySourceVersionFromMesh({
      objectId,
      label: objectName,
      revision: definition.sourceObjectVersion.revision,
      mesh: sourceSnapshot,
    }),
    target: definition.target,
    parameters: definition.parameters,
  });
};

const remapGeometryObjectHistoryForObject = (
  history: readonly GeometryObjectHistoryStep[] | null | undefined,
  objectId: string,
  objectName: string
): GeometryObjectHistoryStep[] =>
  (history ?? []).slice(0, 24).map((step) => {
    const snapshot = cloneGeometrySceneObjectSnapshot(step.snapshot);
    snapshot.id = objectId;
    snapshot.name = objectName;
    const sourceSnapshot = step.topologyDefinitionSourceSnapshot
      ? cloneSurfaceMeshData(step.topologyDefinitionSourceSnapshot, step.topologyDefinitionSourceSnapshot.label)
      : null;
    const topologyDefinition = remapGeometryTopologyDefinitionForObject(
      step.topologyDefinition,
      objectId,
      objectName,
      sourceSnapshot
    );
    return {
      ...step,
      id: makeId(),
      objectId,
      objectName,
      operationTarget: topologyDefinition?.target.label ?? step.operationTarget,
      operationParameters: topologyDefinition?.paramsLabel ?? step.operationParameters,
      topologyDefinition,
      topologyDefinitionSourceSnapshot: sourceSnapshot,
      topologyDefinitionEnabled: topologyDefinition ? step.topologyDefinitionEnabled !== false : undefined,
      topologyDefinitionOrder: topologyDefinition ? step.topologyDefinitionOrder : undefined,
      snapshot,
    };
  });

const readStoredSurfaceMeshTopologySession = (): RestoredSurfaceMeshTopologySession | null => {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(SURFACE_MESH_TOPOLOGY_SESSION_KEY);
    if (!raw || raw.length > SURFACE_MESH_TOPOLOGY_SESSION_MAX_CHARS) return null;
    const stored = safeParseObject<StoredSurfaceMeshTopologySession>(raw);
    if (!stored || stored.version !== 1 || !Number.isFinite(stored.savedAt)) return null;
    if (Date.now() - stored.savedAt > 1000 * 60 * 60 * 24 * 14) return null;
    const activeMesh = deserializeTopologySurfaceMeshData(stored.activeMesh);
    if (!activeMesh) return null;
    const history = (Array.isArray(stored.history) ? stored.history : [])
      .map(deserializeSurfaceMeshTopologyHistoryEntry)
      .filter((entry): entry is SurfaceMeshTopologyHistoryEntry => !!entry)
      .slice(0, SURFACE_MESH_TOPOLOGY_PERSIST_HISTORY_LIMIT);
    return {
      ...stored,
      activeMesh,
      history,
      selectedHistoryId:
        typeof stored.selectedHistoryId === "string" &&
        history.some((entry) => entry.id === stored.selectedHistoryId)
          ? stored.selectedHistoryId
          : history[0]?.id ?? null,
    };
  } catch {
    return null;
  }
};

const readStoredSurfaceMeshTopologySavedPresets = (): SurfaceMeshTopologySavedPreset[] => {
  if (typeof window === "undefined") return [];
  try {
    return safeParseArray<SurfaceMeshTopologySavedPreset>(
      window.localStorage.getItem(SURFACE_MESH_TOPOLOGY_SAVED_PRESETS_KEY)
    )
      .filter((entry) => typeof entry.id === "string" && typeof entry.name === "string")
      .filter((entry) => !!deserializeTopologySurfaceMeshData(entry.mesh))
      .slice(0, SURFACE_MESH_TOPOLOGY_SAVED_PRESET_LIMIT);
  } catch {
    return [];
  }
};

const distancePointToSegmentSq = (point: THREE.Vector3, a: THREE.Vector3, b: THREE.Vector3): number => {
  const ab = new THREE.Vector3().subVectors(b, a);
  const abLenSq = ab.lengthSq();
  if (abLenSq <= 1e-16) return point.distanceToSquared(a);
  const t = clampNumber(new THREE.Vector3().subVectors(point, a).dot(ab) / abLenSq, 0, 1);
  const closest = new THREE.Vector3().copy(a).addScaledVector(ab, t);
  return point.distanceToSquared(closest);
};

const resolveSurfaceMeshTopologyPick = (
  mesh: SurfaceMeshData | null,
  point: GeometryProbePoint | null | undefined
): SurfaceMeshTopologyPick | null => {
  if (!mesh?.positions?.length || !point) return null;
  const topology = countTriangleMeshTopology(mesh);
  if (topology.vertexCount <= 0 || topology.faceCount <= 0) return null;
  const pickPoint = new THREE.Vector3(point.x, point.y, point.z);

  let vertexIndex = 0;
  let bestVertexDistSq = Number.POSITIVE_INFINITY;
  for (let i = 0; i < topology.vertexCount; i += 1) {
    const vertex = readMeshPoint(mesh, i);
    if (!vertex) continue;
    const distSq = pickPoint.distanceToSquared(new THREE.Vector3(vertex.x, vertex.y, vertex.z));
    if (distSq < bestVertexDistSq) {
      bestVertexDistSq = distSq;
      vertexIndex = i;
    }
  }

  let faceIndex = 0;
  let bestFaceDistSq = Number.POSITIVE_INFINITY;
  const tmpClosest = new THREE.Vector3();
  for (let i = 0; i < topology.faceCount; i += 1) {
    const polygon = readMeshFacePolygon(mesh, i);
    if (!polygon || polygon.vertices.length !== 3) continue;
    const [a, b, c] = polygon.vertices;
    const triangle = new THREE.Triangle(
      new THREE.Vector3(a.x, a.y, a.z),
      new THREE.Vector3(b.x, b.y, b.z),
      new THREE.Vector3(c.x, c.y, c.z)
    );
    triangle.closestPointToPoint(pickPoint, tmpClosest);
    const distSq = tmpClosest.distanceToSquared(pickPoint);
    if (distSq < bestFaceDistSq) {
      bestFaceDistSq = distSq;
      faceIndex = i;
    }
  }

  const tri = readMeshFaceVertexIndices(mesh, faceIndex);
  if (!tri) return null;
  const edgeCandidates: Array<[number, number]> = [
    [tri[0], tri[1]],
    [tri[1], tri[2]],
    [tri[2], tri[0]],
  ];
  let edgeA = edgeCandidates[0][0];
  let edgeB = edgeCandidates[0][1];
  let bestEdgeDistSq = Number.POSITIVE_INFINITY;
  for (const [aIndex, bIndex] of edgeCandidates) {
    const a = readMeshPoint(mesh, aIndex);
    const b = readMeshPoint(mesh, bIndex);
    if (!a || !b) continue;
    const distSq = distancePointToSegmentSq(
      pickPoint,
      new THREE.Vector3(a.x, a.y, a.z),
      new THREE.Vector3(b.x, b.y, b.z)
    );
    if (distSq < bestEdgeDistSq) {
      bestEdgeDistSq = distSq;
      edgeA = aIndex;
      edgeB = bIndex;
    }
  }

  return { faceIndex, edgeA, edgeB, vertexIndex };
};

const findChangedMeshFaceIndices = (
  before: SurfaceMeshData,
  after: SurfaceMeshData,
  maxFaces = 12
): number[] => {
  const beforeTopology = countTriangleMeshTopology(before);
  const afterTopology = countTriangleMeshTopology(after);
  const changed: number[] = [];
  const sameTri = (faceIndex: number) => {
    const a = readMeshFaceVertexIndices(before, faceIndex);
    const b = readMeshFaceVertexIndices(after, faceIndex);
    return !!a && !!b && a[0] === b[0] && a[1] === b[1] && a[2] === b[2];
  };
  for (let i = 0; i < afterTopology.faceCount && changed.length < maxFaces; i += 1) {
    if (i >= beforeTopology.faceCount || !sameTri(i)) changed.push(i);
  }
  return changed;
};

const buildTopologyEditSummary = (
  action: string,
  target: string | null | undefined,
  beforeCounts: { vertexCount: number; faceCount: number },
  afterCounts: { vertexCount: number; faceCount: number }
): string => {
  const subject = target ?? "Selected topology";
  const vertexDelta = afterCounts.vertexCount - beforeCounts.vertexCount;
  const faceDelta = afterCounts.faceCount - beforeCounts.faceCount;
  const countTail = `V ${beforeCounts.vertexCount}->${afterCounts.vertexCount}, F ${beforeCounts.faceCount}->${afterCounts.faceCount}`;
  const deltaTail = `${vertexDelta >= 0 ? "+" : ""}${vertexDelta}V, ${faceDelta >= 0 ? "+" : ""}${faceDelta}F`;
  if (action === "face-subdivide") return `${subject} -> subdivided triangles (${deltaTail})`;
  if (action === "edge-split") return `${subject} -> split vertex (${deltaTail})`;
  if (action === "edge-collapse") return `${subject} -> merged vertex (${countTail})`;
  if (action === "face-extrude") return `${subject} -> cap + side faces (${deltaTail})`;
  if (action === "face-inset") return `${subject} -> inset face + rim (${deltaTail})`;
  if (action === "face-delete") return `${subject} -> removed (${deltaTail})`;
  if (action === "edge-bevel") return `${subject} -> offset edge endpoints (${countTail})`;
  if (action === "vertex-move") return `${subject} -> moved vertex (${countTail})`;
  if (action === "vertex-weld") return `${subject} -> merged vertices (${countTail})`;
  return `${subject} -> topology updated (${countTail})`;
};

const buildTopologyEditFeedback = (
  objectId: string,
  action: string,
  target: string | null | undefined,
  beforeMesh: SurfaceMeshData,
  afterMesh: SurfaceMeshData,
  transformedAfterMesh: SurfaceMeshData
): GeometryTopologyEditFeedback => {
  const beforeCounts = countTriangleMeshTopology(beforeMesh);
  const afterCounts = countTriangleMeshTopology(afterMesh);
  const points: GeometryProbePoint[] = [];
  const beforeVertexCount = beforeCounts.vertexCount;
  const afterVertexCount = afterCounts.vertexCount;
  const movedLimit = Math.min(beforeVertexCount, afterVertexCount);
  for (let i = 0; i < movedLimit && points.length < 18; i += 1) {
    const beforeBase = i * 3;
    const afterBase = i * 3;
    const dx = Number(beforeMesh.positions[beforeBase]) - Number(afterMesh.positions[afterBase]);
    const dy = Number(beforeMesh.positions[beforeBase + 1]) - Number(afterMesh.positions[afterBase + 1]);
    const dz = Number(beforeMesh.positions[beforeBase + 2]) - Number(afterMesh.positions[afterBase + 2]);
    if (dx * dx + dy * dy + dz * dz > 1e-10) {
      const point = readMeshPoint(transformedAfterMesh, i);
      if (point) points.push(point);
    }
  }
  for (let i = beforeVertexCount; i < afterVertexCount && points.length < 18; i += 1) {
    const point = readMeshPoint(transformedAfterMesh, i);
    if (point) points.push(point);
  }

  const changedFaceIndices = findChangedMeshFaceIndices(beforeMesh, afterMesh, 14);
  const facePolygons = changedFaceIndices
    .map((faceIndex) => readMeshFacePolygon(transformedAfterMesh, faceIndex))
    .filter((polygon): polygon is Polygon3 => !!polygon);
  const feedbackNormal =
    facePolygons.length > 0
      ? geometryNormalizeVec(polygonNormalFromVertices(facePolygons[0].vertices) ?? { x: 0, y: 1, z: 0 })
      : null;
  const liftPoint = (point: GeometryProbePoint, amount = 0.026): GeometryProbePoint =>
    feedbackNormal ? geometryAdd(point, geometryScale(feedbackNormal, amount)) : point;
  const liftedPoints = points.map((point) => liftPoint(point, 0.04));
  const edgeLines: PolylineSet = [];
  for (const polygon of facePolygons.slice(0, 8)) {
    const verts = polygon.vertices;
    const normal = geometryNormalizeVec(polygonNormalFromVertices(verts) ?? feedbackNormal ?? { x: 0, y: 1, z: 0 });
    const liftedVerts = normal ? verts.map((vertex) => geometryAdd(vertex, geometryScale(normal, 0.032))) : verts;
    for (let i = 0; i < verts.length; i += 1) {
      edgeLines.push([liftedVerts[i], liftedVerts[(i + 1) % liftedVerts.length]]);
    }
  }
  return {
    id: makeId(),
    objectId,
    summary: buildTopologyEditSummary(action, target, beforeCounts, afterCounts),
    points: liftedPoints,
    edgeLines,
    facePolygons,
  };
};

const pointToTuple3 = (point: GeometryProbePoint): [number, number, number] => [point.x, point.y, point.z];

const makeEdgeKeyFromVertices = (a: number, b: number): string => (a < b ? `${a}:${b}` : `${b}:${a}`);

const buildRetainedTopologySelectionPick = (
  objectId: string,
  objectName: string,
  objectType: string,
  mesh: SurfaceMeshData,
  target: GeometryTopologyRetainedSelectionTarget
): GeometryPickResult | null => {
  const fallbackNormal: [number, number, number] = [0, 1, 0];
  const basePick = {
    objectId,
    objectLabel: objectName,
    objectType,
    meshKey: objectId,
    stale: false,
  };
  if (target.kind === "face") {
    const tri = readMeshFaceVertexIndices(mesh, target.faceIndex);
    if (!tri) return null;
    const points = tri.map((index) => readMeshPoint(mesh, index));
    if (points.some((point) => !point)) return null;
    const [a, b, c] = points as [GeometryProbePoint, GeometryProbePoint, GeometryProbePoint];
    const ab = geometrySub(b, a);
    const ac = geometrySub(c, a);
    const normalRaw = geometryCross(ab, ac);
    const normalPoint = geometryNormalizeVec(normalRaw) ?? { x: 0, y: 1, z: 0 };
    const normal = pointToTuple3(normalPoint);
    const centroid: GeometryProbePoint = {
      x: (a.x + b.x + c.x) / 3,
      y: (a.y + b.y + c.y) / 3,
      z: (a.z + b.z + c.z) / 3,
    };
    return {
      ...basePick,
      kind: "face",
      worldPoint: pointToTuple3(centroid),
      normal,
      faceNormal: normal,
      faceIndex: target.faceIndex,
      sourceTriangle: tri,
      label: `${objectName} face #${target.faceIndex}`,
    };
  }
  if (target.kind === "edge") {
    const [aIndex, bIndex] = target.edgeVertices;
    const a = readMeshPoint(mesh, aIndex);
    const b = readMeshPoint(mesh, bIndex);
    if (!a || !b) return null;
    const midpoint: GeometryProbePoint = {
      x: (a.x + b.x) * 0.5,
      y: (a.y + b.y) * 0.5,
      z: (a.z + b.z) * 0.5,
    };
    const tangentPoint = geometryNormalizeVec(geometrySub(b, a)) ?? { x: 1, y: 0, z: 0 };
    const tangent = pointToTuple3(tangentPoint);
    return {
      ...basePick,
      kind: "edge",
      worldPoint: pointToTuple3(midpoint),
      normal: fallbackNormal,
      tangent,
      tangentKind: "edge-direction",
      edgeVertices: [aIndex, bIndex],
      edgeKey: makeEdgeKeyFromVertices(aIndex, bIndex),
      label: `${objectName} edge [${aIndex}, ${bIndex}]`,
    };
  }
  const point = readMeshPoint(mesh, target.vertexIndex);
  if (!point) return null;
  return {
    ...basePick,
    kind: "vertex",
    worldPoint: pointToTuple3(point),
    normal: fallbackNormal,
    vertexNormal: fallbackNormal,
    vertexIndex: target.vertexIndex,
    label: `${objectName} vertex #${target.vertexIndex}`,
  };
};

const buildProceduralPickFromRetainedSelection = (
  pick: GeometryPickResult
): GeometryProceduralPickInfo => {
  const normalTuple = pick.faceNormal ?? pick.vertexNormal ?? pick.surfaceNormal ?? pick.normal ?? [0, 1, 0];
  return {
    point: { x: pick.worldPoint[0], y: pick.worldPoint[1], z: pick.worldPoint[2] },
    normal: { x: normalTuple[0], y: normalTuple[1], z: normalTuple[2] },
    meshKey: pick.meshKey ?? pick.objectId,
    faceIndex: pick.faceIndex,
    vertexIndex: pick.vertexIndex,
    distance: 0,
  };
};

const formatRetainedTopologySelectionLabel = (target: GeometryTopologyRetainedSelectionTarget): string => {
  if (target.label) return target.label;
  if (target.kind === "face") return `Selected face #${target.faceIndex}`;
  if (target.kind === "edge") return `Selected edge [${target.edgeVertices[0]}, ${target.edgeVertices[1]}]`;
  return `Selected vertex #${target.vertexIndex}`;
};

const formatTopologyCountDelta = (
  beforeCounts: { vertexCount: number; faceCount: number },
  afterCounts: { vertexCount: number; faceCount: number }
): string => {
  const vertexDelta = afterCounts.vertexCount - beforeCounts.vertexCount;
  const faceDelta = afterCounts.faceCount - beforeCounts.faceCount;
  return `${vertexDelta >= 0 ? "+" : ""}${vertexDelta}V, ${faceDelta >= 0 ? "+" : ""}${faceDelta}F`;
};

const formatMeshEditFailureMessage = (actionLabel: string, message: string): string => {
  if (/Invalid edge selection/i.test(message)) {
    return `${actionLabel} needs a valid edge. Switch to Edge mode and click one mesh edge.`;
  }
  if (/Selected edge is not part of any face/i.test(message)) {
    return `${actionLabel} needs an edge that belongs to a face. Pick a visible mesh edge.`;
  }
  if (/Invalid face selection/i.test(message)) {
    return `${actionLabel} needs a valid face. Switch to Face mode and click one mesh face.`;
  }
  if (/Invalid vertex selection/i.test(message)) {
    return `${actionLabel} needs a valid vertex. Switch to Vertex mode and click one mesh vertex.`;
  }
  return message || `${actionLabel} failed.`;
};

const countGeometrySnapshotTopology = (
  snapshot: GeometryObject | GeometryDatasetMeshObject | null
): { vertexCount: number; faceCount: number } | null => {
  if (!snapshot || !("mesh" in snapshot)) return null;
  return countTriangleMeshTopology(snapshot.mesh);
};

const inferGeometryHistoryIntent = (
  before: GeometryObject | GeometryDatasetMeshObject | null,
  after: GeometryObject | GeometryDatasetMeshObject
): GeometryHistoryIntent => {
  if (!before) {
    return {
      action: "created",
      label: "Created object",
      operationType: "Create",
      target: after.name,
      parameters: "new object",
      destructive: false,
    };
  }
  if (before.name !== after.name) {
    return {
      action: "rename",
      label: "Renamed object",
      operationType: "Identity",
      target: "Name",
      parameters: `${before.name} -> ${after.name}`,
      destructive: false,
    };
  }
  if (before.visible !== after.visible) {
    return {
      action: "visibility",
      label: after.visible ? "Show object" : "Hide object",
      operationType: "Visibility",
      target: after.name,
      parameters: `visible=${after.visible ? "true" : "false"}`,
      destructive: false,
    };
  }
  if (JSON.stringify(before.transform) !== JSON.stringify(after.transform)) {
    return {
      action: "transform",
      label: "Transform updated",
      operationType: "Transform",
      target: after.name,
      parameters: `position ${formatHistoryVec3(after.transform.position)} · scale ${formatHistoryVec3(after.transform.scale)}`,
      destructive: false,
    };
  }
  if (JSON.stringify(before.material) !== JSON.stringify(after.material)) {
    return {
      action: "material",
      label: "Material updated",
      operationType: "Material",
      target: after.name,
      parameters: "material patch",
      destructive: false,
    };
  }
  if (!("mesh" in before) && !("mesh" in after) && JSON.stringify(before.params) !== JSON.stringify(after.params)) {
    return {
      action: "params",
      label: "Parameters updated",
      operationType: "Parameters",
      target: after.name,
      parameters: "procedural parameter patch",
      destructive: false,
    };
  }
  if ("mesh" in before && "mesh" in after) {
    const b = countTriangleMeshTopology(before.mesh);
    const a = countTriangleMeshTopology(after.mesh);
    return {
      action: "mesh-edit",
      label: "Mesh edited",
      operationType: "Mesh edit",
      target: after.name,
      parameters: `vertices ${b.vertexCount} -> ${a.vertexCount}, faces ${b.faceCount} -> ${a.faceCount}`,
      destructive: true,
    };
  }
  return {
    action: "updated",
    label: "Updated object",
    operationType: "Update",
    target: after.name,
    parameters: null,
    destructive: false,
  };
};

const summarizeGeometryHistorySnapshot = (snapshot: GeometryObject | GeometryDatasetMeshObject): string => {
  const transformSummary = `pos ${formatHistoryVec3(snapshot.transform.position)}`;
  if ("mesh" in snapshot) {
    const vertexCount = Math.floor(snapshot.mesh.positions.length / 3);
    const faceCount = snapshot.mesh.indices?.length
      ? Math.floor(snapshot.mesh.indices.length / 3)
      : Math.floor(snapshot.mesh.positions.length / 9);
    return `mesh V${vertexCount.toLocaleString()} F${faceCount.toLocaleString()} · ${transformSummary}`;
  }
  const sampleParams = Object.entries(snapshot.params)
    .filter(([, raw]) => typeof raw === "number" || typeof raw === "boolean" || typeof raw === "string")
    .slice(0, 2)
    .map(([key, raw]) => `${key}=${typeof raw === "number" ? formatHistoryNumber(raw) : String(raw)}`);
  const paramsSummary = sampleParams.length ? ` · ${sampleParams.join(", ")}` : "";
  return `${snapshot.type}${paramsSummary} · ${transformSummary}`;
};

const summarizeGeometryHistoryChange = (
  before: GeometryObject | GeometryDatasetMeshObject | null,
  after: GeometryObject | GeometryDatasetMeshObject
): string => {
  if (!before) return "Initial snapshot";
  const changes: string[] = [];
  if (before.name !== after.name) changes.push("renamed");
  if (before.visible !== after.visible) changes.push(after.visible ? "shown" : "hidden");
  if ("mesh" in before && "mesh" in after) {
    const beforeV = Math.floor(before.mesh.positions.length / 3);
    const afterV = Math.floor(after.mesh.positions.length / 3);
    if (beforeV !== afterV) changes.push(`vertices ${beforeV}→${afterV}`);
    const beforeF = before.mesh.indices?.length ? Math.floor(before.mesh.indices.length / 3) : Math.floor(before.mesh.positions.length / 9);
    const afterF = after.mesh.indices?.length ? Math.floor(after.mesh.indices.length / 3) : Math.floor(after.mesh.positions.length / 9);
    if (beforeF !== afterF) changes.push(`faces ${beforeF}→${afterF}`);
  } else if (!("mesh" in before) && !("mesh" in after)) {
    if (before.type !== after.type) changes.push(`${before.type}→${after.type}`);
    if (JSON.stringify(before.params) !== JSON.stringify(after.params)) changes.push("params updated");
  } else {
    changes.push("object kind changed");
  }
  if (JSON.stringify(before.transform) !== JSON.stringify(after.transform)) changes.push("transform updated");
  if (JSON.stringify(before.material) !== JSON.stringify(after.material)) changes.push("material updated");
  return changes.length ? changes.join(" · ") : "No visible change";
};

const buildMeshEdgePolylines = (
  mesh: { positions: ArrayLike<number>; indices?: ArrayLike<number> | null },
  includeCoplanar = true,
  angleThresholdDeg = 2
): PolylineSet => {
  const positions = mesh.positions;
  const vertCount = Math.floor(positions.length / 3);
  if (!vertCount) return [];
  const indices = mesh.indices;
  const triCount = indices?.length ? Math.floor(indices.length / 3) : Math.floor(vertCount / 3);
  if (!triCount) return [];

  type EdgeInfo = {
    a: number;
    b: number;
    n0?: { x: number; y: number; z: number };
    n1?: { x: number; y: number; z: number };
  };
  const edgeMap = new Map<string, EdgeInfo>();
  const cosThreshold = Math.cos((Math.max(0, angleThresholdDeg) * Math.PI) / 180);

  const getPos = (idx: number) => {
    const base = idx * 3;
    return {
      x: Number(positions[base] ?? 0),
      y: Number(positions[base + 1] ?? 0),
      z: Number(positions[base + 2] ?? 0),
    };
  };

  const addEdge = (a: number, b: number, normal: { x: number; y: number; z: number } | null) => {
    const i0 = Math.max(0, Math.min(a, b));
    const i1 = Math.max(0, Math.max(a, b));
    const key = `${i0}|${i1}`;
    const prev = edgeMap.get(key);
    if (!prev) {
      edgeMap.set(key, { a: i0, b: i1, n0: normal ?? undefined });
      return;
    }
    if (!prev.n1 && normal) prev.n1 = normal;
  };

  const triNormal = (ia: number, ib: number, ic: number) => {
    const a = getPos(ia);
    const b = getPos(ib);
    const c = getPos(ic);
    const abx = b.x - a.x;
    const aby = b.y - a.y;
    const abz = b.z - a.z;
    const acx = c.x - a.x;
    const acy = c.y - a.y;
    const acz = c.z - a.z;
    const nx = aby * acz - abz * acy;
    const ny = abz * acx - abx * acz;
    const nz = abx * acy - aby * acx;
    const len = Math.hypot(nx, ny, nz);
    if (!Number.isFinite(len) || len <= 1e-12) return null;
    return { x: nx / len, y: ny / len, z: nz / len };
  };

  for (let t = 0; t < triCount; t++) {
    const base = t * 3;
    const ia = indices ? Number(indices[base]) : base;
    const ib = indices ? Number(indices[base + 1]) : base + 1;
    const ic = indices ? Number(indices[base + 2]) : base + 2;
    if (!Number.isFinite(ia) || !Number.isFinite(ib) || !Number.isFinite(ic)) continue;
    if (ia < 0 || ib < 0 || ic < 0 || ia >= vertCount || ib >= vertCount || ic >= vertCount) continue;
    const normal = triNormal(ia, ib, ic);
    addEdge(ia, ib, normal);
    addEdge(ib, ic, normal);
    addEdge(ic, ia, normal);
  }

  const lines: PolylineSet = [];
  for (const edge of edgeMap.values()) {
    if (!includeCoplanar && edge.n0 && edge.n1) {
      const dot = edge.n0.x * edge.n1.x + edge.n0.y * edge.n1.y + edge.n0.z * edge.n1.z;
      if (dot >= cosThreshold) continue;
    }
    const a = getPos(edge.a);
    const b = getPos(edge.b);
    if (
      !Number.isFinite(a.x) ||
      !Number.isFinite(a.y) ||
      !Number.isFinite(a.z) ||
      !Number.isFinite(b.x) ||
      !Number.isFinite(b.y) ||
      !Number.isFinite(b.z)
    ) {
      continue;
    }
    lines.push([a, b]);
  }
  return lines;
};

const limitPolylineSet = (lines: PolylineSet, maxLines: number): PolylineSet => {
  if (lines.length <= maxLines) return lines;
  const step = lines.length / maxLines;
  const picked: PolylineSet = [];
  for (let i = 0; i < maxLines; i += 1) {
    const line = lines[Math.min(lines.length - 1, Math.floor(i * step))];
    if (line) picked.push(line);
  }
  return picked;
};

const circlePolyline = (
  radius: number,
  plane: "xy" | "xz" | "yz",
  center: { x: number; y: number; z: number } = { x: 0, y: 0, z: 0 },
  segments = 96,
  arc = Math.PI * 2
): PolylineSet[number] => {
  const count = Math.max(12, Math.round(segments));
  const pts: PolylineSet[number] = [];
  const steps = Math.max(2, Math.ceil((count * Math.min(Math.PI * 2, Math.max(0.01, arc))) / (Math.PI * 2)));
  for (let i = 0; i <= steps; i += 1) {
    const t = (i / steps) * arc;
    const c = Math.cos(t) * radius;
    const s = Math.sin(t) * radius;
    if (plane === "xy") pts.push({ x: center.x + c, y: center.y + s, z: center.z });
    else if (plane === "xz") pts.push({ x: center.x + c, y: center.y, z: center.z + s });
    else pts.push({ x: center.x, y: center.y + c, z: center.z + s });
  }
  return pts;
};

const buildProceduralObjectSelectionGuides = (object: GeometryObject): PolylineSet | null => {
  const params = object.params;
  if (object.type === "sphere") {
    const r = Math.max(1e-6, Number(params.radius ?? 1));
    return [
      circlePolyline(r, "xy"),
      circlePolyline(r, "xz"),
      circlePolyline(r, "yz"),
    ];
  }
  if (object.type === "cylinder") {
    const rt = Math.max(0, Number(params.radiusTop ?? 1));
    const rb = Math.max(0, Number(params.radiusBottom ?? 1));
    const h = Math.max(1e-6, Number(params.height ?? 2));
    const top = h * 0.5;
    const bottom = -h * 0.5;
    const lines: PolylineSet = [];
    if (rt > 1e-6) lines.push(circlePolyline(rt, "xz", { x: 0, y: top, z: 0 }, 72));
    if (rb > 1e-6) lines.push(circlePolyline(rb, "xz", { x: 0, y: bottom, z: 0 }, 72));
    for (const t of [0, Math.PI]) {
      lines.push([
        { x: Math.cos(t) * rb, y: bottom, z: Math.sin(t) * rb },
        { x: Math.cos(t) * rt, y: top, z: Math.sin(t) * rt },
      ]);
    }
    return lines;
  }
  if (object.type === "cone") {
    const r = Math.max(1e-6, Number(params.radius ?? 1));
    const h = Math.max(1e-6, Number(params.height ?? 2));
    const bottom = -h * 0.5;
    const top = h * 0.5;
    const lines: PolylineSet = [circlePolyline(r, "xz", { x: 0, y: bottom, z: 0 }, 72)];
    for (const t of [0, Math.PI]) {
      lines.push([
        { x: Math.cos(t) * r, y: bottom, z: Math.sin(t) * r },
        { x: 0, y: top, z: 0 },
      ]);
    }
    return lines;
  }
  if (object.type === "torus") {
    const r = Math.max(1e-6, Number(params.radius ?? 1));
    const tube = Math.max(1e-6, Number(params.tube ?? 0.35));
    const arc = Math.max(0.01, Math.min(Math.PI * 2, Number(params.arc ?? Math.PI * 2)));
    const lines: PolylineSet = [
      circlePolyline(r + tube, "xy", { x: 0, y: 0, z: 0 }, 128, arc),
      circlePolyline(r, "xy", { x: 0, y: 0, z: 0 }, 128, arc),
      circlePolyline(Math.max(1e-6, r - tube), "xy", { x: 0, y: 0, z: 0 }, 128, arc),
    ];
    if (arc < Math.PI * 2 - 1e-4) {
      const end = arc;
      lines.push([
        { x: Math.cos(0) * (r - tube), y: Math.sin(0) * (r - tube), z: 0 },
        { x: Math.cos(0) * (r + tube), y: Math.sin(0) * (r + tube), z: 0 },
      ]);
      lines.push([
        { x: Math.cos(end) * (r - tube), y: Math.sin(end) * (r - tube), z: 0 },
        { x: Math.cos(end) * (r + tube), y: Math.sin(end) * (r + tube), z: 0 },
      ]);
    }
    return lines;
  }
  return null;
};

const buildDatasetMeshObjectSelectionGuides = (
  object: GeometryDatasetMeshObject,
  mesh: SurfaceMeshData
): PolylineSet | null => {
  const key = `${object.id} ${object.name}`.toLowerCase();
  if (!key.includes("torus")) return null;
  const bounds = boundsFromPositions(mesh.positions);
  if (!bounds) return null;
  const center = {
    x: (bounds.min[0] + bounds.max[0]) * 0.5,
    y: (bounds.min[1] + bounds.max[1]) * 0.5,
    z: (bounds.min[2] + bounds.max[2]) * 0.5,
  };
  const rx = Math.max(1e-6, (bounds.max[0] - bounds.min[0]) * 0.5);
  const ry = Math.max(1e-6, (bounds.max[1] - bounds.min[1]) * 0.5);
  const tube = Math.max(1e-6, (bounds.max[2] - bounds.min[2]) * 0.5);
  const outer = Math.max(rx, ry);
  const centerline = Math.max(1e-6, outer - tube);
  const inner = Math.max(1e-6, outer - tube * 2);
  return [
    circlePolyline(outer, "xy", center, 128),
    circlePolyline(centerline, "xy", center, 128),
    circlePolyline(inner, "xy", center, 128),
  ];
};

const buildGeometryTransformMatrix = (transform: GeometryObjectTransform) => {
  const pos = transform.position;
  const rot = transform.rotation;
  const scale = transform.scale;
  const safeScale = new THREE.Vector3(
    toSafeNumber(scale.x, 1) || 1,
    toSafeNumber(scale.y, 1) || 1,
    toSafeNumber(scale.z, 1) || 1
  );
  safeScale.x = Math.max(1e-6, safeScale.x);
  safeScale.y = Math.max(1e-6, safeScale.y);
  safeScale.z = Math.max(1e-6, safeScale.z);
  const euler = new THREE.Euler(
    (toSafeNumber(rot.x, 0) * Math.PI) / 180,
    (toSafeNumber(rot.y, 0) * Math.PI) / 180,
    (toSafeNumber(rot.z, 0) * Math.PI) / 180,
    "XYZ"
  );
  const quat = new THREE.Quaternion().setFromEuler(euler);
  const mat = new THREE.Matrix4();
  mat.compose(
    new THREE.Vector3(toSafeNumber(pos.x, 0), toSafeNumber(pos.y, 0), toSafeNumber(pos.z, 0)),
    quat,
    safeScale
  );
  return mat;
};

const applyGeometryTransformToPolylineSet = (
  lines: PolylineSet,
  transform: GeometryObjectTransform
): PolylineSet => {
  if (!lines.length) return [];
  const mat = buildGeometryTransformMatrix(transform);
  return lines.map((line) =>
    line.map((p) => {
      const v = new THREE.Vector3(p.x, p.y, p.z).applyMatrix4(mat);
      return { x: v.x, y: v.y, z: v.z };
    })
  );
};

const transformSurfaceMeshByGeometryTransform = (
  mesh: SurfaceMeshData,
  transform: GeometryObjectTransform
): SurfaceMeshData => {
  const mat = buildGeometryTransformMatrix(transform);
  const positions = Float32Array.from(mesh.positions);
  const tmp = new THREE.Vector3();
  for (let i = 0; i + 2 < positions.length; i += 3) {
    tmp.set(positions[i], positions[i + 1], positions[i + 2]).applyMatrix4(mat);
    positions[i] = tmp.x;
    positions[i + 1] = tmp.y;
    positions[i + 2] = tmp.z;
  }
  return {
    ...mesh,
    positions,
    indices: mesh.indices ? Uint32Array.from(mesh.indices) : null,
    normals: null,
    uvs: mesh.uvs ? Float32Array.from(mesh.uvs) : null,
    adjacency: null,
    meanEdgeLength: null,
    validation: null,
  };
};

type GeometryVariantResolvedMesh = {
  mesh: SurfaceMeshData;
  transform: GeometryObjectTransform;
  flatShading?: boolean;
};

const buildSurfaceMeshFromGeometryObjectSnapshot = (
  obj: GeometryObject,
  labelOverride?: string
): GeometryVariantResolvedMesh | null => {
  const entry = GEOMETRY_OBJECT_REGISTRY[obj.type];
  if (!entry) return null;
  const geom = entry.build(obj.params);
  try {
    const mesh = computeVertexNormals(
      buildSurfaceMeshFromGeometry(
        geom,
        labelOverride ?? obj.name,
        { kind: "proceduralObjects" },
        { mergeVertices: false }
      )
    );
    if (!mesh.positions.length) return null;
    return {
      mesh,
      transform: {
        position: { ...obj.transform.position },
        rotation: { ...obj.transform.rotation },
        scale: { ...obj.transform.scale },
      },
      flatShading: obj.type === "polyhedron" ? !Boolean(obj.params.smoothNormals ?? true) : false,
    };
  } finally {
    geom.dispose();
  }
};

const resolveVariantSnapshotMesh = (
  snapshot: GeometryObject | GeometryDatasetMeshObject,
  labelOverride?: string
): GeometryVariantResolvedMesh | null => {
  if ("mesh" in snapshot) {
    return {
      mesh: cloneSurfaceMeshData(snapshot.mesh, labelOverride ?? snapshot.name),
      transform: {
        position: { ...snapshot.transform.position },
        rotation: { ...snapshot.transform.rotation },
        scale: { ...snapshot.transform.scale },
      },
      flatShading: false,
    };
  }
  return buildSurfaceMeshFromGeometryObjectSnapshot(snapshot, labelOverride ?? snapshot.name);
};

const computeVariantSnapshotMetrics = (
  snapshot: GeometryObject | GeometryDatasetMeshObject
): TriangleMeshGeometricMetrics | null => {
  const resolved = resolveVariantSnapshotMesh(snapshot);
  if (!resolved) return null;
  return computeTriangleMeshGeometricMetrics(
    transformSurfaceMeshByGeometryTransform(resolved.mesh, resolved.transform)
  );
};

const MAX_ADVANCED_SNAP_VERTICES = 24000;
const MAX_ADVANCED_SNAP_EDGE_POINTS = 24000;
const MAX_ADVANCED_SNAP_FACE_POINTS = 24000;
const MAX_ADVANCED_SNAP_TRIANGLES = 14000;
const MAX_ADVANCED_SNAP_OBJECT_CENTERS = 6000;
const MAX_ADVANCED_SNAP_OBJECT_ORIGINS = 6000;
const MAX_ADVANCED_SNAP_BBOX_CORNERS = 24000;

type SnapPoint3 = { x: number; y: number; z: number };
type SnapTriangle3 = { a: SnapPoint3; b: SnapPoint3; c: SnapPoint3 };
type SnapSegment3 = { a: SnapPoint3; b: SnapPoint3 };
type GeometrySnapPreviewKind =
  | "grid"
  | "vertex"
  | "edge"
  | "face_center"
  | "surface"
  | "object_center"
  | "object_origin"
  | "bbox_corner"
  | "face_plane"
  | "ground_plane";

const vecDistSq3 = (a: SnapPoint3, b: SnapPoint3) => {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  const dz = a.z - b.z;
  return dx * dx + dy * dy + dz * dz;
};

const nearestPointFromList = (query: SnapPoint3, points: SnapPoint3[]): { point: SnapPoint3 | null; distSq: number } => {
  let best: SnapPoint3 | null = null;
  let bestDistSq = Number.POSITIVE_INFINITY;
  for (let i = 0; i < points.length; i++) {
    const candidate = points[i];
    const d2 = vecDistSq3(query, candidate);
    if (d2 < bestDistSq) {
      bestDistSq = d2;
      best = candidate;
    }
  }
  return { point: best, distSq: bestDistSq };
};

const nearestPointOnTriangles = (
  query: SnapPoint3,
  triangles: SnapTriangle3[]
): { point: SnapPoint3 | null; distSq: number } => {
  if (!triangles.length) return { point: null, distSq: Number.POSITIVE_INFINITY };
  const queryV = new THREE.Vector3(query.x, query.y, query.z);
  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const c = new THREE.Vector3();
  const closest = new THREE.Vector3();
  const tri = new THREE.Triangle();
  let best: SnapPoint3 | null = null;
  let bestDistSq = Number.POSITIVE_INFINITY;
  for (let i = 0; i < triangles.length; i++) {
    const t = triangles[i];
    a.set(t.a.x, t.a.y, t.a.z);
    b.set(t.b.x, t.b.y, t.b.z);
    c.set(t.c.x, t.c.y, t.c.z);
    tri.set(a, b, c);
    tri.closestPointToPoint(queryV, closest);
    const d2 = closest.distanceToSquared(queryV);
    if (d2 < bestDistSq) {
      bestDistSq = d2;
      best = { x: closest.x, y: closest.y, z: closest.z };
    }
  }
  return { point: best, distSq: bestDistSq };
};

const nearestPointOnSegments = (
  query: SnapPoint3,
  segments: SnapSegment3[]
): { point: SnapPoint3 | null; distSq: number } => {
  if (!segments.length) return { point: null, distSq: Number.POSITIVE_INFINITY };
  const q = new THREE.Vector3(query.x, query.y, query.z);
  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const ab = new THREE.Vector3();
  const aq = new THREE.Vector3();
  const closest = new THREE.Vector3();
  let best: SnapPoint3 | null = null;
  let bestDistSq = Number.POSITIVE_INFINITY;
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i];
    a.set(seg.a.x, seg.a.y, seg.a.z);
    b.set(seg.b.x, seg.b.y, seg.b.z);
    ab.subVectors(b, a);
    const lenSq = ab.lengthSq();
    if (lenSq <= 1e-12) continue;
    aq.subVectors(q, a);
    const t = Math.max(0, Math.min(1, aq.dot(ab) / lenSq));
    closest.copy(a).addScaledVector(ab, t);
    const d2 = closest.distanceToSquared(q);
    if (d2 < bestDistSq) {
      bestDistSq = d2;
      best = { x: closest.x, y: closest.y, z: closest.z };
    }
  }
  return { point: best, distSq: bestDistSq };
};

const buildMeshPlacementSnapPrimitives = (
  mesh: Pick<SurfaceMeshData, "positions" | "indices">
): { vertices: SnapPoint3[]; edgeSegments: SnapSegment3[]; triangles: SnapTriangle3[] } => {
  const vertices: SnapPoint3[] = [];
  const edgeSegments: SnapSegment3[] = [];
  const triangles: SnapTriangle3[] = [];
  const positions = mesh.positions;
  if (!positions || positions.length < 9) return { vertices, edgeSegments, triangles };

  const vertexCount = Math.floor(positions.length / 3);
  const maxVertices = Math.min(vertexCount, 48000);
  for (let i = 0; i < maxVertices; i++) {
    const idx = i * 3;
    vertices.push({ x: positions[idx], y: positions[idx + 1], z: positions[idx + 2] });
  }

  const pushFace = (ia: number, ib: number, ic: number) => {
    if (ia < 0 || ib < 0 || ic < 0) return;
    if (ia >= vertexCount || ib >= vertexCount || ic >= vertexCount) return;
    const aIdx = ia * 3;
    const bIdx = ib * 3;
    const cIdx = ic * 3;
    const a = { x: positions[aIdx], y: positions[aIdx + 1], z: positions[aIdx + 2] };
    const b = { x: positions[bIdx], y: positions[bIdx + 1], z: positions[bIdx + 2] };
    const c = { x: positions[cIdx], y: positions[cIdx + 1], z: positions[cIdx + 2] };
    if (triangles.length < 20000) triangles.push({ a, b, c });
    if (edgeSegments.length < 30000) edgeSegments.push({ a, b });
    if (edgeSegments.length < 30000) edgeSegments.push({ a: b, b: c });
    if (edgeSegments.length < 30000) edgeSegments.push({ a: c, b: a });
  };

  const indices = mesh.indices;
  if (indices && indices.length >= 3) {
    for (let i = 0; i + 2 < indices.length; i += 3) {
      pushFace(indices[i], indices[i + 1], indices[i + 2]);
      if (triangles.length >= 20000 && edgeSegments.length >= 30000) break;
    }
  } else {
    for (let i = 0; i + 2 < vertexCount; i += 3) {
      pushFace(i, i + 1, i + 2);
      if (triangles.length >= 20000 && edgeSegments.length >= 30000) break;
    }
  }
  return { vertices, edgeSegments, triangles };
};

const computeSurfaceMeshFocus = (
  mesh: Pick<SurfaceMeshData, "positions">
): { center: { x: number; y: number; z: number }; radius: number } | null => {
  const positions = mesh.positions;
  if (!positions || positions.length < 3) return null;
  let minX = Infinity;
  let minY = Infinity;
  let minZ = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  let maxZ = -Infinity;
  for (let i = 0; i + 2 < positions.length; i += 3) {
    const x = Number(positions[i]);
    const y = Number(positions[i + 1]);
    const z = Number(positions[i + 2]);
    if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) continue;
    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (z < minZ) minZ = z;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
    if (z > maxZ) maxZ = z;
  }
  if (!Number.isFinite(minX) || !Number.isFinite(maxX)) return null;
  const center = {
    x: (minX + maxX) * 0.5,
    y: (minY + maxY) * 0.5,
    z: (minZ + maxZ) * 0.5,
  };
  let radiusSq = 0;
  for (let i = 0; i + 2 < positions.length; i += 3) {
    const dx = Number(positions[i]) - center.x;
    const dy = Number(positions[i + 1]) - center.y;
    const dz = Number(positions[i + 2]) - center.z;
    if (!Number.isFinite(dx) || !Number.isFinite(dy) || !Number.isFinite(dz)) continue;
    const d2 = dx * dx + dy * dy + dz * dz;
    if (d2 > radiusSq) radiusSq = d2;
  }
  return {
    center,
    radius: Math.max(0.2, Math.sqrt(Math.max(0, radiusSq))),
  };
};

type MeshFeatureAnalysis = {
  sharpEdges: PolylineSet;
  faceNormals: PolylineSet;
  dihedralLabels: Array<{ text: string; position: { x: number; y: number; z: number } }>;
  angleDefects: Array<{ point: { x: number; y: number; z: number }; defect: number }>;
};

const analyzeMeshFeatures = (
  mesh: { positions: ArrayLike<number>; indices?: ArrayLike<number> | null },
  dihedralThresholdDeg: number,
  faceNormalScale: number
): MeshFeatureAnalysis => {
  const positions = mesh.positions;
  const indices = mesh.indices ?? null;
  const vertexCount = Math.floor(positions.length / 3);
  const triCount = indices ? Math.floor(indices.length / 3) : Math.floor(vertexCount / 3);
  if (!vertexCount || !triCount) {
    return { sharpEdges: [], faceNormals: [], dihedralLabels: [], angleDefects: [] };
  }

  const getPos = (idx: number) => {
    const base = idx * 3;
    return new THREE.Vector3(
      Number(positions[base] ?? 0),
      Number(positions[base + 1] ?? 0),
      Number(positions[base + 2] ?? 0)
    );
  };
  const safeAcos = (value: number) => Math.acos(clampNumber(value, -1, 1));

  const faceNormals: THREE.Vector3[] = new Array(triCount);
  const faceCenters: THREE.Vector3[] = new Array(triCount);
  const cornerIndices: Array<[number, number, number]> = [];
  const vertexAngleSum = new Float64Array(vertexCount);
  const boundaryVertex = new Uint8Array(vertexCount);

  type EdgeInfo = { a: number; b: number; face0: number; face1: number | null };
  const edges = new Map<string, EdgeInfo>();
  const addEdge = (a: number, b: number, faceIndex: number) => {
    const i0 = Math.min(a, b);
    const i1 = Math.max(a, b);
    const key = `${i0}|${i1}`;
    const existing = edges.get(key);
    if (!existing) {
      edges.set(key, { a: i0, b: i1, face0: faceIndex, face1: null });
      return;
    }
    if (existing.face1 == null) existing.face1 = faceIndex;
  };

  for (let t = 0; t < triCount; t++) {
    const base = t * 3;
    const ia = indices ? Number(indices[base]) : base;
    const ib = indices ? Number(indices[base + 1]) : base + 1;
    const ic = indices ? Number(indices[base + 2]) : base + 2;
    if (
      !Number.isInteger(ia) ||
      !Number.isInteger(ib) ||
      !Number.isInteger(ic) ||
      ia < 0 ||
      ib < 0 ||
      ic < 0 ||
      ia >= vertexCount ||
      ib >= vertexCount ||
      ic >= vertexCount
    ) {
      continue;
    }
    cornerIndices.push([ia, ib, ic]);

    const a = getPos(ia);
    const b = getPos(ib);
    const c = getPos(ic);
    const ab = b.clone().sub(a);
    const ac = c.clone().sub(a);
    const bc = c.clone().sub(b);
    const normal = new THREE.Vector3().crossVectors(ab, ac);
    const nLen = normal.length();
    if (nLen <= 1e-12 || !Number.isFinite(nLen)) {
      faceNormals[t] = new THREE.Vector3(0, 1, 0);
    } else {
      normal.multiplyScalar(1 / nLen);
      faceNormals[t] = normal;
    }
    faceCenters[t] = a.clone().add(b).add(c).multiplyScalar(1 / 3);

    const abDir = ab.clone().normalize();
    const acDir = ac.clone().normalize();
    const baDir = a.clone().sub(b).normalize();
    const bcDir = bc.clone().normalize();
    const caDir = a.clone().sub(c).normalize();
    const cbDir = b.clone().sub(c).normalize();
    if (Number.isFinite(abDir.lengthSq()) && Number.isFinite(acDir.lengthSq())) {
      vertexAngleSum[ia] += safeAcos(abDir.dot(acDir));
    }
    if (Number.isFinite(baDir.lengthSq()) && Number.isFinite(bcDir.lengthSq())) {
      vertexAngleSum[ib] += safeAcos(baDir.dot(bcDir));
    }
    if (Number.isFinite(caDir.lengthSq()) && Number.isFinite(cbDir.lengthSq())) {
      vertexAngleSum[ic] += safeAcos(caDir.dot(cbDir));
    }

    addEdge(ia, ib, t);
    addEdge(ib, ic, t);
    addEdge(ic, ia, t);
  }

  const threshold = Math.max(0, Number(dihedralThresholdDeg) || 0);
  const sharpEdges: PolylineSet = [];
  const faceNormalLines: PolylineSet = [];
  const dihedralLabels: Array<{ text: string; position: { x: number; y: number; z: number } }> = [];

  if (faceNormalScale > 0) {
    for (let t = 0; t < faceCenters.length; t++) {
      const center = faceCenters[t];
      const normal = faceNormals[t];
      if (!center || !normal) continue;
      const end = center.clone().addScaledVector(normal, faceNormalScale);
      faceNormalLines.push(
        [
          { x: center.x, y: center.y, z: center.z },
          { x: end.x, y: end.y, z: end.z },
        ]
      );
    }
  }

  for (const edge of edges.values()) {
    const a = getPos(edge.a);
    const b = getPos(edge.b);
    const isBoundary = edge.face1 == null;
    if (isBoundary) {
      boundaryVertex[edge.a] = 1;
      boundaryVertex[edge.b] = 1;
      sharpEdges.push([
        { x: a.x, y: a.y, z: a.z },
        { x: b.x, y: b.y, z: b.z },
      ]);
      continue;
    }
    const n0 = faceNormals[edge.face0];
    const n1 = faceNormals[edge.face1!];
    if (!n0 || !n1) continue;
    const angleDeg = safeAcos(n0.dot(n1)) * RAD_TO_DEG;
    if (angleDeg >= threshold) {
      sharpEdges.push([
        { x: a.x, y: a.y, z: a.z },
        { x: b.x, y: b.y, z: b.z },
      ]);
    }
    const mid = a.clone().add(b).multiplyScalar(0.5);
    dihedralLabels.push({
      text: `${angleDeg.toFixed(1)}deg`,
      position: { x: mid.x, y: mid.y, z: mid.z },
    });
  }

  const angleDefects: Array<{ point: { x: number; y: number; z: number }; defect: number }> = [];
  for (let i = 0; i < vertexCount; i++) {
    const expected = boundaryVertex[i] ? Math.PI : Math.PI * 2;
    const defect = expected - vertexAngleSum[i];
    if (!Number.isFinite(defect) || Math.abs(defect) < 1e-4) continue;
    const p = getPos(i);
    angleDefects.push({ point: { x: p.x, y: p.y, z: p.z }, defect });
  }

  return { sharpEdges, faceNormals: faceNormalLines, dihedralLabels, angleDefects };
};

