  const mobiusSummary = useMemo(() => {
    const eps = 1e-12;
    const A = mobiusParams.a;
    const B = mobiusParams.b;
    const Cc = mobiusParams.c;
    const D = mobiusParams.d;
    const det = cSub(cMul(A, D), cMul(B, Cc));
    const affine = cAbs2(Cc) < eps;
    const pole = affine ? null : cNeg(cDiv(D, Cc));
    const fixed = mobiusFixedPoints(mobiusParams);
    const fixedLabel =
      fixed.kind === "all"
        ? "all points"
        : fixed.kind === "none"
          ? "none"
          : fixed.values.map(cToStr).join(" ; ");
    const transformationType = affine
      ? "affine"
      : cAbs2(A) < eps && cAbs2(D) < eps
        ? "inversion-like"
        : "general Möbius";
    return {
      det,
      affine,
      pole,
      fixed,
      fixedLabel,
      transformationType,
      singularity: pole ? `pole at z = ${cToStr(pole)}` : "none",
      valid: cAbs2(det) >= eps,
    };
  }, [mobiusParams]);

  useEffect(() => {
    if (mode !== "mobius" || mobiusSubTab !== "animation" || !mobiusAnimationPlaying) return;
    let raf = 0;
    let last = performance.now();
    const tick = (now: number) => {
      const dt = Math.max(0, (now - last) / 1000);
      last = now;
      setMobiusAnimationProgress((prev) => {
        const next = prev + dt * 0.22 * mobiusAnimationSpeed;
        return next >= 1 ? next - Math.floor(next) : next;
      });
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [mode, mobiusSubTab, mobiusAnimationPlaying, mobiusAnimationSpeed]);

