        const idx = j * nu + i;
        const base = evalBaseW(u, v);
        if (!base) {
          re[idx] = NaN;
          im[idx] = NaN;
          reClamped[idx] = NaN;
          imClamped[idx] = NaN;
          wMag[idx] = NaN;
          continue;
        }
        let r = base.re;
        let m = base.im;
        r *= wScale;
        m *= wScale;
        re[idx] = r;
        im[idx] = m;
        const mag = Math.hypot(r, m);
        wMag[idx] = mag;
