      zRef.current.drawPoints([], { layer: "other-exact-zero-z" });
      zRef.current.drawPoints([], { layer: "other-exact-pole-z" });
      zRef.current.drawPoints([], { layer: "other-poles-inside-z" });
      zRef.current.drawPoints([], { layer: "other-poles-outside-z" });
