  const handleCaptureVisualize = useCallback(
    (stageId: WorkbookStageId, blockId: string, slot: WorkbookSnapshotSlot) => {
      if (IS_REPLAY_MODE) return;
      const snapshot = buildViewerSnapshot();
      if (!activeWorkbookId) return;
      setCompareBlockId(blockId);
      setWorkbooks((prev) =>
        prev.map((w) =>
          w.id === activeWorkbookId
            ? {
                ...w,
                updatedAt: Date.now(),
                stages: w.stages.map((s) =>
                  s.id === stageId
                    ? {
                        ...s,
                        blocks: s.blocks.map((b) => {
                          if (b.id !== blockId) return b;
                          const prevSnapshotA = resolveVisualizeSnapshot(b.visualize, "A");
                          const prevSnapshotB = resolveVisualizeSnapshot(b.visualize, "B");
                          const nextSnapshot = {
                            ...snapshot,
                            thumbnail:
                              (slot === "A" ? prevSnapshotA?.thumbnail : prevSnapshotB?.thumbnail) ?? null,
                          };
                          return {
                            ...b,
                            visualize: {
                              ...(b.visualize ?? { live: false }),
                              live: false,
                              snapshotA: slot === "A" ? nextSnapshot : prevSnapshotA,
                              snapshotB: slot === "B" ? nextSnapshot : prevSnapshotB,
                            },
                          };
                        }),
                      }
                    : s
                ),
              }
            : w
        )
      );
      setPendingThumbnailCapture({ stageId, blockId, snapshot, slot });
      setWorkbookCaptureToken((t) => t + 1);
    },
    [activeWorkbookId, buildViewerSnapshot]
  );

  const handleWorkbookThumbnail = useCallback(
    (dataUrl: string | null) => {
      if (IS_REPLAY_MODE) return;
      if (!pendingThumbnailCapture || !activeWorkbookId) return;
      const { stageId, blockId, snapshot, slot } = pendingThumbnailCapture;
      setPendingThumbnailCapture(null);
      setWorkbooks((prev) =>
        prev.map((w) =>
          w.id === activeWorkbookId
            ? {
                ...w,
                updatedAt: Date.now(),
                stages: w.stages.map((s) =>
                  s.id === stageId
                    ? {
                        ...s,
                        blocks: s.blocks.map((b) => {
                          if (b.id !== blockId) return b;
                          const prevSnapshotA = resolveVisualizeSnapshot(b.visualize, "A");
                          const prevSnapshotB = resolveVisualizeSnapshot(b.visualize, "B");
                          const nextSnapshot = {
                            ...snapshot,
                            thumbnail: dataUrl ?? snapshot.thumbnail ?? null,
                          };
                          return {
                            ...b,
                            visualize: {
                              ...(b.visualize ?? { live: false }),
                              live: false,
                              snapshotA: slot === "A" ? nextSnapshot : prevSnapshotA,
                              snapshotB: slot === "B" ? nextSnapshot : prevSnapshotB,
                            },
                          };
                        }),
                      }
                    : s
                ),
              }
            : w
        )
      );
    },
    [activeWorkbookId, pendingThumbnailCapture]
  );

  const handleApplyVisualize = useCallback(
    (snapshot: WorkbookViewSnapshot, blockId?: string, slot?: WorkbookSnapshotSlot) => {
      if (blockId) setCompareBlockId(blockId);
      if (slot === "A") setCompareUseSnapshotA(true);
      if (slot === "B") setCompareUseSnapshotB(true);
      if (snapshot.datasetKind === "volume") {
        setDatasetKind("volume");
        setSurfacesPanelState("work");
        setSurfacesLeftTab("scene");
      } else if (snapshot.viewerKind && isSurfaceViewerKind(snapshot.viewerKind)) {
        setSurfaceViewerKind(snapshot.viewerKind);
        setDatasetKind(snapshot.viewerKind === "mesh" ? "mesh" : "surface");
      }

      if (snapshot.viewerKind === "param" || snapshot.viewerKind === "weierstrass") {
        if (snapshot.paramId) setParamSurfaceId(snapshot.paramId);
      } else if (snapshot.viewerKind === "graph") {
        if (snapshot.surfaceId) setGraphSurfaceId(snapshot.surfaceId);
      } else if (snapshot.viewerKind === "implicit") {
        if (snapshot.surfaceId) setImplicitSurfaceId(snapshot.surfaceId);
      }

      if (snapshot.graphExpr != null) setGraphExpr(snapshot.graphExpr);
      if (snapshot.implicitExpr != null) setImplicitExpr(snapshot.implicitExpr);
      if (snapshot.paramXExpr != null) setParamXExpr(snapshot.paramXExpr);
      if (snapshot.paramYExpr != null) setParamYExpr(snapshot.paramYExpr);
      if (snapshot.paramZExpr != null) setParamZExpr(snapshot.paramZExpr);
      if (snapshot.weierstrassGExpr != null) setWeierstrassGExpr(snapshot.weierstrassGExpr);
      if (snapshot.weierstrassPhiExpr != null) setWeierstrassPhiExpr(snapshot.weierstrassPhiExpr);
      if (snapshot.weierstrassRecenter != null) setWeierstrassRecenter(snapshot.weierstrassRecenter);
      if (snapshot.graphResolution != null) setGraphResolution(Math.max(10, Math.round(snapshot.graphResolution)));
      if (snapshot.implicitResolution != null) setImplicitResolution(Math.max(8, Math.round(snapshot.implicitResolution)));
      if (snapshot.paramResolution != null) setParamResolution(Math.max(10, Math.round(snapshot.paramResolution)));
      if (snapshot.weierstrassResolution != null) {
        setWeierstrassResolution(Math.max(10, Math.round(snapshot.weierstrassResolution)));
      }
      if (snapshot.graphDomain && snapshot.surfaceId && isGraphSurface(snapshot.surfaceId)) {
        const surfaceId = snapshot.surfaceId;
        const graphDomain = snapshot.graphDomain;
        setGraphDomains((prev) => ({
          ...prev,
          [surfaceId]: normalizeGraphDomain(graphDomain, getDefaultGraphSpan(surfaceId)),
        }));
      }
      if (snapshot.implicitDomain && snapshot.surfaceId && isImplicitSurface(snapshot.surfaceId)) {
        const surfaceId = snapshot.surfaceId;
        const implicitDomain = snapshot.implicitDomain;
        setImplicitDomains((prev) => ({
          ...prev,
          [surfaceId]: normalizeImplicitDomain(
            implicitDomain,
            getDefaultImplicitDomain(surfaceId)
          ),
        }));
      }
      if (snapshot.paramDomain && snapshot.paramId) {
        const paramId = snapshot.paramId;
        const paramDomain = snapshot.paramDomain;
        setParamDomains((prev) => ({
          ...prev,
          [paramId]: normalizeParamDomain(
            paramDomain,
            getParamDomainPreviewBounds(paramId)
          ),
        }));
      }
      if (snapshot.weierstrassDomain) {
        setWeierstrassDomain(normalizeParamDomain(snapshot.weierstrassDomain, WEIERSTRASS_DEFAULTS.domain));
      }

      if (snapshot.colorMode) setColorMode(snapshot.colorMode);
      if (snapshot.colorPalette) setColorPalette(snapshot.colorPalette);
      if (snapshot.showWireframe !== undefined) setShowWireframe(snapshot.showWireframe);
      if (snapshot.showContours !== undefined) setShowContours(snapshot.showContours);
      if (snapshot.showChartGrid !== undefined) setShowChartGrid(snapshot.showChartGrid);
      if (snapshot.probeEnabled !== undefined) setProbeEnabled(snapshot.probeEnabled);
      if (snapshot.showProbeNormal !== undefined) setShowProbeNormal(snapshot.showProbeNormal);
      if (snapshot.showProbeTangentPlane !== undefined) setShowProbeTangentPlane(snapshot.showProbeTangentPlane);
      if (snapshot.showProbeTangents !== undefined) setShowProbeTangents(snapshot.showProbeTangents);
      if (snapshot.showPrincipalDirections !== undefined) setShowPrincipalDirections(snapshot.showPrincipalDirections);
      if (snapshot.showPrincipalGlyphs !== undefined) setShowPrincipalGlyphs(snapshot.showPrincipalGlyphs);
      if (snapshot.showPrincipalLines !== undefined) setShowPrincipalLines(snapshot.showPrincipalLines);
      if (snapshot.showCurvatureLines !== undefined) setShowCurvatureLines(snapshot.showCurvatureLines);
      if (snapshot.showRidges !== undefined) setShowRidges(snapshot.showRidges);
      if (snapshot.showValleys !== undefined) setShowValleys(snapshot.showValleys);
      if (snapshot.showGaussMap !== undefined) setShowGaussMap(snapshot.showGaussMap);
      if (snapshot.showBoundingBox !== undefined) setShowBoundingBox(snapshot.showBoundingBox);
      if (snapshot.showPlanes !== undefined) setShowPlanes(snapshot.showPlanes);
      if (snapshot.volumeViewMode) setVolumeViewMode(snapshot.volumeViewMode);
      if (snapshot.volumeIsoValue !== undefined) setVolumeIsoValue(snapshot.volumeIsoValue);
      if (snapshot.volumeShowIsosurface !== undefined) setVolumeShowIsosurface(snapshot.volumeShowIsosurface);
      if (snapshot.volumeShowStreamlines !== undefined) setVolumeShowStreamlines(snapshot.volumeShowStreamlines);

      if (snapshot.camera) {
        setCameraOverride(snapshot.camera);
        setCameraOverrideToken((t) => t + 1);
      }
    },
    [
      setDatasetKind,
      setSurfaceViewerKind,
      setParamSurfaceId,
      setGraphSurfaceId,
      setImplicitSurfaceId,
      setGraphExpr,
      setImplicitExpr,
      setParamXExpr,
      setParamYExpr,
      setParamZExpr,
      setWeierstrassGExpr,
      setWeierstrassPhiExpr,
      setWeierstrassRecenter,
      setGraphResolution,
      setImplicitResolution,
      setParamResolution,
      setWeierstrassResolution,
      setGraphDomains,
      setImplicitDomains,
      setParamDomains,
      setWeierstrassDomain,
      setColorMode,
      setColorPalette,
      setShowWireframe,
      setShowContours,
      setShowChartGrid,
      setProbeEnabled,
      setShowProbeNormal,
      setShowProbeTangentPlane,
      setShowProbeTangents,
      setShowPrincipalDirections,
      setShowPrincipalGlyphs,
      setShowPrincipalLines,
      setShowCurvatureLines,
      setShowRidges,
      setShowValleys,
      setShowGaussMap,
      setShowBoundingBox,
      setShowPlanes,
      setVolumeViewMode,
      setVolumeIsoValue,
      setVolumeShowIsosurface,
      setVolumeShowStreamlines,
      setSurfacesPanelState,
      setSurfacesLeftTab,
      setCompareBlockId,
      setCompareUseSnapshotA,
      setCompareUseSnapshotB,
    ]
  );

  const buildWorkbookWorkspaceState = useCallback(
    (embedAssets = true): WorkbookWorkspaceState => {
    const now = Date.now();
    const graphDomainCopy: Record<string, GraphDomain> = {};
    for (const [id, domain] of Object.entries(graphDomains)) {
      graphDomainCopy[id] = { xSpan: domain.xSpan, ySpan: domain.ySpan };
    }
    const implicitDomainCopy: Record<string, ImplicitDomain> = {};
    for (const [id, domain] of Object.entries(implicitDomains)) {
      implicitDomainCopy[id] = { xSpan: domain.xSpan, ySpan: domain.ySpan };
    }
    const paramDomainCopy: Record<string, ParamDomain> = {};
    for (const [id, domain] of Object.entries(paramDomains)) {
      paramDomainCopy[id] = {
        uMin: domain.uMin,
        uMax: domain.uMax,
        vMin: domain.vMin,
        vMax: domain.vMax,
      };
    }

    const datasetItems: WorkbookDatasetRecipe[] = [
      {
        id: "surface:graph",
        kind: "surface",
        source: "explicit",
        recipe: {
          surfaceId: graphSurfaceId,
          expr: graphExpr,
          resolution: graphResolution,
          domains: graphDomainCopy,
        },
        provenance: { source: "explicit", createdAt: now, version: 1 },
      },
      {
        id: "surface:implicit",
        kind: "surface",
        source: "implicit",
        recipe: {
          surfaceId: implicitSurfaceId,
          expr: implicitExpr,
          resolution: implicitResolution,
          domains: implicitDomainCopy,
        },
        provenance: { source: "implicit", createdAt: now, version: 1 },
      },
      {
        id: "surface:param",
        kind: "surface",
        source: "param",
        recipe: {
          surfaceId: paramSurfaceId,
          xExpr: paramXExpr,
          yExpr: paramYExpr,
          zExpr: paramZExpr,
          resolution: paramResolution,
          domains: paramDomainCopy,
        },
        provenance: { source: "param", createdAt: now, version: 1 },
      },
      {
        id: "surface:weierstrass",
        kind: "surface",
        source: "weierstrass",
        recipe: {
          gExpr: weierstrassGExpr,
          phiExpr: weierstrassPhiExpr,
          domain: weierstrassDomain,
          resolution: weierstrassResolution,
          recenterRescale: weierstrassRecenter,
        },
        provenance: { source: "weierstrass", createdAt: now, version: 1 },
      },
    ];

    if (meshDataset?.mesh) {
      const source = meshDataset.mesh.source;
      const linkedObjectIds =
        source.kind === "geometryObject"
          ? [
              source.objectId,
              ...(source.objects?.map((entry) => entry.objectId) ?? []),
            ].filter((id): id is string => !!id)
          : [];
      datasetItems.push({
        id: "surface:mesh",
        kind: "mesh",
        source: source.kind,
        recipe: {
          label: meshDataset.mesh.label,
          source,
        },
        mesh: embedAssets ? serializeSurfaceMeshData(meshDataset.mesh) : null,
        provenance: {
          source: source.kind,
          linkedObjectIds,
          createdAt: now,
          version: 1,
        },
      });
    }

    if (datasetKind === "volume" || volumeDatasetOverride) {
      datasetItems.push({
        id: "volume:active",
        kind: "volume",
        source: volumeDatasetOverride ? "volumeOverride" : "volumePreset",
        recipe: {
          presetId: volumePresetId,
          params: volumeParamsResolved,
          dims: volumeDims,
          sampling: volumeSamplingClamped,
          customExpr: volumeCustomExpr,
          showIsosurface: volumeShowIsosurface,
          isoValue: volumeIsoValue,
          viewMode: volumeViewMode,
          distanceSigned: volumeDistanceSigned,
        },
        provenance: {
          source: volumeDatasetOverride ? "volumeOverride" : "volumePreset",
          createdAt: now,
          version: 1,
        },
      });
    }

    const computeRecipes: WorkbookWorkspaceState["analysis"]["overlays"]["computeRecipes"] = [];
    for (const workbook of workbooks) {
      for (const stage of workbook.stages) {
        for (const block of stage.blocks) {
          if (block.type !== "compute" || !block.compute?.operatorId) continue;
          const outputs = block.compute.outputs ?? {};
          const outputKinds: string[] = [];
          if (outputs.viewPatch) outputKinds.push("viewPatch");
          if (outputs.geodesicHeat) outputKinds.push("geodesicHeat");
          if (outputs.curveOverlay) outputKinds.push("curveOverlay");
          if (outputs.directionOverlay) outputKinds.push("directionOverlay");
          if (outputs.selectionMask) outputKinds.push("selectionMask");
          if (outputs.geodesicPath) outputKinds.push("geodesicPath");
          const status: WorkbookComputeRunStatus =
            block.compute.lastRun?.status ??
            (block.compute.status === "ok"
              ? "ok"
              : block.compute.status === "failed"
                ? "failed"
                : "stale");
          computeRecipes.push({
            workbookId: workbook.id,
            stageId: stage.id,
            blockId: block.id,
            operatorId: block.compute.operatorId,
            inputRefs: block.compute.inputs ?? [],
            status,
            outputKinds,
            cachedKeys: Object.keys(block.compute.cache ?? {}),
            runCount: block.compute.runHistory?.length ?? 0,
            latestRunAt: block.compute.runHistory?.[0]?.savedAt ?? null,
          });
        }
      }
    }

    return {
      version: 2,
      savedAt: now,
      geometry: {
        mode: geometryMode,
        objects: geometryObjects.map((obj) => ({
          id: obj.id,
          type: obj.type,
          params: { ...obj.params },
          transform: {
            position: { ...obj.transform.position },
            rotation: { ...obj.transform.rotation },
            scale: { ...obj.transform.scale },
          },
          visible: obj.visible,
          material: normalizeGeometryMaterial((obj as { material?: unknown })?.material),
          name: obj.name,
          group: obj.group,
        })),
        datasetMeshObjects: geometryDatasetMeshObjects.map((obj) => serializeGeometryDatasetMeshObject(obj)),
        historyById: serializeGeometryObjectHistoryById(geometryObjectHistoryById),
        variantSets: serializeGeometryVariantSets(geometryVariantSets),
        showGhostedVariants: geometryShowAllVariantsGhosted,
        selectedVariantId: geometrySelectedVariantId,
        selectedVariantCompareId: geometrySelectedVariantCompareId,
        promotionModeDefault: geometryPromotionMode,
        selectedObjectId: geometrySelectedObjectId,
        scratchScene: geometryScratchSceneSeed,
        workbookScenes: geometryWorkbookSceneSeeds,
        derivedConstructions: geometryDerivedConstructions.slice(0, 80).map((entry) => ({
          ...entry,
          sourcePoint: entry.sourcePoint ? { ...entry.sourcePoint } : entry.sourcePoint,
          sourceNormal: entry.sourceNormal ? { ...entry.sourceNormal } : entry.sourceNormal,
          sourceVertexSignature: entry.sourceVertexSignature
            ? { point: { ...entry.sourceVertexSignature.point } }
            : entry.sourceVertexSignature,
          secondaryVertexRef: entry.secondaryVertexRef
            ? {
                objectId: entry.secondaryVertexRef.objectId,
                vertexIndex: entry.secondaryVertexRef.vertexIndex,
                point: { ...entry.secondaryVertexRef.point },
              }
            : entry.secondaryVertexRef,
          tertiaryVertexRef: entry.tertiaryVertexRef
            ? {
                objectId: entry.tertiaryVertexRef.objectId,
                vertexIndex: entry.tertiaryVertexRef.vertexIndex,
                point: { ...entry.tertiaryVertexRef.point },
              }
            : entry.tertiaryVertexRef,
          selectedEdgeRef: entry.selectedEdgeRef
            ? {
                objectId: entry.selectedEdgeRef.objectId,
                edgeVertexPair: [...entry.selectedEdgeRef.edgeVertexPair] as [number, number],
                a: { ...entry.selectedEdgeRef.a },
                b: { ...entry.selectedEdgeRef.b },
              }
            : entry.selectedEdgeRef,
          frozenSnapshot: entry.frozenSnapshot
            ? {
                origin: entry.frozenSnapshot.origin ? { ...entry.frozenSnapshot.origin } : null,
                direction: entry.frozenSnapshot.direction ? { ...entry.frozenSnapshot.direction } : null,
                groups: entry.frozenSnapshot.groups.map((group) => ({
                  ...group,
                  lines: group.lines.map((line) => line.map((point) => ({ ...point }))),
                })),
                pointSets: entry.frozenSnapshot.pointSets.map((set) => ({
                  ...set,
                  points: set.points.map((point) => ({ ...point })),
                })),
                labelSets: entry.frozenSnapshot.labelSets.map((set) => ({
                  ...set,
                  labels: set.labels.map((label) => ({ ...label, position: { ...label.position } })),
                })),
              }
            : entry.frozenSnapshot,
        })),
      },
      datasets: {
        currentDatasetRef,
        items: datasetItems,
      },
      analysis: {
        chart: {
          showChartGrid,
          chartGridDensity,
          chartMode,
          graphDomains: graphDomainCopy,
          implicitDomains: implicitDomainCopy,
          paramDomains: paramDomainCopy,
        },
        scalarFields: {
          colorMode,
          colorPalette,
          showContours,
          contourCount,
          implicitOverlay,
          showPrincipalDirections,
          showPrincipalGlyphs,
          showPrincipalLines,
          showCurvatureLines,
          showRidges,
          showValleys,
          showGaussMap,
          showBoundingBox,
          showPlanes,
          calculusScalarSource,
          calculusCustomScalarExpr,
          workbookScalarFieldNames: Array.from(workbookScalarFields.keys()),
        },
        vectorFields: {
          calculusVectorOverlayEnabled,
          calculusVectorSource,
          calculusActiveVectorField,
          calculusVectorDensity,
          calculusVectorScale,
          volumeShowStreamlines,
          volumeVectorPresetId,
          volumeStreamSeedGrid,
          volumeStreamlineStepSizeOverride,
          volumeStreamlineMaxSteps,
          volumeStreamlineMaxLength,
          workbookVectorFieldNames: Array.from(workbookVectorFields.keys()),
        },
        overlays: {
          geodesicPathEnabled,
          geodesicPathConstrain,
          geodesicPathSmooth,
          geodesicHeatEnabled,
          geodesicHeatUseContinuous,
          geodesicHeatShowHeatmap,
          geodesicDiskEnabled,
          geodesicDiskRadius,
          geodesicDiskAutoUpdate,
          geodesicDiskShowBoundary,
          geodesicDiskMethod,
          computeRecipes,
        },
      },
    };
    },
    [
      graphDomains,
      implicitDomains,
      paramDomains,
      graphSurfaceId,
      graphExpr,
      graphResolution,
      implicitSurfaceId,
      implicitExpr,
      implicitResolution,
      paramSurfaceId,
      paramXExpr,
      paramYExpr,
      paramZExpr,
      paramResolution,
      weierstrassGExpr,
      weierstrassPhiExpr,
      weierstrassDomain,
      weierstrassResolution,
      weierstrassRecenter,
      meshDataset,
      datasetKind,
      volumeDatasetOverride,
      volumePresetId,
      volumeParamsResolved,
      volumeDims,
      volumeSamplingClamped,
      volumeCustomExpr,
      volumeShowIsosurface,
      volumeIsoValue,
      volumeViewMode,
      volumeDistanceSigned,
      workbooks,
      geometryMode,
      geometryObjects,
      geometryDatasetMeshObjects,
      geometryObjectHistoryById,
      geometryVariantSets,
      geometryShowAllVariantsGhosted,
      geometrySelectedVariantId,
      geometrySelectedVariantCompareId,
      geometryPromotionMode,
      geometrySelectedObjectId,
      geometryScratchSceneSeed,
      geometryWorkbookSceneSeeds,
      geometryDerivedConstructions,
      currentDatasetRef,
      showChartGrid,
      chartGridDensity,
      chartMode,
      colorMode,
      colorPalette,
      showContours,
      contourCount,
      implicitOverlay,
      showPrincipalDirections,
      showPrincipalGlyphs,
      showPrincipalLines,
      showCurvatureLines,
      showRidges,
      showValleys,
      showGaussMap,
      showBoundingBox,
      showPlanes,
      calculusScalarSource,
      calculusCustomScalarExpr,
      workbookScalarFields,
      calculusVectorOverlayEnabled,
      calculusVectorSource,
      calculusActiveVectorField,
      calculusVectorDensity,
      calculusVectorScale,
      volumeShowStreamlines,
      volumeVectorPresetId,
      volumeStreamSeedGrid,
      volumeStreamlineStepSizeOverride,
      volumeStreamlineMaxSteps,
      volumeStreamlineMaxLength,
      workbookVectorFields,
      geodesicPathEnabled,
      geodesicPathConstrain,
      geodesicPathSmooth,
      geodesicHeatEnabled,
      geodesicHeatUseContinuous,
      geodesicHeatShowHeatmap,
      geodesicDiskEnabled,
      geodesicDiskRadius,
      geodesicDiskAutoUpdate,
      geodesicDiskShowBoundary,
      geodesicDiskMethod,
    ]
  );

  const workbookSessionPayloadWithWorkspace = useMemo<WorkbookReplayPayload>(
    () => ({
      ...workbookSessionPayload,
      workspace: buildWorkbookWorkspaceState(true),
    }),
    [workbookSessionPayload, buildWorkbookWorkspaceState]
  );

  const workbookSessionJsonWithWorkspace = useMemo(
    () =>
      JSON.stringify(
        {
          version: WORKBOOK_PROJECT_FORMAT_VERSION,
          format: WORKBOOK_PROJECT_FORMAT,
          payload: workbookSessionPayloadWithWorkspace,
        },
        null,
        2
      ),
    [workbookSessionPayloadWithWorkspace]
  );
  const workbookSessionHashWithWorkspace = useMemo(
    () => hashString(workbookSessionJsonWithWorkspace),
    [workbookSessionJsonWithWorkspace]
  );
  const workbookBundlePayload = useMemo<WorkbookReplayPayload>(
    () =>
      workbookBundleAssetMode === "embedded"
        ? workbookSessionPayloadWithWorkspace
        : {
            ...workbookSessionPayloadWithWorkspace,
            workspace: toLinkedWorkspace(workbookSessionPayloadWithWorkspace.workspace),
          },
    [workbookBundleAssetMode, workbookSessionPayloadWithWorkspace]
  );
  const workbookBundleJson = useMemo(
    () =>
      JSON.stringify(
        buildWorkbookProjectEnvelope(workbookBundlePayload, workbookBundleAssetMode, Date.now()),
        null,
        2
      ),
    [workbookBundlePayload, workbookBundleAssetMode]
  );

  const markWorkbookManualSave = useCallback(
    (hash: string, savedAt: number, fileName?: string) => {
      if (IS_REPLAY_MODE) return;
      setWorkbookManualSaveHash(hash);
      setWorkbookManualSaveAt(savedAt);
      try {
        localStorage.setItem(WORKBOOK_MANUAL_SAVE_HASH_KEY, hash);
        localStorage.setItem(WORKBOOK_MANUAL_SAVE_AT_KEY, String(savedAt));
      } catch {
        // ignore
      }
      if (fileName) {
        setWorkbookManualSaveName(fileName);
        try {
          localStorage.setItem(WORKBOOK_MANUAL_SAVE_NAME_KEY, fileName);
        } catch {
          // ignore
        }
      }
    },
    []
  );

  const applyWorkbookWorkspace = (workspace: WorkbookWorkspaceState | undefined) => {
    if (!workspace || typeof workspace !== "object") return;
    const restoredWorkspace = migrateWorkbookWorkspace(workspace);
    if (!restoredWorkspace || typeof restoredWorkspace !== "object") return;

    const geometry = restoredWorkspace.geometry;
    if (geometry && typeof geometry === "object") {
      const savedMode = String((geometry as any).mode ?? "");
      setGeometryMode(
        savedMode === "demo"
          ? "demo"
          : savedMode === "scratch"
            ? "scratch"
            : savedMode === "workbook"
              ? "workbook"
              : savedMode === "problem"
                ? "scratch"
                : "procedural"
      );
      const objects = Array.isArray(geometry.objects) ? geometry.objects : [];
      const normalized = objects
        .filter((obj) => obj && typeof obj.id === "string" && typeof obj.type === "string")
        .map((obj) => ({
          id: obj.id,
          type: obj.type,
          params: { ...(obj.params ?? {}) },
          transform: {
            position: {
              x: Number((obj.transform as any)?.position?.x ?? 0),
              y: Number((obj.transform as any)?.position?.y ?? 0),
              z: Number((obj.transform as any)?.position?.z ?? 0),
            },
            rotation: {
              x: Number((obj.transform as any)?.rotation?.x ?? 0),
              y: Number((obj.transform as any)?.rotation?.y ?? 0),
              z: Number((obj.transform as any)?.rotation?.z ?? 0),
            },
            scale: {
              x: Number((obj.transform as any)?.scale?.x ?? 1),
              y: Number((obj.transform as any)?.scale?.y ?? 1),
              z: Number((obj.transform as any)?.scale?.z ?? 1),
            },
          },
          visible: Boolean(obj.visible ?? true),
          material: normalizeGeometryMaterial(obj.material),
          name: String(obj.name ?? obj.id),
          group: typeof obj.group === "string" ? obj.group : "default",
        })) as GeometryObject[];
      const datasetMeshObjectsRaw = Array.isArray((geometry as any).datasetMeshObjects)
        ? ((geometry as any).datasetMeshObjects as WorkbookGeometryDatasetMeshObject[])
        : [];
      const normalizedDatasetMeshObjects = datasetMeshObjectsRaw
        .filter((entry) => entry && typeof entry.id === "string" && entry.mesh && typeof entry.mesh === "object")
        .map((entry) => deserializeGeometryDatasetMeshObject(entry));
      const restoredHistoryById = deserializeGeometryObjectHistoryById((geometry as any).historyById);
      const restoredObjectIds = new Set([
        ...normalized.map((entry) => entry.id),
        ...normalizedDatasetMeshObjects.map((entry) => entry.id),
      ]);
      const filteredHistoryById = filterGeometryRecordByObjectIds(restoredHistoryById, restoredObjectIds);
      setGeometryObjects(normalized);
      if (normalized.length) {
        setGeometrySelectedObjectId(geometry.selectedObjectId ?? normalized[0].id);
      } else if (normalizedDatasetMeshObjects.length) {
        const preferredId = typeof geometry.selectedObjectId === "string" ? geometry.selectedObjectId : null;
        const fallbackId = normalizedDatasetMeshObjects[0]?.id ?? null;
        const resolvedId =
          preferredId && normalizedDatasetMeshObjects.some((entry) => entry.id === preferredId)
            ? preferredId
            : fallbackId;
        setGeometrySelectedObjectId(resolvedId);
      } else {
        setGeometrySelectedObjectId(null);
      }
      setGeometryDatasetMeshObjects(normalizedDatasetMeshObjects);
      setGeometryObjectHistoryById(filteredHistoryById);
      const promotedFrozenIds = normalizedDatasetMeshObjects
        .filter((entry) => entry.promotion?.promotionMode === "frozen_baked_object")
        .map((entry) => entry.id);
      if (promotedFrozenIds.length) {
        setGeometryLockedObjectIds(new Set(promotedFrozenIds));
      } else {
        setGeometryLockedObjectIds(new Set());
      }
      setGeometryVariantSets(deserializeGeometryVariantSets((geometry as any).variantSets));
      setGeometryShowAllVariantsGhosted(Boolean((geometry as any).showGhostedVariants));
      const selectedVariantIdRaw = (geometry as any).selectedVariantId;
      setGeometrySelectedVariantId(typeof selectedVariantIdRaw === "string" ? selectedVariantIdRaw : null);
      const selectedVariantCompareIdRaw = (geometry as any).selectedVariantCompareId;
      setGeometrySelectedVariantCompareId(
        typeof selectedVariantCompareIdRaw === "string" ? selectedVariantCompareIdRaw : null
      );
      const promotionModeRaw = (geometry as any).promotionModeDefault;
      if (GEOMETRY_TO_MESH_PROMOTION_MODES.includes(promotionModeRaw)) {
        setGeometryPromotionMode(promotionModeRaw as GeometryToMeshPromotionMode);
      }
      setGeometryScratchSceneSeed(normalizeConstructionLabSeed((geometry as any).scratchScene));
      setGeometryWorkbookSceneSeeds(normalizeConstructionLabSeedRecord((geometry as any).workbookScenes));
      setGeometryDerivedConstructions(
        normalizeGeometryDerivedConstructionsForRestore((geometry as any).derivedConstructions)
      );
      setGeometrySelectedDerivedConstructionId(null);
      setGeometryConstructionHistory([]);
    }

    const datasetItems = restoredWorkspace.datasets?.items ?? [];
    const byId = new Map(datasetItems.map((item) => [item.id, item]));

    const graphRecipe = byId.get("surface:graph")?.recipe as any;
    if (graphRecipe) {
      if (typeof graphRecipe.surfaceId === "string") setGraphSurfaceId(graphRecipe.surfaceId as SurfaceId);
      if (typeof graphRecipe.expr === "string") setGraphExpr(graphRecipe.expr);
      if (Number.isFinite(graphRecipe.resolution)) setGraphResolution(Math.max(10, Math.round(graphRecipe.resolution)));
      if (graphRecipe.domains && typeof graphRecipe.domains === "object") {
        const next: Record<string, GraphDomain> = {};
        for (const [id, domain] of Object.entries(graphRecipe.domains as Record<string, any>)) {
          next[id] = normalizeGraphDomain(
            { xSpan: Number(domain?.xSpan), ySpan: Number(domain?.ySpan) },
            getDefaultGraphSpan(id as SurfaceId)
          );
        }
        setGraphDomains(next);
      }
    }

    const implicitRecipe = byId.get("surface:implicit")?.recipe as any;
    if (implicitRecipe) {
      if (typeof implicitRecipe.surfaceId === "string") setImplicitSurfaceId(implicitRecipe.surfaceId as SurfaceId);
      if (typeof implicitRecipe.expr === "string") setImplicitExpr(implicitRecipe.expr);
      if (Number.isFinite(implicitRecipe.resolution)) {
        setImplicitResolution(Math.max(8, Math.round(implicitRecipe.resolution)));
      }
      if (implicitRecipe.domains && typeof implicitRecipe.domains === "object") {
        const next: Record<string, ImplicitDomain> = {};
        for (const [id, domain] of Object.entries(implicitRecipe.domains as Record<string, any>)) {
          next[id] = normalizeImplicitDomain(
            { xSpan: Number(domain?.xSpan), ySpan: Number(domain?.ySpan) },
            getDefaultImplicitDomain(id as SurfaceId)
          );
        }
        setImplicitDomains(next);
      }
    }

    const paramRecipe = byId.get("surface:param")?.recipe as any;
    if (paramRecipe) {
      if (typeof paramRecipe.surfaceId === "string") setParamSurfaceId(paramRecipe.surfaceId as ParamSurfaceId);
      if (typeof paramRecipe.xExpr === "string") setParamXExpr(paramRecipe.xExpr);
      if (typeof paramRecipe.yExpr === "string") setParamYExpr(paramRecipe.yExpr);
      if (typeof paramRecipe.zExpr === "string") setParamZExpr(paramRecipe.zExpr);
      if (Number.isFinite(paramRecipe.resolution)) setParamResolution(Math.max(10, Math.round(paramRecipe.resolution)));
      if (paramRecipe.domains && typeof paramRecipe.domains === "object") {
        const next: Record<string, ParamDomain> = {};
        for (const [id, domain] of Object.entries(paramRecipe.domains as Record<string, any>)) {
          next[id] = normalizeParamDomain(
            {
              uMin: Number(domain?.uMin),
              uMax: Number(domain?.uMax),
              vMin: Number(domain?.vMin),
              vMax: Number(domain?.vMax),
            },
            getParamDomainPreviewBounds(id as ParamSurfaceId)
          );
        }
        setParamDomains(next);
      }
    }

    const weierstrassRecipe = byId.get("surface:weierstrass")?.recipe as any;
    if (weierstrassRecipe) {
      if (typeof weierstrassRecipe.gExpr === "string") setWeierstrassGExpr(weierstrassRecipe.gExpr);
      if (typeof weierstrassRecipe.phiExpr === "string") setWeierstrassPhiExpr(weierstrassRecipe.phiExpr);
      if (weierstrassRecipe.domain && typeof weierstrassRecipe.domain === "object") {
        setWeierstrassDomain(
          normalizeParamDomain(
            {
              uMin: Number((weierstrassRecipe.domain as any).uMin),
              uMax: Number((weierstrassRecipe.domain as any).uMax),
              vMin: Number((weierstrassRecipe.domain as any).vMin),
              vMax: Number((weierstrassRecipe.domain as any).vMax),
            },
            WEIERSTRASS_DEFAULTS.domain
          )
        );
      }
      if (Number.isFinite(weierstrassRecipe.resolution)) {
        setWeierstrassResolution(Math.max(10, Math.round(weierstrassRecipe.resolution)));
      }
      if (typeof weierstrassRecipe.recenterRescale === "boolean") {
        setWeierstrassRecenter(weierstrassRecipe.recenterRescale);
      }
    }

    const meshItem = byId.get("surface:mesh");
    if (meshItem?.mesh) {
      const mesh = applySurfaceMeshOps(deserializeSurfaceMeshData(meshItem.mesh));
      setMeshDataset(mesh);
      setDatasetKind("mesh");
      setSurfaceViewerKind("mesh");
    }

    const volumeRecipe = byId.get("volume:active")?.recipe as any;
    if (volumeRecipe) {
      if (
        typeof volumeRecipe.presetId === "string" &&
        VOLUME_PRESETS.some((preset) => preset.id === volumeRecipe.presetId)
      ) {
        setVolumePresetId(volumeRecipe.presetId as VolumePresetId);
      }
      if (
        Array.isArray(volumeRecipe.dims) &&
        volumeRecipe.dims.length === 3 &&
        volumeRecipe.dims.every((v: unknown) => Number.isFinite(Number(v)))
      ) {
        setVolumeDims([
          Math.max(8, Math.round(Number(volumeRecipe.dims[0]))),
          Math.max(8, Math.round(Number(volumeRecipe.dims[1]))),
          Math.max(8, Math.round(Number(volumeRecipe.dims[2]))),
        ]);
      }
      if (volumeRecipe.params && typeof volumeRecipe.params === "object") {
        setVolumeParams(volumeRecipe.params as VolumePresetParams);
      }
      if (typeof volumeRecipe.customExpr === "string") setVolumeCustomExpr(volumeRecipe.customExpr);
      if (typeof volumeRecipe.showIsosurface === "boolean") setVolumeShowIsosurface(volumeRecipe.showIsosurface);
      if (Number.isFinite(volumeRecipe.isoValue)) setVolumeIsoValue(Number(volumeRecipe.isoValue));
      if (volumeRecipe.viewMode === "slices" || volumeRecipe.viewMode === "3d") {
        setVolumeViewMode(volumeRecipe.viewMode);
      }
      if (typeof volumeRecipe.distanceSigned === "boolean") {
        setVolumeDistanceSigned(volumeRecipe.distanceSigned);
      }
    }

    const currentRef = restoredWorkspace.datasets?.currentDatasetRef ?? "";
    if (currentRef.startsWith("graph:")) {
      setDatasetKind("surface");
      setSurfaceViewerKind("graph");
    } else if (currentRef.startsWith("implicit:")) {
      setDatasetKind("surface");
      setSurfaceViewerKind("implicit");
    } else if (currentRef.startsWith("param:")) {
      setDatasetKind("surface");
      setSurfaceViewerKind("param");
    } else if (currentRef.startsWith("weierstrass:")) {
      setDatasetKind("surface");
      setSurfaceViewerKind("weierstrass");
    } else if (currentRef.startsWith("mesh:")) {
      setDatasetKind("mesh");
      setSurfaceViewerKind("mesh");
    } else if (currentRef.startsWith("volume:")) {
      setDatasetKind("volume");
    }

    const chart = restoredWorkspace.analysis?.chart;
    if (chart) {
      setShowChartGrid(Boolean(chart.showChartGrid));
      if (Number.isFinite(chart.chartGridDensity)) {
        setChartGridDensity(Math.max(2, Math.min(64, Math.round(chart.chartGridDensity))));
      }
      if (chart.chartMode === "auto" || chart.chartMode === "xy" || chart.chartMode === "uv" || chart.chartMode === "local") {
        setChartMode(chart.chartMode);
      }
    }

    const scalars = restoredWorkspace.analysis?.scalarFields;
    if (scalars) {
      setColorMode(scalars.colorMode);
      setColorPalette(scalars.colorPalette);
      setShowContours(Boolean(scalars.showContours));
      if (Number.isFinite(scalars.contourCount)) setContourCount(Math.max(2, Math.round(scalars.contourCount)));
      if (scalars.implicitOverlay === "none" || scalars.implicitOverlay === "normals" || scalars.implicitOverlay === "curvature") {
        setImplicitOverlay(scalars.implicitOverlay);
      }
      setShowPrincipalDirections(Boolean(scalars.showPrincipalDirections));
      setShowPrincipalGlyphs(Boolean(scalars.showPrincipalGlyphs));
      setShowPrincipalLines(Boolean(scalars.showPrincipalLines));
      setShowCurvatureLines(Boolean(scalars.showCurvatureLines));
      setShowRidges(Boolean(scalars.showRidges));
      setShowValleys(Boolean(scalars.showValleys));
      setShowGaussMap(Boolean(scalars.showGaussMap));
      setShowBoundingBox(Boolean(scalars.showBoundingBox));
      setShowPlanes(Boolean(scalars.showPlanes));
      if (typeof scalars.calculusScalarSource === "string") setCalculusScalarSource(scalars.calculusScalarSource);
      if (typeof scalars.calculusCustomScalarExpr === "string") setCalculusCustomScalarExpr(scalars.calculusCustomScalarExpr);
    }

    const vectors = restoredWorkspace.analysis?.vectorFields;
    if (vectors) {
      setCalculusVectorOverlayEnabled(Boolean(vectors.calculusVectorOverlayEnabled));
      if (typeof vectors.calculusVectorSource === "string") setCalculusVectorSource(vectors.calculusVectorSource);
      if (typeof vectors.calculusActiveVectorField === "string") setCalculusActiveVectorField(vectors.calculusActiveVectorField);
      if (Number.isFinite(vectors.calculusVectorDensity)) {
        setCalculusVectorDensity(Math.max(10, Math.round(vectors.calculusVectorDensity)));
      }
      if (Number.isFinite(vectors.calculusVectorScale)) {
        setCalculusVectorScale(Math.max(0.01, Number(vectors.calculusVectorScale)));
      }
      setVolumeShowStreamlines(Boolean(vectors.volumeShowStreamlines));
      if (typeof vectors.volumeVectorPresetId === "string" && VECTOR_PRESETS.some((p) => p.id === vectors.volumeVectorPresetId)) {
        setVolumeVectorPresetId(vectors.volumeVectorPresetId as VectorPresetId);
      }
      if (Number.isFinite(vectors.volumeStreamSeedGrid)) setVolumeStreamSeedGrid(Math.max(1, Math.round(vectors.volumeStreamSeedGrid)));
      if (vectors.volumeStreamlineStepSizeOverride == null || Number.isFinite(vectors.volumeStreamlineStepSizeOverride)) {
        setVolumeStreamlineStepSizeOverride(
          vectors.volumeStreamlineStepSizeOverride == null ? null : Number(vectors.volumeStreamlineStepSizeOverride)
        );
      }
      if (Number.isFinite(vectors.volumeStreamlineMaxSteps)) {
        setVolumeStreamlineMaxSteps(Math.max(1, Math.round(vectors.volumeStreamlineMaxSteps)));
      }
    }

    const overlays = restoredWorkspace.analysis?.overlays;
    if (overlays) {
      setGeodesicPathEnabled(Boolean(overlays.geodesicPathEnabled));
      setGeodesicPathConstrain(Boolean(overlays.geodesicPathConstrain));
      setGeodesicPathSmooth(Boolean(overlays.geodesicPathSmooth));
      setGeodesicHeatEnabled(Boolean(overlays.geodesicHeatEnabled));
      setGeodesicHeatUseContinuous(Boolean(overlays.geodesicHeatUseContinuous));
      setGeodesicHeatShowHeatmap(Boolean(overlays.geodesicHeatShowHeatmap));
      setGeodesicDiskEnabled(Boolean(overlays.geodesicDiskEnabled));
      if (Number.isFinite(overlays.geodesicDiskRadius)) setGeodesicDiskRadius(Number(overlays.geodesicDiskRadius));
      setGeodesicDiskAutoUpdate(Boolean(overlays.geodesicDiskAutoUpdate));
      setGeodesicDiskShowBoundary(Boolean(overlays.geodesicDiskShowBoundary));
      if (overlays.geodesicDiskMethod === "heat" || overlays.geodesicDiskMethod === "dijkstra") {
        setGeodesicDiskMethod(overlays.geodesicDiskMethod);
      }
    }
  };

  const applyWorkbookPayload = useCallback(
    (raw: unknown) => {
      if (IS_REPLAY_MODE) return false;
      const parsed = raw as any;
      const payloadLike: WorkbookReplayPayload = Array.isArray(parsed)
        ? { workbooks: parsed }
        : (parsed as WorkbookReplayPayload);
      const migratedPayload = migrateWorkbookReplayPayload(payloadLike);
      const nextWorkbooks: Workbook[] = Array.isArray(migratedPayload?.workbooks)
        ? migratedPayload.workbooks
        : [];
      if (!nextWorkbooks.length) return false;
      const normalized = normalizeWorkbooks(nextWorkbooks);
      const firstWorkbook = normalized[0];
      if (!firstWorkbook) return false;
      setWorkbooks(normalized);
      const nextActive =
        typeof migratedPayload?.activeWorkbookId === "string" &&
        normalized.some((w) => w.id === migratedPayload.activeWorkbookId)
          ? migratedPayload.activeWorkbookId
          : firstWorkbook.id;
      const nextStage: WorkbookStageId = migratedPayload?.activeStageId ?? "define";
      setActiveWorkbookId(nextActive);
      setActiveStageId(nextStage);
      if (migratedPayload?.workspace) {
        applyWorkbookWorkspace(migratedPayload.workspace as WorkbookWorkspaceState);
      }
      const nextHash = hashString(
        JSON.stringify(
          {
            version: WORKBOOK_PROJECT_FORMAT_VERSION,
            format: WORKBOOK_PROJECT_FORMAT,
            payload: {
              workbooks: normalized,
              activeWorkbookId: nextActive,
              activeStageId: nextStage,
            },
          },
          null,
          2
        )
      );
      markWorkbookManualSave(nextHash, Date.now());
      workbookAutosaveHashRef.current = nextHash;
      return true;
    },
    [markWorkbookManualSave]
  );

  const commitWorkbookAutosave = useCallback(() => {
    if (IS_REPLAY_MODE) return;
    if (workbookAutosaveHashRef.current === workbookSessionHashWithWorkspace) return;
    const entry: WorkbookStoredSession = {
      savedAt: Date.now(),
      payload: workbookSessionPayloadWithWorkspace,
    };
    try {
      localStorage.setItem(WORKBOOK_AUTOSAVE_KEY, JSON.stringify(entry));
      const journal = safeParseArray<WorkbookAutosaveJournalEntry>(localStorage.getItem(WORKBOOK_AUTOSAVE_JOURNAL_KEY))
        .filter(
          (item) =>
            !!item &&
            typeof item.id === "string" &&
            Number.isFinite(item.savedAt) &&
            typeof item.hash === "string" &&
            isWorkbookReplayPayload(item.payload)
        );
      journal.push({
        id: makeId(),
        savedAt: entry.savedAt,
        hash: workbookSessionHashWithWorkspace,
        payload: entry.payload,
      });
      localStorage.setItem(
        WORKBOOK_AUTOSAVE_JOURNAL_KEY,
        JSON.stringify(journal.slice(-WORKBOOK_AUTOSAVE_JOURNAL_LIMIT))
      );
      setWorkbookAutosaveAt(entry.savedAt);
      workbookAutosaveHashRef.current = workbookSessionHashWithWorkspace;
    } catch {
      // ignore
    }
  }, [workbookSessionPayloadWithWorkspace, workbookSessionHashWithWorkspace]);

  useEffect(() => {
    if (IS_REPLAY_MODE) return;
    const timer = window.setTimeout(() => {
      commitWorkbookAutosave();
    }, WORKBOOK_AUTOSAVE_DEBOUNCE_MS);
    return () => window.clearTimeout(timer);
  }, [commitWorkbookAutosave, workbookSessionHashWithWorkspace]);

  useEffect(() => {
    if (IS_REPLAY_MODE) return;
    const interval = window.setInterval(() => {
      commitWorkbookAutosave();
    }, WORKBOOK_AUTOSAVE_INTERVAL_SEC * 1000);
    return () => window.clearInterval(interval);
  }, [commitWorkbookAutosave]);

  useEffect(() => {
    if (IS_REPLAY_MODE) return;
    if (recoveryPromptShownRef.current) return;
    recoveryPromptShownRef.current = true;
    const stored = safeParseObject<WorkbookStoredSession>(localStorage.getItem(WORKBOOK_AUTOSAVE_KEY));
    if (!stored || !isWorkbookReplayPayload(stored.payload) || !Number.isFinite(stored.savedAt)) return;
    const params = new URLSearchParams(window.location.search);
    const shouldSkipRecovery = params.get("memoryGuardRecovery") === "1" || params.get("skipAutosaveRecovery") === "1";
    if (shouldSkipRecovery) {
      const url = new URL(window.location.href);
      url.searchParams.delete("memoryGuardRecovery");
      url.searchParams.delete("skipAutosaveRecovery");
      window.history.replaceState(null, document.title, `${url.pathname}${url.search}${url.hash}`);
      return;
    }
    const dismissedAt = Number(localStorage.getItem(WORKBOOK_AUTOSAVE_RECOVERY_DISMISSED_AT_KEY));
    if (Number.isFinite(dismissedAt) && dismissedAt >= stored.savedAt) return;
    const manualAt = workbookManualSaveAt ?? 0;
    if (stored.savedAt <= manualAt) return;
    const message = `Recover last autosave from ${new Date(stored.savedAt).toLocaleString()}?`;
    if (!window.confirm(message)) {
      try {
        localStorage.setItem(WORKBOOK_AUTOSAVE_RECOVERY_DISMISSED_AT_KEY, String(stored.savedAt));
      } catch {
        // ignore
      }
      return;
    }
    try {
      localStorage.removeItem(WORKBOOK_AUTOSAVE_RECOVERY_DISMISSED_AT_KEY);
    } catch {
      // ignore
    }
    if (!applyWorkbookPayload(stored.payload)) return;
    const restoredHash = hashString(
      JSON.stringify(
        {
          version: WORKBOOK_PROJECT_FORMAT_VERSION,
          format: WORKBOOK_PROJECT_FORMAT,
          payload: stored.payload,
        },
        null,
        2
      )
    );
    const recoveredName = workbookManualSaveName || "recovered-session.math3d";
    markWorkbookManualSave(restoredHash, stored.savedAt, ensureMath3dExtension(recoveredName));
  }, [applyWorkbookPayload, markWorkbookManualSave, workbookManualSaveAt, workbookManualSaveName]);

  const persistWorkbookSnapshots = useCallback((next: WorkbookNamedSnapshot[]) => {
    setWorkbookSnapshots(next);
    if (IS_REPLAY_MODE) return;
    try {
      if (next.length) {
        localStorage.setItem(WORKBOOK_SNAPSHOT_HISTORY_KEY, JSON.stringify(next));
        localStorage.setItem(
          WORKBOOK_SNAPSHOT_KEY,
          JSON.stringify({ savedAt: next[0].savedAt, payload: next[0].payload } satisfies WorkbookStoredSession)
        );
      } else {
        localStorage.removeItem(WORKBOOK_SNAPSHOT_HISTORY_KEY);
        localStorage.removeItem(WORKBOOK_SNAPSHOT_KEY);
      }
    } catch {
      // ignore
    }
  }, []);

  const handleSaveWorkbookAs = useCallback(() => {
    const base =
      workbooks.length > 1
        ? "math3d-book"
        : sanitizeFileBase(activeWorkbook?.title ?? "workbook", "workbook");
    const fileName = `${base}-${new Date().toISOString().slice(0, 10)}.math3d`;
    downloadTextFile(workbookBundleJson, fileName, "application/json");
    markWorkbookManualSave(workbookSessionHash, Date.now(), fileName);
  }, [workbookBundleJson, workbookSessionHash, workbooks.length, activeWorkbook, markWorkbookManualSave]);

  const handleSaveWorkbook = useCallback(() => {
    const base =
      workbooks.length > 1
        ? "math3d-book"
        : sanitizeFileBase(activeWorkbook?.title ?? "workbook", "workbook");
    const defaultName = `${base}-${new Date().toISOString().slice(0, 10)}.math3d`;
    const fileName = ensureMath3dExtension(workbookManualSaveName || defaultName);
    downloadTextFile(workbookBundleJson, fileName, "application/json");
    markWorkbookManualSave(workbookSessionHash, Date.now(), fileName);
  }, [
    workbookBundleJson,
    workbookSessionHash,
    workbookManualSaveName,
    workbooks.length,
    activeWorkbook,
    markWorkbookManualSave,
  ]);

  const handleSnapshotWorkbookSession = useCallback((name?: string) => {
    if (IS_REPLAY_MODE) return;
    const savedAt = Date.now();
    const cleanName = (name ?? "").trim();
    const entry: WorkbookStoredSession = {
      savedAt,
      payload: workbookSessionPayloadWithWorkspace,
    };
    const named: WorkbookNamedSnapshot = {
      id: makeId(),
      name: cleanName || `Snapshot ${new Date(savedAt).toLocaleString()}`,
      savedAt,
      payload: entry.payload,
    };
    setSelectedWorkbookSnapshotId(named.id);
    persistWorkbookSnapshots(
      normalizeSnapshotHistory([named, ...workbookSnapshots]).slice(0, WORKBOOK_SNAPSHOT_HISTORY_LIMIT)
    );
  }, [persistWorkbookSnapshots, workbookSessionPayloadWithWorkspace, workbookSnapshots]);

  const resolveTaskMeasuredObjectById = useCallback(
    (objectId: string): WorkbookGeometryTaskMeasuredObject | null => {
      const resolved = resolveGeometrySceneMeshById(objectId);
      if (!resolved) return null;
      const metrics = computeTriangleMeshGeometricMetrics(resolved.mesh);
      return {
        label: resolved.object.name,
        volume: metrics.volume,
        surfaceArea: metrics.surfaceArea,
        vertexCount: metrics.vertexCount,
        faceCount: metrics.faceCount,
        width: metrics.dimensions?.x ?? 0,
        height: metrics.dimensions?.y ?? 0,
        depth: metrics.dimensions?.z ?? 0,
      };
    },
    [resolveGeometrySceneMeshById]
  );

  const resolveWorkbookGeometryTaskValidationContext = useCallback((): WorkbookGeometryTaskValidationContext => {
    const selectedId = geometrySelectedSceneObject?.id ?? null;
    const primary =
      (selectedId ? resolveTaskMeasuredObjectById(selectedId) : null) ??
      (geometryCompareObjectAId ? resolveTaskMeasuredObjectById(geometryCompareObjectAId) : null);

    let comparison: WorkbookGeometryTaskMeasuredObject | null = null;
    if (geometryCompareObjectBId && geometryCompareObjectBId !== selectedId) {
      comparison = resolveTaskMeasuredObjectById(geometryCompareObjectBId);
    }
    if (!comparison && geometryCompareObjectAId && geometryCompareObjectAId !== selectedId) {
      comparison = resolveTaskMeasuredObjectById(geometryCompareObjectAId);
    }

    return { primary, comparison };
  }, [
    geometryCompareObjectAId,
    geometryCompareObjectBId,
    geometrySelectedSceneObject?.id,
    resolveTaskMeasuredObjectById,
  ]);

  const handleValidateWorkbookGeometryTask = useCallback(() => {
    if (IS_REPLAY_MODE) return;
    if (!activeWorkbookId) return;
    const activeGeometryTask = activeWorkbook?.geometryTask;
    if (!activeGeometryTask) return;
    const report = evaluateWorkbookGeometryTask(
      activeGeometryTask.spec,
      resolveWorkbookGeometryTaskValidationContext()
    );
    const nextAssertStatus: NonNullable<WorkbookBlock["assert"]>["status"] =
      report.status === "pass" ? "pass" : report.status === "fail" ? "fail" : "pending";
    setWorkbooks((prev) =>
      prev.map((workbook) => {
        if (workbook.id !== activeWorkbookId) return workbook;
        let patchedAssert = false;
        return {
          ...workbook,
          updatedAt: Date.now(),
          geometryTask: {
            ...(workbook.geometryTask ?? activeGeometryTask),
            lastValidation: report,
          },
          stages: workbook.stages.map((stage) =>
            stage.id !== "explain"
              ? stage
              : {
                  ...stage,
                  blocks: stage.blocks.map((block) => {
                    if (patchedAssert || block.type !== "assert") return block;
                    patchedAssert = true;
                    return {
                      ...block,
                      assert: {
                        ...(block.assert ?? { expected: "", status: "pending" }),
                        status: nextAssertStatus,
                      },
                    };
                  }),
                }
          ),
        };
      })
    );
    setGeometryCreateActionStatus(`Task validation: ${report.summary}`);
  }, [
    activeWorkbook,
    activeWorkbookId,
    resolveWorkbookGeometryTaskValidationContext,
  ]);

  const handleSaveWorkbookGeometryTaskSolutionSnapshot = useCallback(() => {
    if (IS_REPLAY_MODE) return;
    if (!activeWorkbookId) return;
    const taskTitle = activeWorkbook?.geometryTask?.spec.title ?? "Geometry task";
    const snapshotName = `Solution - ${taskTitle}`;
    const savedAt = Date.now();
    const namedId = makeId();
    const named: WorkbookNamedSnapshot = {
      id: namedId,
      name: snapshotName,
      savedAt,
      payload: workbookSessionPayloadWithWorkspace,
    };
    setSelectedWorkbookSnapshotId(named.id);
    persistWorkbookSnapshots(
      normalizeSnapshotHistory([named, ...workbookSnapshots]).slice(0, WORKBOOK_SNAPSHOT_HISTORY_LIMIT)
    );
    setWorkbooks((prev) =>
      prev.map((workbook) => {
        if (workbook.id !== activeWorkbookId) return workbook;
        const existing = workbook.geometryTask?.solutionSnapshotIds ?? [];
        const deduped = [namedId, ...existing.filter((id) => id !== namedId)].slice(0, 24);
        return {
          ...workbook,
          updatedAt: Date.now(),
          geometryTask: workbook.geometryTask
            ? { ...workbook.geometryTask, solutionSnapshotIds: deduped }
            : workbook.geometryTask,
        };
      })
    );
  }, [
    activeWorkbook?.geometryTask?.spec.title,
    activeWorkbookId,
    persistWorkbookSnapshots,
    workbookSessionPayloadWithWorkspace,
    workbookSnapshots,
  ]);

  const handleRestoreWorkbookSnapshotById = useCallback(
    (snapshotId: string) => {
      if (IS_REPLAY_MODE) return;
      const found = workbookSnapshots.find((snap) => snap.id === snapshotId);
      if (!found || !isWorkbookReplayPayload(found.payload)) return;
      if (!applyWorkbookPayload(found.payload)) return;
      const restoredHash = hashString(
        JSON.stringify(
          {
            version: WORKBOOK_PROJECT_FORMAT_VERSION,
            format: WORKBOOK_PROJECT_FORMAT,
            payload: found.payload,
          },
          null,
          2
        )
      );
      markWorkbookManualSave(restoredHash, found.savedAt, workbookManualSaveName || "restored-snapshot.math3d");
    },
    [workbookSnapshots, applyWorkbookPayload, markWorkbookManualSave, workbookManualSaveName]
  );

