  const applySurfaceMeshTopologyEdit = useCallback(
    (
      actionLabel: string,
      traceOperation: string,
      operationHistoryLabel: string,
      labelSuffix: string,
      targetLabel: string,
      paramsLabel: string,
      selectedResultLabel: string,
      edit: (mesh: SurfaceMeshData) => SurfaceMeshData,
      sourceMeshOverride?: SurfaceMeshData | null,
      afterApply?: (context: {
        beforeCounts: { vertexCount: number; faceCount: number };
        afterCounts: { vertexCount: number; faceCount: number };
        edited: SurfaceMeshData;
      }) => void
    ) => {
      setSurfaceMeshOpsError(null);
      setSurfaceMeshTopologyStatus(null);
      setSurfaceMeshTopologyHistoryPreviewId(null);
      const sourceMesh = sourceMeshOverride ?? surfaceMeshData;
      if (!sourceMesh?.positions?.length) {
        setSurfaceMeshTopologyStatus("Surface mesh not ready yet.");
        return;
      }
      try {
        const beforeCounts = countTriangleMeshTopology(sourceMesh);
        const baseLabel = sourceMesh.label ?? "Surface mesh";
        const base = cloneSurfaceMeshData(sourceMesh, `${baseLabel} (${labelSuffix})`);
        const edited = applySurfaceMeshOps(edit(base));
        const afterCounts = countTriangleMeshTopology(edited);
        const topologyAction =
          traceOperation.includes("face-subdivide")
            ? "face-subdivide"
            : traceOperation.includes("face-extrude")
            ? "face-extrude"
            : traceOperation.includes("face-inset")
            ? "face-inset"
            : traceOperation.includes("split-edge")
            ? "edge-split"
            : traceOperation.includes("collapse-edge")
            ? "edge-collapse"
            : traceOperation.includes("bevel-edge")
            ? "edge-bevel"
            : traceOperation.includes("vertex-move")
            ? "vertex-move"
            : "mesh-topology";
        setSurfaceMeshTopologyFeedback(
          buildTopologyEditFeedback(
            "mesh-workspace",
            topologyAction,
            operationHistoryLabel,
            sourceMesh,
            edited,
            edited
          )
        );
        const historyEntry: SurfaceMeshTopologyHistoryEntry = {
          id: makeId(),
          at: Date.now(),
          actionLabel,
          sourceLabel: baseLabel,
          targetLabel,
          paramsLabel,
          definition: buildSurfaceMeshTopologyDefinition({
            actionLabel,
            sourceLabel: baseLabel,
            targetLabel,
            paramsLabel,
            beforeCounts,
          }),
          resultLabel: buildTopologyEditSummary(topologyAction, targetLabel, beforeCounts, afterCounts),
          beforeCounts,
          afterCounts,
          selectedResultLabel,
          beforeSnapshot: cloneSurfaceMeshData(sourceMesh, sourceMesh.label),
          snapshot: cloneSurfaceMeshData(edited, edited.label),
        };
        const meshActionPulseId = `mesh:${topologyAction}`;
        setContextualActionPulseId(meshActionPulseId);
        const appliedCountsLabel = formatContextualViewportPreviewCounts(beforeCounts, afterCounts);
        const appliedPreviewOperation: ContextualViewportPreviewOperation =
          topologyAction === "face-subdivide"
            ? "Subdivide"
            : topologyAction === "face-extrude"
              ? "Extrude"
              : topologyAction === "face-inset"
                ? "Inset"
            : topologyAction === "edge-collapse"
              ? "Collapse"
              : topologyAction === "edge-bevel"
                ? "Bevel"
                : topologyAction === "edge-split"
                  ? "Split"
                  : topologyAction === "vertex-move"
                    ? "Move"
                    : "Split";
        showAppliedContextualViewportPreview(
          "Mesh",
          buildContextualViewportPreview({
            workspace: "Mesh",
            operation: appliedPreviewOperation,
            selectedEntity: targetLabel,
            label: historyEntry.resultLabel,
            actionPulseId: meshActionPulseId,
            details: [{ label: "Counts", value: appliedCountsLabel }],
        overlays: surfaceMeshAccessibleCommandPreviewOverlays ?? surfaceMeshCommandPreviewOverlays,
          }),
          `${historyEntry.resultLabel}, ${appliedCountsLabel}`
        );
        setSurfaceMeshTopologyHistory((prev) => [historyEntry, ...prev].slice(0, 24));
        setSelectedSurfaceMeshTopologyHistoryId(historyEntry.id);
        setMeshDataset(edited, traceOperation);
        afterApply?.({ beforeCounts, afterCounts, edited });
        appendMeshPromotionOperation(operationHistoryLabel);
        setSurfaceMeshTopologyStatus(`${actionLabel}: ${historyEntry.resultLabel}. Selected ${selectedResultLabel}.`);
        handleChangeViewerKind("mesh");
      } catch (err: any) {
        setSurfaceMeshTopologyFeedback(null);
        setSurfaceMeshTopologyStatus(formatMeshEditFailureMessage(actionLabel, err?.message ?? `${actionLabel} failed.`));
      }
    },
    [
      appendMeshPromotionOperation,
      handleChangeViewerKind,
      setMeshDataset,
      showAppliedContextualViewportPreview,
      surfaceMeshCommandPreviewOverlays,
      surfaceMeshData,
    ]
  );

