    nurbsKnotUText,
    nurbsKnotVText,
    nurbsWeightsText,
    paramSurfaceId,
    paramXExpr,
    paramYExpr,
    paramZExpr,
    rotationalProfileMode,
    rotationalProfilePointsText,
    rotationalProfileRExpr,
    rotationalProfileZExpr,
    surfaceFormulaEditorShowsRotationalFields,
