                  const renderedThumb = makePresetThumb(preset.id, preset.label, preset.operation, "mesh", "rendered");
                  const thumb = thumbByViewMode(renderedThumb, diagramThumb, cardViewMode);
                  const summary = compactSummary(preset.summary);
