/* ---------------- Domain previews (SVG) ---------------- */

type XYDomainPreviewProps = {
  width: number;
  height: number;
  xSpan: number; // shows x in [-xSpan, xSpan]
  ySpan: number; // shows y in [-ySpan, ySpan]
  onPick: (xy: { x: number; y: number }) => void;
  picked?: { x: number; y: number } | null;
  mode?: "click" | "hover";
  dragToPick?: boolean;
};

const XYDomainPreview = React.memo(function XYDomainPreview({
  width,
  height,
  xSpan,
  ySpan,
  onPick,
  picked: pickedProp,
  mode = "click",
  dragToPick = false,
}: XYDomainPreviewProps) {
  const [picked, setPicked] = useState<{ x: number; y: number } | null>(null);
  const [hovered, setHovered] = useState<{ x: number; y: number } | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const isPointerInsideRef = useRef(false);
  const safeXSpan = Number.isFinite(xSpan) && xSpan > 0 ? xSpan : 1;
  const safeYSpan = Number.isFinite(ySpan) && ySpan > 0 ? ySpan : 1;
  const hoverTimerRef = useRef<number | null>(null);
  const pendingHoverRef = useRef<{ x: number; y: number; updateLocal: boolean } | null>(null);
  const lastSentRef = useRef<{ x: number; y: number } | null>(null);
  const HOVER_PICK_INTERVAL_MS = 90;

  const pushPick = useCallback(
    (xy: { x: number; y: number }, updateLocal = true) => {
      if (updateLocal) setPicked(xy);
      onPick(xy);
      lastSentRef.current = xy;
    },
    [onPick]
  );

  const flushHoverPick = useCallback(() => {
    if (hoverTimerRef.current != null) {
      window.clearTimeout(hoverTimerRef.current);
      hoverTimerRef.current = null;
    }
    const pending = pendingHoverRef.current;
    pendingHoverRef.current = null;
    if (!pending) return;
    const next = { x: pending.x, y: pending.y };

    const last = lastSentRef.current;
    const epsX = safeXSpan * 0.01;
    const epsY = safeYSpan * 0.01;
    if (last && Math.abs(next.x - last.x) <= epsX && Math.abs(next.y - last.y) <= epsY) {
      return;
    }
    pushPick(next, pending.updateLocal);
  }, [pushPick, safeXSpan, safeYSpan]);

  const scheduleHoverPick = useCallback(
    (xy: { x: number; y: number }, updateLocal: boolean) => {
      pendingHoverRef.current = { ...xy, updateLocal };
      if (hoverTimerRef.current != null) return;
      hoverTimerRef.current = window.setTimeout(() => {
        flushHoverPick();
      }, HOVER_PICK_INTERVAL_MS);
    },
    [flushHoverPick]
  );

  useEffect(() => {
    if (!pickedProp) return;
    if (mode === "hover" && isPointerInsideRef.current) return;
    setPicked(pickedProp);
    lastSentRef.current = pickedProp;
  }, [mode, pickedProp?.x, pickedProp?.y]);

  useEffect(
    () => () => {
      if (hoverTimerRef.current != null) {
        window.clearTimeout(hoverTimerRef.current);
        hoverTimerRef.current = null;
      }
    },
    []
  );

  const pad = 12;
  const w = width;
  const h = height;

  const toXY = (clientX: number, clientY: number, svg: SVGSVGElement) => {
    const r = svg.getBoundingClientRect();
    const px = (clientX - r.left - pad) / (r.width - 2 * pad);
    const py = (clientY - r.top - pad) / (r.height - 2 * pad);
    const x = (px * 2 - 1) * safeXSpan;
    const y = (1 - py * 2) * safeYSpan;
    return { x, y };
  };

  const toPx = (x: number, y: number) => {
    const px = pad + ((x / safeXSpan + 1) * 0.5) * (w - 2 * pad);
    const py = pad + ((1 - (y / safeYSpan + 1) * 0.5) * (h - 2 * pad));
    return { px, py };
  };

  const gridLines = 8;

  return (
    <div style={{ border: "1px solid #dbe4ee", borderRadius: 12, overflow: "hidden", background: "#ffffff" }}>
      <svg
        width={w}
        height={h}
        style={{ display: "block", cursor: "crosshair" }}
        onMouseDown={(e) => {
          if (e.button !== 0) return;
          setIsDragging(true);
          isPointerInsideRef.current = true;
          const svg = e.currentTarget;
          const xy = toXY(e.clientX, e.clientY, svg);
          setHovered(xy);
          pushPick(xy);
        }}
        onMouseMove={(e) => {
          isPointerInsideRef.current = true;
          const svg = e.currentTarget;
          const xy = toXY(e.clientX, e.clientY, svg);
          if (mode !== "hover") setHovered(xy);
          if (mode === "hover" || (dragToPick && isDragging)) {
            const updateLocal = mode === "hover" ? false : true;
            scheduleHoverPick(xy, updateLocal);
          }
        }}
        onMouseUp={() => {
          setIsDragging(false);
          flushHoverPick();
        }}
        onMouseLeave={() => {
          isPointerInsideRef.current = false;
          setHovered(null);
          setIsDragging(false);
          flushHoverPick();
        }}
      >
        {/* background */}
        <rect x={0} y={0} width={w} height={h} fill="#f8fbff" />

        {/* inner frame */}
        <rect x={pad} y={pad} width={w - 2 * pad} height={h - 2 * pad} fill="#ffffff" stroke="#dbe4ee" />

        {/* grid */}
        {Array.from({ length: gridLines + 1 }).map((_, i) => {
          const t = i / gridLines;
          const x = pad + t * (w - 2 * pad);
          const y = pad + t * (h - 2 * pad);
          const major = i === 0 || i === gridLines || i === gridLines / 2 || i % 2 === 0;
          return (
            <g key={i}>
              <line x1={x} y1={pad} x2={x} y2={h - pad} stroke={major ? "#d8e0ea" : "#edf2f7"} strokeWidth={major ? 1.1 : 1} />
              <line x1={pad} y1={y} x2={w - pad} y2={y} stroke={major ? "#d8e0ea" : "#edf2f7"} strokeWidth={major ? 1.1 : 1} />
            </g>
          );
        })}

        {/* axes */}
        {(() => {
          const o = toPx(0, 0);
          return (
            <g>
              <line x1={pad} y1={o.py} x2={w - pad} y2={o.py} stroke="#94a3b8" strokeWidth={1.3} />
              <line x1={o.px} y1={pad} x2={o.px} y2={h - pad} stroke="#94a3b8" strokeWidth={1.3} />
              <text x={w - pad - 8} y={o.py - 4} fontSize="10" fill="#64748b">x</text>
              <text x={o.px + 4} y={pad + 11} fontSize="10" fill="#64748b">y</text>
            </g>
          );
        })()}

        {/* crosshair (disabled in drag mode to avoid flicker) */}
        {!dragToPick && mode === "click" && (picked || hovered) && (() => {
          const marker = picked ?? hovered!;
          const p = toPx(marker.x, marker.y);
          return (
            <g>
              <line x1={pad} y1={p.py} x2={w - pad} y2={p.py} stroke="#2563eb" strokeWidth={1} strokeDasharray="4 3" opacity={0.55} />
              <line x1={p.px} y1={pad} x2={p.px} y2={h - pad} stroke="#2563eb" strokeWidth={1} strokeDasharray="4 3" opacity={0.55} />
            </g>
          );
        })()}

        {/* picked marker */}
        {picked && (() => {
          const p = toPx(picked.x, picked.y);
          return (
            <g>
              <circle cx={p.px} cy={p.py} r={10} fill="none" stroke="#ef4444" strokeWidth={1.5} opacity={0.45} />
              <circle cx={p.px} cy={p.py} r={6} fill="#ef4444" stroke="#ffffff" strokeWidth={1.5} />
              <circle cx={p.px} cy={p.py} r={2.2} fill="#ffffff" />
            </g>
          );
        })()}
      </svg>

      <div style={{ padding: "8px 10px", fontSize: 11, borderTop: "1px solid #eee", display: "flex", justifyContent: "space-between" }}>
        <span style={{ opacity: 0.75 }}>x in ±{xSpan.toFixed(2)}  y in ±{ySpan.toFixed(2)}  linked to 3D probe</span>
        <span style={{ fontFamily: "monospace", textAlign: "right" }}>
          {picked ? `pick ${fmt(picked.x)}, ${fmt(picked.y)}` : "pick (none)"}
          {mode !== "hover" && hovered ? ` | hover ${fmt(hovered.x)}, ${fmt(hovered.y)}` : ""}
        </span>
      </div>
    </div>
  );
});

type ParamDomainPreviewProps = {
  width: number;
  height: number;
  uMin: number;
  uMax: number;
  vMin: number;
  vMax: number;
  onPick: (uv: { u: number; v: number }) => void;
  picked?: { u: number; v: number } | null;
  mode?: "click" | "hover";
  dragToPick?: boolean;
};

const ParamDomainPreview = React.memo(function ParamDomainPreview({
  width,
  height,
  uMin,
  uMax,
  vMin,
  vMax,
  onPick,
  picked: pickedProp,
  mode = "click",
  dragToPick = false,
}: ParamDomainPreviewProps) {
  const [picked, setPicked] = useState<{ u: number; v: number } | null>(null);
  const [hovered, setHovered] = useState<{ u: number; v: number } | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const isPointerInsideRef = useRef(false);
  const hoverTimerRef = useRef<number | null>(null);
  const pendingHoverRef = useRef<{ u: number; v: number; updateLocal: boolean } | null>(null);
  const lastSentRef = useRef<{ u: number; v: number } | null>(null);
  const HOVER_PICK_INTERVAL_MS = 90;
  const spanU = Math.max(1e-9, Math.abs(uMax - uMin));
  const spanV = Math.max(1e-9, Math.abs(vMax - vMin));

  const pushPick = useCallback(
    (uv: { u: number; v: number }, updateLocal = true) => {
      if (updateLocal) setPicked(uv);
      onPick(uv);
      lastSentRef.current = uv;
    },
    [onPick]
  );

  const flushHoverPick = useCallback(() => {
    if (hoverTimerRef.current != null) {
      window.clearTimeout(hoverTimerRef.current);
      hoverTimerRef.current = null;
    }
    const pending = pendingHoverRef.current;
    pendingHoverRef.current = null;
    if (!pending) return;
    const next = { u: pending.u, v: pending.v };

    const last = lastSentRef.current;
    const epsU = spanU * 0.01;
    const epsV = spanV * 0.01;
    if (last && Math.abs(next.u - last.u) <= epsU && Math.abs(next.v - last.v) <= epsV) {
      return;
    }
    pushPick(next, pending.updateLocal);
  }, [pushPick, spanU, spanV]);

  const scheduleHoverPick = useCallback(
    (uv: { u: number; v: number }, updateLocal: boolean) => {
      pendingHoverRef.current = { ...uv, updateLocal };
      if (hoverTimerRef.current != null) return;
      hoverTimerRef.current = window.setTimeout(() => {
        flushHoverPick();
      }, HOVER_PICK_INTERVAL_MS);
    },
    [flushHoverPick]
  );

  useEffect(() => {
    if (!pickedProp) return;
    if (mode === "hover" && isPointerInsideRef.current) return;
    setPicked(pickedProp);
    lastSentRef.current = pickedProp;
  }, [mode, pickedProp?.u, pickedProp?.v]);

  useEffect(
    () => () => {
      if (hoverTimerRef.current != null) {
        window.clearTimeout(hoverTimerRef.current);
        hoverTimerRef.current = null;
      }
    },
    []
  );

  const pad = 12;
  const w = width;
  const h = height;

  const toUV = (clientX: number, clientY: number, svg: SVGSVGElement) => {
    const r = svg.getBoundingClientRect();
    const px = (clientX - r.left - pad) / (r.width - 2 * pad);
    const py = (clientY - r.top - pad) / (r.height - 2 * pad);
    const u = uMin + px * (uMax - uMin);
    const v = vMax - py * (vMax - vMin);
    return { u, v };
  };

  const toPx = (u: number, v: number) => {
    const px = pad + ((u - uMin) / (uMax - uMin)) * (w - 2 * pad);
    const py = pad + ((vMax - v) / (vMax - vMin)) * (h - 2 * pad);
    return { px, py };
  };

  const gridLines = 8;

  return (
    <div style={{ border: "1px solid #dbe4ee", borderRadius: 12, overflow: "hidden", background: "#ffffff" }}>
      <svg
        width={w}
        height={h}
        style={{ display: "block", cursor: "crosshair" }}
        onMouseDown={(e) => {
          if (e.button !== 0) return;
          setIsDragging(true);
          isPointerInsideRef.current = true;
          const svg = e.currentTarget;
          const uv = toUV(e.clientX, e.clientY, svg);
          setHovered(uv);
          pushPick(uv);
        }}
        onMouseMove={(e) => {
          isPointerInsideRef.current = true;
          const svg = e.currentTarget;
          const uv = toUV(e.clientX, e.clientY, svg);
          if (mode !== "hover") setHovered(uv);
          if (mode === "hover" || (dragToPick && isDragging)) {
            const updateLocal = mode === "hover" ? false : true;
            scheduleHoverPick(uv, updateLocal);
          }
        }}
        onMouseUp={() => {
          setIsDragging(false);
          flushHoverPick();
        }}
        onMouseLeave={() => {
          isPointerInsideRef.current = false;
          setHovered(null);
          setIsDragging(false);
          flushHoverPick();
        }}
      >
        <rect x={0} y={0} width={w} height={h} fill="#f8fbff" />
        <rect x={pad} y={pad} width={w - 2 * pad} height={h - 2 * pad} fill="#ffffff" stroke="#dbe4ee" />

        {Array.from({ length: gridLines + 1 }).map((_, i) => {
          const t = i / gridLines;
          const x = pad + t * (w - 2 * pad);
          const y = pad + t * (h - 2 * pad);
          const major = i === 0 || i === gridLines || i === gridLines / 2 || i % 2 === 0;
          return (
            <g key={i}>
              <line x1={x} y1={pad} x2={x} y2={h - pad} stroke={major ? "#d8e0ea" : "#edf2f7"} strokeWidth={major ? 1.1 : 1} />
              <line x1={pad} y1={y} x2={w - pad} y2={y} stroke={major ? "#d8e0ea" : "#edf2f7"} strokeWidth={major ? 1.1 : 1} />
            </g>
          );
        })}

        <text x={w - pad - 10} y={h - pad + 14} fontSize="10" fill="#64748b">u</text>
        <text x={pad - 8} y={pad - 4} fontSize="10" fill="#64748b">v</text>

        {!dragToPick && mode === "click" && (picked || hovered) && (() => {
          const marker = picked ?? hovered!;
          const p = toPx(marker.u, marker.v);
          return (
            <g>
              <line x1={pad} y1={p.py} x2={w - pad} y2={p.py} stroke="#2563eb" strokeWidth={1} strokeDasharray="4 3" opacity={0.55} />
              <line x1={p.px} y1={pad} x2={p.px} y2={h - pad} stroke="#2563eb" strokeWidth={1} strokeDasharray="4 3" opacity={0.55} />
            </g>
          );
        })()}

        {/* picked marker */}
        {picked && (() => {
          const p = toPx(picked.u, picked.v);
          return (
            <g>
              <circle cx={p.px} cy={p.py} r={10} fill="none" stroke="#ef4444" strokeWidth={1.5} opacity={0.45} />
              <circle cx={p.px} cy={p.py} r={6} fill="#ef4444" stroke="#ffffff" strokeWidth={1.5} />
              <circle cx={p.px} cy={p.py} r={2.2} fill="#ffffff" />
            </g>
          );
        })()}
      </svg>

      <div style={{ padding: "8px 10px", fontSize: 11, borderTop: "1px solid #eee", display: "flex", justifyContent: "space-between" }}>
        <span style={{ opacity: 0.75 }}>u in [{fmt(uMin)},{fmt(uMax)}], v in [{fmt(vMin)},{fmt(vMax)}], linked to 3D probe</span>
        <span style={{ fontFamily: "monospace", textAlign: "right" }}>
          {picked ? `pick ${fmt(picked.u)}, ${fmt(picked.v)}` : "pick (none)"}
          {mode !== "hover" && hovered ? ` | hover ${fmt(hovered.u)}, ${fmt(hovered.v)}` : ""}
        </span>
      </div>
    </div>
  );
});
const cardStyle: React.CSSProperties = {
  marginTop: 8,
  background: "#fff",
  border: "1px solid #e6e6e6",
  borderRadius: 12,
  padding: 10,
};

type C = { re: number; im: number };

const c0: C = { re: 0, im: 0 };
const c1: C = { re: 1, im: 0 };

const cAbs2 = (z: C) => z.re * z.re + z.im * z.im;
const cAdd = (a: C, b: C): C => ({ re: a.re + b.re, im: a.im + b.im });
const cSub = (a: C, b: C): C => ({ re: a.re - b.re, im: a.im - b.im });
const cMul = (a: C, b: C): C => ({ re: a.re * b.re - a.im * b.im, im: a.re * b.im + a.im * b.re });
const cDiv = (a: C, b: C): C => {
  const d = cAbs2(b);
  return { re: (a.re * b.re + a.im * b.im) / d, im: (a.im * b.re - a.re * b.im) / d };
};
const cNeg = (a: C): C => ({ re: -a.re, im: -a.im });
const cSqrt = (z: C): C => {
  const eps = 1e-12;
  if (Math.abs(z.re) < eps && Math.abs(z.im) < eps) return { re: 0, im: 0 };
  const r = Math.hypot(z.re, z.im);
  const re = Math.sqrt((r + z.re) * 0.5);
  const imSign = z.im < 0 ? -1 : 1;
  const im = imSign * Math.sqrt(Math.max(0, (r - z.re) * 0.5));
  return { re, im };
};

const cToStr = (z: C) => `${z.re.toFixed(4)}${z.im < 0 ? " − " : " + "}${Math.abs(z.im).toFixed(4)}i`;
const cFinite = (z: C) => Number.isFinite(z.re) && Number.isFinite(z.im);
const cAbs = (z: C) => Math.hypot(z.re, z.im);
const cDot = (a: C, b: C) => a.re * b.re + a.im * b.im;
const cCross = (a: C, b: C) => a.re * b.im - a.im * b.re;

const mobiusEval = (z: C, p: MobiusParams, eps = 1e-12): C | null => mapMobiusPoint(z, p, eps);

const crossRatio = (z1: C, z2: C, z3: C, z4: C, eps = 1e-12): C | null => {
  const n1 = cSub(z1, z3);
  const n2 = cSub(z2, z4);
  const d1 = cSub(z1, z4);
  const d2 = cSub(z2, z3);
  const den = cMul(d1, d2);
  if (cAbs2(den) < eps) return null;
  return cDiv(cMul(n1, n2), den);
};

const buildCirclePolyline = (center: C, radius: number, samples = 240): C[] => {
  const pts: C[] = [];
  for (let i = 0; i <= samples; i++) {
    const t = (2 * Math.PI * i) / samples;
    pts.push({ re: center.re + radius * Math.cos(t), im: center.im + radius * Math.sin(t) });
  }
  return pts;
};

const buildLinePolyline = (point: C, direction: C, tMin: number, tMax: number, samples = 240): C[] => {
  const pts: C[] = [];
  for (let i = 0; i <= samples; i++) {
    const u = i / samples;
    const t = tMin + (tMax - tMin) * u;
    pts.push({ re: point.re + direction.re * t, im: point.im + direction.im * t });
  }
  return pts;
};

const mapPolylineSegments = (polyline: C[], params: MobiusParams, eps = 1e-12): [number, number][][] => {
  return mapMobiusPolylineSegments(polyline, params, { eps })
    .map((seg) => seg.map((w) => [w.re, w.im] as [number, number]));
};
const mobiusFixedPoints = (p: MobiusParams): { kind: "none" | "single" | "pair" | "all"; values: C[] } => {
  return mobiusFixedPointsCore(p);
};

type M2 = { a: C; b: C; c: C; d: C };

const mId = (): M2 => ({ a: c1, b: c0, c: c0, d: c1 });

const mMul = (X: M2, Y: M2): M2 => ({
  a: cAdd(cMul(X.a, Y.a), cMul(X.b, Y.c)),
  b: cAdd(cMul(X.a, Y.b), cMul(X.b, Y.d)),
  c: cAdd(cMul(X.c, Y.a), cMul(X.d, Y.c)),
  d: cAdd(cMul(X.c, Y.b), cMul(X.d, Y.d)),
});

const mT = (t: C): M2 => ({ a: c1, b: t, c: c0, d: c1 });        // z -> z + t
const mS = (k: C): M2 => ({ a: k, b: c0, c: c0, d: c1 });        // z -> k z
const mJ = (): M2 => ({ a: c0, b: c1, c: c1, d: c0 });           // z -> 1/z

const mToParams = (M: M2): MobiusParams => ({ a: M.a, b: M.b, c: M.c, d: M.d });

function mobiusParamsAtDecomposeStep(p: MobiusParams, step: number, eps = 1e-12): MobiusParams | null {
  const A = p.a, B = p.b, Cc = p.c, D = p.d;
  const det = cSub(cMul(A, D), cMul(B, Cc));

  if (cAbs2(Cc) < eps || cAbs2(det) < eps) {
    // affine or singular case: no stable four-step decomposition
    return null;
  }

  const finalShift = cDiv(A, Cc);
  const delta = cDiv(D, Cc);
  const lambda = cDiv(cMul(Cc, Cc), cSub(cMul(B, Cc), cMul(A, D))); // C^2/(BC-AD)

  // Build step matrix:
  // step0: id
  // step1: Tδ
  // step2: Sλ ∘ Tδ
  // step3: J ∘ Sλ ∘ Tδ
  // step4: Tβ ∘ J ∘ Sλ ∘ Tδ
  let M = mId();

  if (step >= 1) M = mMul(mT(delta), M);
  if (step >= 2) M = mMul(mS(lambda), M);
  if (step >= 3) M = mMul(mJ(), M);
  if (step >= 4) M = mMul(mT(finalShift), M);

  return mToParams(M);
}
const MobiusDecomposeCard: React.FC<{
  params: MobiusParams;
  step: number;
  onStep: (s: number) => void;
}> = ({ params, step, onStep }) => {
  const eps = 1e-12;
  const A = params.a, B = params.b, Cc = params.c, D = params.d;
  const det = cSub(cMul(A, D), cMul(B, Cc));

  const isAffine = cAbs2(Cc) < eps;
  const isSingular = cAbs2(det) < eps;

  let finalShift: C | null = null;
  let lambda: C | null = null;
  let delta: C | null = null;

  if (!isAffine && !isSingular) {
    finalShift = cDiv(A, Cc);
    delta = cDiv(D, Cc);
    lambda = cDiv(cMul(Cc, Cc), cSub(cMul(B, Cc), cMul(A, D)));
  }

  const stepsLabel = [
    "0: z",
    "1: Tδ(z)=z+δ",
    "2: Sλ(z)=λ(z+δ)",
    "3: J(z)=1/(λ(z+δ))",
    "4: Tβ(z)=β+1/(λ(z+δ))",
  ];

  const copyLatex = async () => {
    const latex =
      isAffine
        ? `f(z)=\\frac{Az+B}{D}=\\left(\\frac{A}{D}\\right)z+\\frac{B}{D}`
        : isSingular
          ? `\\det=AD-BC=0\\text{ (singular matrix): no Möbius decomposition}`
          : `\\delta=\\frac{D}{C},\\ \\lambda=\\frac{C^2}{BC-AD},\\ \\beta=\\frac{A}{C},\\quad f(z)=\\beta+\\frac{1}{\\lambda(z+\\delta)}=T_\\beta\\circ J\\circ S_\\lambda\\circ T_\\delta`;
    await navigator.clipboard.writeText(latex);
  };

  return (
    <div style={cardStyle}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
        <div style={{ fontWeight: 800 }}>Decomposition</div>
        <button
          type="button"
          onClick={copyLatex}
          style={{ padding: "4px 8px", borderRadius: 8, border: "1px solid #ddd", background: "#fff", cursor: "pointer" }}
        >
          Copy LaTeX
        </button>
      </div>

      <div style={{ fontSize: 12, marginTop: 6, opacity: 0.8 }}>
        Matrix: <span style={{ fontFamily: "monospace" }}>A,B,C,D</span>
      </div>
      <div style={{ fontFamily: "monospace", fontSize: 12, marginTop: 4 }}>
        A={cToStr(A)}{"  "}B={cToStr(B)}{"  "}C={cToStr(Cc)}{"  "}D={cToStr(D)}
      </div>

      {isAffine ? (
        <div style={{ marginTop: 8, fontSize: 12, opacity: 0.8 }}>
          Affine case (C≈0): f(z) = (A/D)z + (B/D). Stepper disabled.
        </div>
      ) : isSingular ? (
        <div style={{ marginTop: 8, fontSize: 12, opacity: 0.8 }}>
          Singular case (AD-BC≈0): decomposition disabled because this is not an invertible Möbius map.
        </div>
      ) : (
        <>
          <div style={{ marginTop: 8, fontSize: 12 }}>
            <div style={{ fontFamily: "monospace" }}>δ = D/C = {delta ? cToStr(delta) : ""}</div>
            <div style={{ fontFamily: "monospace" }}>λ = C²/(BC-AD) = {lambda ? cToStr(lambda) : ""}</div>
            <div style={{ fontFamily: "monospace" }}>β = A/C = {finalShift ? cToStr(finalShift) : ""}</div>
          </div>

          <div style={{ marginTop: 10, fontSize: 12, lineHeight: 1.5 }}>
            <div style={{ fontWeight: 700, marginBottom: 4 }}>Pipeline</div>
            <div style={{ fontFamily: "monospace" }}>Z-plane</div>
            <div style={{ marginLeft: 10 }}>↓ translation: z → z + δ</div>
            <div style={{ marginLeft: 10 }}>↓ scaling/rotation: z → λz</div>
            <div style={{ marginLeft: 10 }}>↓ inversion: z → 1/z</div>
            <div style={{ marginLeft: 10 }}>↓ final translation: z → z + β</div>
            <div style={{ fontFamily: "monospace", marginTop: 2 }}>W-plane</div>
          </div>

          <div style={{ marginTop: 10 }}>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12 }}>
              <span style={{ fontWeight: 700 }}>Step</span>
              <span style={{ fontFamily: "monospace" }}>{stepsLabel[step]}</span>
            </div>
            <input
              type="range"
              min={0}
              max={4}
              step={1}
              value={step}
              onChange={(e) => onStep(parseInt(e.target.value, 10))}
              style={{ width: "100%" }}
            />
          </div>

          <div style={{ marginTop: 6, fontSize: 12, opacity: 0.75 }}>
            Rendering uses the chosen intermediate map in the W-plane.
          </div>
        </>
      )}
    </div>
  );
};
const MobiusInvariantsCard: React.FC<{ params: MobiusParams }> = ({ params }) => {
  const eps = 1e-12;
  const A = params.a, B = params.b, Cc = params.c, D = params.d;

  const det = cSub(cMul(A, D), cMul(B, Cc)); // AD-BC
  const isAffine = cAbs2(Cc) < eps;
  const isSingular = cAbs2(det) < eps;
  const fixed = mobiusFixedPoints(params);
  const zRef = useRef<PlanePlotHandle | null>(null);
  const wRef = useRef<PlanePlotHandle | null>(null);
  const [replaceIndex, setReplaceIndex] = useState(0);
  const [crossPoints, setCrossPoints] = useState<C[]>([
    { re: -1.2, im: -0.9 },
    { re: 1.1, im: -0.8 },
    { re: 0.9, im: 1.0 },
    { re: -0.8, im: 0.9 },
  ]);

  const pole = isAffine ? null : cNeg(cDiv(D, Cc));  // -D/C
  const fInf = isAffine ? null : cDiv(A, Cc);        // A/C
  const fixedLabel =
    fixed.kind === "all"
      ? "all points"
      : fixed.kind === "none"
        ? "none"
        : fixed.values.map(cToStr).join(" ; ");
  const crossZ = useMemo(() => crossRatio(crossPoints[0], crossPoints[1], crossPoints[2], crossPoints[3]), [crossPoints]);
  const crossWPoints = useMemo(() => crossPoints.map((z) => mobiusEval(z, params)), [crossPoints, params]);
  const crossWValid = crossWPoints.every((w) => !!w && cFinite(w));
  const crossW = useMemo(() => {
    if (!crossWValid) return null;
    const p0 = crossWPoints[0] as C;
    const p1 = crossWPoints[1] as C;
    const p2 = crossWPoints[2] as C;
    const p3 = crossWPoints[3] as C;
    return crossRatio(p0, p1, p2, p3);
  }, [crossWPoints, crossWValid]);
  const crossDiff = useMemo(() => {
    if (!crossZ || !crossW) return null;
    return cAbs(cSub(crossZ, crossW));
  }, [crossZ, crossW]);

  const setPointFromClick = useCallback((pt: { re: number; im: number }) => {
    setCrossPoints((prev) => prev.map((z, i) => (i === replaceIndex ? { re: pt.re, im: pt.im } : z)));
    setReplaceIndex((i) => (i + 1) % 4);
  }, [replaceIndex]);

  useEffect(() => {
    if (!zRef.current || !wRef.current) return;
    zRef.current.clear();
    wRef.current.clear();
    zRef.current.drawGrid(0.5);
    wRef.current.drawGrid(0.5);

    const colors = ["#d32f2f", "#1976d2", "#2e7d32", "#7b1fa2"];
    const zPairs = crossPoints.map((p) => [p.re, p.im] as [number, number]);
    zRef.current.drawCurve([...zPairs, zPairs[0]], "#444", { layer: "cr-z-poly", width: 1.1, dash: "4 3", opacity: 0.72 });
    for (let i = 0; i < crossPoints.length; i++) {
      zRef.current.drawPoints([[crossPoints[i].re, crossPoints[i].im]], {
        color: colors[i],
        size: 4.8,
        shape: "circle",
        layer: `cr-z-${i}`,
      });
    }

    const validW = crossWPoints
      .map((p) => (p && cFinite(p) ? [p.re, p.im] as [number, number] : null))
      .filter((p): p is [number, number] => !!p);
    if (validW.length >= 2) {
      wRef.current.drawCurve([...validW, validW[0]], "#0b66c3", { layer: "cr-w-poly", width: 1.1, dash: "4 3", opacity: 0.72 });
    }
    for (let i = 0; i < crossWPoints.length; i++) {
      const w = crossWPoints[i];
      if (!w || !cFinite(w)) continue;
      wRef.current.drawPoints([[w.re, w.im]], {
        color: colors[i],
        size: 4.8,
        shape: "circle",
        layer: `cr-w-${i}`,
      });
    }
  }, [crossPoints, crossWPoints]);

  return (
    <div style={{ display: "grid", gap: 10 }}>
      <div style={cardStyle}>
        <div style={{ fontWeight: 800, marginBottom: 6 }}>Invariants</div>
        <div style={{ fontSize: 12, display: "grid", gap: 4 }}>
          <div><b>determinant:</b> ad - bc = <span style={{ fontFamily: "monospace" }}>{cToStr(det)}</span></div>
          <div>
            <b>pole:</b>{" "}
            {pole ? <span style={{ fontFamily: "monospace" }}>z = {cToStr(pole)}</span> : "none (affine c = 0)"}
          </div>
          <div>
            <b>image of infinity:</b>{" "}
            {fInf ? <span style={{ fontFamily: "monospace" }}>a/c = {cToStr(fInf)}</span> : "∞ (affine c = 0)"}
          </div>
          <div>
            <b>preimage of infinity:</b>{" "}
            {pole ? <span style={{ fontFamily: "monospace" }}>-d/c = {cToStr(pole)}</span> : "no finite preimage (affine c = 0)"}
          </div>
          <div><b>fixed points:</b> {fixedLabel}</div>
          <div><b>derivative:</b> <span style={{ fontFamily: "monospace" }}>f'(z) = (ad - bc) / (cz + d)^2</span></div>
          <div><b>local scale:</b> <span style={{ fontFamily: "monospace" }}>|f'(z)| = |ad - bc| / |cz + d|^2</span></div>
          <div><b>angle preservation:</b> {isSingular ? "no (degenerate: ad - bc = 0)" : "yes, where defined (cz + d ≠ 0)"}</div>
        </div>
        <div style={{ marginTop: 8, fontSize: 12 }}>
          <div style={{ fontWeight: 700, marginBottom: 2 }}>Preserved</div>
          <div>• generalized circles</div>
          <div>• angles</div>
          <div>• cross-ratios</div>
          <div>• orientation locally (where defined)</div>
        </div>
      </div>

      <div style={cardStyle}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
          <div style={{ fontWeight: 800 }}>Cross-ratio experiment</div>
          <div style={{ display: "flex", gap: 6 }}>
            <button
              type="button"
              onClick={() => {
                setCrossPoints([
                  { re: -1.2, im: -0.9 },
                  { re: 1.1, im: -0.8 },
                  { re: 0.9, im: 1.0 },
                  { re: -0.8, im: 0.9 },
                ]);
                setReplaceIndex(0);
              }}
            >
              Reset points
            </button>
          </div>
        </div>
        <div style={{ fontSize: 12, opacity: 0.8, marginTop: 4 }}>
          Click the Z-plane to place z1..z4 (current target: z{replaceIndex + 1}).
        </div>
        <div style={{ marginTop: 8, display: "grid", gap: 4, fontSize: 12 }}>
          <div>
            <b>CR(z1,z2,z3,z4):</b>{" "}
            <span style={{ fontFamily: "monospace" }}>{crossZ ? cToStr(crossZ) : "undefined"}</span>
          </div>
          <div>
            <b>CR(w1,w2,w3,w4):</b>{" "}
            <span style={{ fontFamily: "monospace" }}>{crossW ? cToStr(crossW) : "undefined (point at pole / infinity)"}</span>
          </div>
          <div>
            <b>Difference:</b>{" "}
            <span style={{ fontFamily: "monospace" }}>{crossDiff == null ? "undefined" : crossDiff.toExponential(3)}</span>
            {crossDiff != null && crossDiff < 1e-7 ? "  ~0" : ""}
          </div>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(340px, 1fr))", gap: 12, marginTop: 10 }}>
          <div style={{ display: "grid", gap: 6 }}>
            <div style={{ fontWeight: 700, fontSize: 12 }}>Z-plane</div>
            <div style={{ minHeight: 270 }}>
              <PlanePlot id="svgZMobiusInv" extent={3} step={1} ref={zRef} style={{ height: "100%" }} onClickPoint={setPointFromClick} />
            </div>
          </div>
          <div style={{ display: "grid", gap: 6 }}>
            <div style={{ fontWeight: 700, fontSize: 12 }}>W-plane</div>
            <div style={{ minHeight: 270 }}>
              <PlanePlot id="svgWMobiusInv" extent={3} step={1} ref={wRef} style={{ height: "100%" }} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

type MobiusShapeEntry =
  | { id: string; kind: "circle"; center: C; radius: number }
  | { id: string; kind: "line"; point: C; direction: C }
  | { id: string; kind: "ray"; origin: C; direction: C }
  | { id: string; kind: "grid"; spacing: number; range: number }
  | { id: string; kind: "samples"; points: C[] };

const MobiusCirclesCard: React.FC<{ params: MobiusParams }> = ({ params }) => {
  const zRef = useRef<PlanePlotHandle | null>(null);
  const wRef = useRef<PlanePlotHandle | null>(null);
  const nextIdRef = useRef(1);
  const [entries, setEntries] = useState<MobiusShapeEntry[]>([]);

  const pole = useMemo(() => (cAbs2(params.c) < 1e-12 ? null : cNeg(cDiv(params.d, params.c))), [params]);
  const isAffine = pole === null;
  const colors = ["#c62828", "#1565c0", "#2e7d32", "#6a1b9a", "#ef6c00", "#00897b", "#ad1457"];

  const getNextId = useCallback((prefix: string) => `${prefix}-${nextIdRef.current++}`, []);

  const addCircle = useCallback(() => {
    const offset = entries.length * 0.2;
    setEntries((prev) => [
      ...prev,
      { id: getNextId("circle"), kind: "circle", center: { re: -0.4 + offset, im: 0.3 - offset }, radius: 0.9 },
    ]);
  }, [entries.length, getNextId]);

  const addLine = useCallback(() => {
    const offset = entries.length * 0.18;
    setEntries((prev) => [
      ...prev,
      { id: getNextId("line"), kind: "line", point: { re: -0.8 + offset, im: -0.4 + offset }, direction: { re: 1, im: 0.5 } },
    ]);
  }, [entries.length, getNextId]);

  const addRay = useCallback(() => {
    const offset = entries.length * 0.14;
    setEntries((prev) => [
      ...prev,
      { id: getNextId("ray"), kind: "ray", origin: { re: -1.2 + offset, im: -0.9 + 0.08 * entries.length }, direction: { re: 1, im: 0.25 } },
    ]);
  }, [entries.length, getNextId]);

  const addGrid = useCallback(() => {
    setEntries((prev) => [
      ...prev,
      { id: getNextId("grid"), kind: "grid", spacing: 0.8, range: 2.4 },
    ]);
  }, [getNextId]);

  const addSamples = useCallback(() => {
    const pts: C[] = [];
    for (let i = 0; i < 9; i++) {
      const t = (2 * Math.PI * i) / 9;
      pts.push({ re: 1.3 * Math.cos(t), im: 1.3 * Math.sin(t) });
    }
    setEntries((prev) => [...prev, { id: getNextId("samples"), kind: "samples", points: pts }]);
  }, [getNextId]);

  const analyses = useMemo(() => {
    const tol = 0.045;
    return entries.map((entry) => {
      if (entry.kind === "samples") {
        return { id: entry.id, input: "sample points", output: "sample points", note: "pointwise image under f" };
      }
      if (entry.kind === "grid") {
        if (isAffine) return { id: entry.id, input: "grid (lines)", output: "grid (lines)", note: "affine map preserves lines" };
        const kMax = Math.floor(entry.range / entry.spacing);
        let throughPoleCount = 0;
        if (pole) {
          for (let k = -kMax; k <= kMax; k++) {
            const x0 = k * entry.spacing;
            if (Math.abs(pole.re - x0) < tol) throughPoleCount++;
            if (Math.abs(pole.im - x0) < tol) throughPoleCount++;
          }
        }
        return {
          id: entry.id,
          input: "grid (lines)",
          output: throughPoleCount > 0 ? "mixed (line/circle)" : "circles",
          note: throughPoleCount > 0 ? `${throughPoleCount} grid line(s) pass through pole` : "no grid line passes through pole",
        };
      }
      if (entry.kind === "circle") {
        const throughPole = pole ? Math.abs(cAbs(cSub(pole, entry.center)) - entry.radius) < tol : false;
        return {
          id: entry.id,
          input: "circle",
          output: throughPole ? "line" : "circle",
          note: throughPole ? "circle through pole" : "circle not through pole",
        };
      }
      if (entry.kind === "line") {
        if (isAffine || !pole) return { id: entry.id, input: "line", output: "line", note: "affine case" };
        const dirNorm = cAbs(entry.direction);
        const d = dirNorm < 1e-9 ? 1e9 : Math.abs(cCross(cSub(pole, entry.point), entry.direction)) / dirNorm;
        const throughPole = d < tol;
        return { id: entry.id, input: "line", output: throughPole ? "line" : "circle", note: throughPole ? "line through pole" : "line misses pole" };
      }
      if (isAffine || !pole) return { id: entry.id, input: "ray", output: "ray on line", note: "affine case" };
      const dirNorm = cAbs(entry.direction);
      const d = dirNorm < 1e-9 ? 1e9 : Math.abs(cCross(cSub(pole, entry.origin), entry.direction)) / dirNorm;
      const along = cDot(cSub(pole, entry.origin), entry.direction);
      const throughPole = d < tol && along >= -tol;
      return { id: entry.id, input: "ray", output: throughPole ? "ray on line" : "arc on circle", note: throughPole ? "ray reaches pole" : "ray misses pole" };
    });
  }, [entries, isAffine, pole]);

  useEffect(() => {
    if (!zRef.current || !wRef.current) return;
    zRef.current.clear();
    wRef.current.clear();
    zRef.current.drawGrid(0.5);
    wRef.current.drawGrid(0.5);

    entries.forEach((entry, idx) => {
      const color = colors[idx % colors.length];
      if (entry.kind === "samples") {
        const zPts = entry.points.map((p) => [p.re, p.im] as [number, number]);
        zRef.current?.drawPoints(zPts, { color, shape: "diamond", size: 4, layer: `${entry.id}-z` });
        const wPts = entry.points
          .map((p) => mobiusEval(p, params))
          .filter((p): p is C => !!p && cFinite(p))
          .map((p) => [p.re, p.im] as [number, number]);
        wRef.current?.drawPoints(wPts, { color, shape: "diamond", size: 4, layer: `${entry.id}-w` });
        return;
      }

      const drawSourceAndImage = (poly: C[]) => {
        const zPts = poly.map((p) => [p.re, p.im] as [number, number]);
        zRef.current?.drawCurve(zPts, color, { width: 1.5, layer: `${entry.id}-z` });
        const mappedSegments = mapPolylineSegments(poly, params);
        mappedSegments.forEach((seg, segIndex) => {
          wRef.current?.drawCurve(seg, color, { width: 1.5, layer: `${entry.id}-w-${segIndex}` });
        });
      };

      if (entry.kind === "circle") {
        drawSourceAndImage(buildCirclePolyline(entry.center, entry.radius, 240));
      } else if (entry.kind === "line") {
        drawSourceAndImage(buildLinePolyline(entry.point, entry.direction, -4.5, 4.5, 260));
      } else if (entry.kind === "ray") {
        drawSourceAndImage(buildLinePolyline(entry.origin, entry.direction, 0, 5.5, 220));
      } else if (entry.kind === "grid") {
        const kMax = Math.max(1, Math.floor(entry.range / entry.spacing));
        for (let k = -kMax; k <= kMax; k++) {
          const x0 = k * entry.spacing;
          drawSourceAndImage(buildLinePolyline({ re: x0, im: 0 }, { re: 0, im: 1 }, -entry.range, entry.range, 180));
          drawSourceAndImage(buildLinePolyline({ re: 0, im: x0 }, { re: 1, im: 0 }, -entry.range, entry.range, 180));
        }
      }
    });

    if (pole) {
      zRef.current.drawPoints([[pole.re, pole.im]], {
        color: "#f57c00",
        shape: "triangle",
        size: 4.8,
        layer: "mobius-pole-z",
      });
    }
  }, [colors, entries, params, pole]);

  return (
    <div style={{ display: "grid", gap: 10 }}>
      <div style={cardStyle}>
        <div style={{ fontWeight: 800, marginBottom: 6 }}>Circles / Lines</div>
        <div style={{ fontSize: 12, opacity: 0.85, marginBottom: 6 }}>
          Möbius maps send generalized circles to generalized circles. A circle through the pole maps to a line.
        </div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
          <button type="button" onClick={addCircle}>Add circle</button>
          <button type="button" onClick={addLine}>Add line</button>
          <button type="button" onClick={addRay}>Add ray</button>
          <button type="button" onClick={addGrid}>Add grid</button>
          <button type="button" onClick={addSamples}>Add sample points</button>
          <button type="button" onClick={() => setEntries([])}>Clear</button>
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(340px, 1fr))", gap: 12 }}>
        <div style={{ display: "grid", gap: 6 }}>
          <div style={{ fontWeight: 700, fontSize: 12 }}>Z-plane (input objects)</div>
          <div style={{ minHeight: 280 }}>
            <PlanePlot id="svgZMobiusCircles" extent={3} step={1} ref={zRef} style={{ height: "100%" }} />
          </div>
        </div>
        <div style={{ display: "grid", gap: 6 }}>
          <div style={{ fontWeight: 700, fontSize: 12 }}>W-plane (transformed objects)</div>
          <div style={{ minHeight: 280 }}>
            <PlanePlot id="svgWMobiusCircles" extent={3} step={1} ref={wRef} style={{ height: "100%" }} />
          </div>
        </div>
      </div>

      <div style={cardStyle}>
        <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>Rule examples</div>
        <div style={{ display: "grid", gap: 4, fontSize: 12, marginBottom: 8 }}>
          <div style={{ display: "grid", gridTemplateColumns: "120px 140px", gap: 8 }}>
            <span>line</span>
            <span style={{ fontWeight: 700 }}>circle (or line through pole)</span>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "120px 140px", gap: 8 }}>
            <span>circle</span>
            <span style={{ fontWeight: 700 }}>circle</span>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "120px 140px", gap: 8 }}>
            <span>circle through pole</span>
            <span style={{ fontWeight: 700 }}>line</span>
          </div>
        </div>
        <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>Input object / Output object</div>
        {entries.length === 0 ? (
          <div style={{ fontSize: 12, opacity: 0.75 }}>Add objects to see mapped classifications.</div>
        ) : (
          <div style={{ display: "grid", gap: 4, fontSize: 12 }}>
            {analyses.map((row, i) => (
              <div key={row.id} style={{ display: "grid", gridTemplateColumns: "120px 140px 1fr", gap: 8 }}>
                <span>{i + 1}. {row.input}</span>
                <span style={{ fontWeight: 700 }}>{row.output}</span>
                <span style={{ opacity: 0.8 }}>{row.note}</span>
              </div>
            ))}
          </div>
        )}
        <div style={{ marginTop: 8, fontSize: 12, opacity: 0.84 }}>
          Rule summary: line → {isAffine ? "line" : "line or circle"}, circle → {isAffine ? "circle" : "circle (or line if through pole)"}.
        </div>
      </div>
    </div>
  );
};

const MobiusRiemannCard: React.FC<{ params: MobiusParams }> = ({ params }) => {
  const zRef = useRef<PlanePlotHandle | null>(null);
  const wRef = useRef<PlanePlotHandle | null>(null);
  const [layoutMode, setLayoutMode] = useState<"split" | "overlay" | "sphere" | "beforeAfter">("split");
  const [sampleMode, setSampleMode] = useState<"orbit" | "manual">("orbit");
  const [animating, setAnimating] = useState(true);
  const [phase, setPhase] = useState(0);
  const [animSpeed, setAnimSpeed] = useState(0.8);
  const [sampleRadius, setSampleRadius] = useState(1.25);
  const [manualZ, setManualZ] = useState<C>({ re: 1, im: 0 });
  const [showProjectionRays, setShowProjectionRays] = useState(true);
  const [showPlaneGrid, setShowPlaneGrid] = useState(true);
  const [showAxes, setShowAxes] = useState(true);
  const [showUnitCircle, setShowUnitCircle] = useState(true);
  const [showEquator, setShowEquator] = useState(true);
  const [showPoles, setShowPoles] = useState(true);
  const [showSphereGuide, setShowSphereGuide] = useState(true);
  const [showSphereGrid, setShowSphereGrid] = useState(true);
  const [showFixedPoints, setShowFixedPoints] = useState(true);
  const [showPresetCurve, setShowPresetCurve] = useState(true);
  const [showMappedCurve, setShowMappedCurve] = useState(true);
  const [geometryPreset, setGeometryPreset] = useState<
    "unit_circle" | "circle_center0" | "circle_offset" | "real_axis" | "imag_axis" | "line_x" | "line_y"
  >("unit_circle");
  const [presetRadius, setPresetRadius] = useState(1);
  const [presetOffsetX, setPresetOffsetX] = useState(0.7);
  const [presetOffsetY, setPresetOffsetY] = useState(0.25);
  const [presetLineConst, setPresetLineConst] = useState(0.5);

  const eps = 1e-9;
  const sampleOrbitZ = useMemo<C>(
    () => ({ re: sampleRadius * Math.cos(phase), im: sampleRadius * Math.sin(phase) }),
    [phase, sampleRadius]
  );
  const sampleZ = sampleMode === "orbit" ? sampleOrbitZ : manualZ;
  const sampleW = useMemo(() => mobiusEval(sampleZ, params), [params, sampleZ]);
  const zSphere = useMemo(() => stereographicToSphere(sampleZ.re, sampleZ.im), [sampleZ]);
  const wSphere = useMemo(
    () => (sampleW && cFinite(sampleW) ? stereographicToSphere(sampleW.re, sampleW.im) : { x: 0, y: 0, z: 1 }),
    [sampleW]
  );
  const zBackProjected = useMemo(() => sphereToStereographic(zSphere), [zSphere]);
  const wBackProjected = useMemo(() => sphereToStereographic(wSphere), [wSphere]);

  const poleZ = useMemo(() => (cAbs2(params.c) > eps ? cNeg(cDiv(params.d, params.c)) : null), [params]);
  const imageInfinity = useMemo(() => (cAbs2(params.c) > eps ? cDiv(params.a, params.c) : null), [params]);
  const fixed = useMemo(() => mobiusFixedPoints(params), [params]);
  const fixedPointsSphere = useMemo(
    () =>
      fixed.values
        .filter((z) => cFinite(z))
        .map((z) => ({ ...stereographicToSphere(z.re, z.im), zComplex: z })),
    [fixed.values]
  );

  const modeLabel = useMemo(() => {
    if (fixed.kind === "single") return "parabolic-like";
    if (fixed.kind === "all") return "identity-like";
    if (cAbs2(params.b) < eps && cAbs2(params.c) < eps && cAbs2(params.d) > eps) {
      const ratio = cDiv(params.a, params.d);
      const mag = cAbs(ratio);
      if (Math.abs(mag - 1) < 0.06) return "elliptic-like (rotation)";
      return mag > 1 ? "loxodromic-like (expanding)" : "loxodromic-like (contracting)";
    }
    if (fixed.kind === "pair") return "general two-fixed-point map";
    return "general Möbius";
  }, [fixed.kind, params]);

  useEffect(() => {
    if (!animating || sampleMode !== "orbit") return;
    const id = window.setInterval(() => {
      setPhase((p) => p + 0.04 * Math.max(0.2, animSpeed));
    }, 30);
    return () => window.clearInterval(id);
  }, [animating, animSpeed, sampleMode]);

  const objectCurveZ = useMemo<C[]>(() => {
    if (geometryPreset === "unit_circle") return buildCirclePolyline({ re: 0, im: 0 }, 1, 260);
    if (geometryPreset === "circle_center0") return buildCirclePolyline({ re: 0, im: 0 }, Math.max(0.1, presetRadius), 260);
    if (geometryPreset === "circle_offset") {
      return buildCirclePolyline({ re: presetOffsetX, im: presetOffsetY }, Math.max(0.1, presetRadius), 260);
    }
    if (geometryPreset === "real_axis") return buildLinePolyline({ re: 0, im: 0 }, { re: 1, im: 0 }, -3.2, 3.2, 260);
    if (geometryPreset === "imag_axis") return buildLinePolyline({ re: 0, im: 0 }, { re: 0, im: 1 }, -3.2, 3.2, 260);
    if (geometryPreset === "line_x") {
      return buildLinePolyline({ re: presetLineConst, im: 0 }, { re: 0, im: 1 }, -3.2, 3.2, 260);
    }
    return buildLinePolyline({ re: 0, im: presetLineConst }, { re: 1, im: 0 }, -3.2, 3.2, 260);
  }, [geometryPreset, presetLineConst, presetOffsetX, presetOffsetY, presetRadius]);

  const objectLabel = useMemo(() => {
    if (geometryPreset === "unit_circle") return "|z| = 1 (equator)";
    if (geometryPreset === "circle_center0") return `|z| = ${Math.max(0.1, presetRadius).toFixed(2)}`;
    if (geometryPreset === "circle_offset") {
      return `|z - (${presetOffsetX.toFixed(2)} + ${presetOffsetY.toFixed(2)}i)| = ${Math.max(0.1, presetRadius).toFixed(2)}`;
    }
    if (geometryPreset === "real_axis") return "Im(z) = 0 (real axis)";
    if (geometryPreset === "imag_axis") return "Re(z) = 0 (imaginary axis)";
    if (geometryPreset === "line_x") return `Re(z) = ${presetLineConst.toFixed(2)}`;
    return `Im(z) = ${presetLineConst.toFixed(2)}`;
  }, [geometryPreset, presetLineConst, presetOffsetX, presetOffsetY, presetRadius]);

  const objectCurveWSegments = useMemo(() => mapPolylineSegments(objectCurveZ, params), [objectCurveZ, params]);

  const liftToSphereSegments = useCallback((curve: C[], mapper: (z: C) => C | null): { x: number; y: number; z: number }[][] => {
    const out: { x: number; y: number; z: number }[][] = [];
    let current: { x: number; y: number; z: number }[] = [];
    for (const z of curve) {
      const mapped = mapper(z);
      if (!mapped || !cFinite(mapped)) {
        if (current.length >= 2) out.push(current);
        current = [];
        continue;
      }
      const p = stereographicToSphere(mapped.re, mapped.im);
      if (!Number.isFinite(p.x) || !Number.isFinite(p.y) || !Number.isFinite(p.z)) {
        if (current.length >= 2) out.push(current);
        current = [];
        continue;
      }
      current.push({ x: p.x, y: p.y, z: p.z });
    }
    if (current.length >= 2) out.push(current);
    return out;
  }, []);

  const objectCurveSphereBefore = useMemo(() => liftToSphereSegments(objectCurveZ, (z) => z), [liftToSphereSegments, objectCurveZ]);
  const objectCurveSphereAfter = useMemo(
    () => liftToSphereSegments(objectCurveZ, (z) => mobiusEval(z, params)),
    [liftToSphereSegments, objectCurveZ, params]
  );

  const orbitSphereTraceBefore = useMemo(() => {
    if (sampleMode !== "orbit") return [] as { x: number; y: number; z: number }[];
    const trace: { x: number; y: number; z: number }[] = [];
    const n = 220;
    for (let i = 0; i <= n; i++) {
      const t = phase - Math.PI + (2 * Math.PI * i) / n;
      const z = { re: sampleRadius * Math.cos(t), im: sampleRadius * Math.sin(t) };
      const p = stereographicToSphere(z.re, z.im);
      trace.push({ x: p.x, y: p.y, z: p.z });
    }
    return trace;
  }, [phase, sampleMode, sampleRadius]);

  const orbitSphereTraceAfter = useMemo(() => {
    if (sampleMode !== "orbit") return [] as { x: number; y: number; z: number }[];
    const trace: { x: number; y: number; z: number }[] = [];
    const n = 220;
    for (let i = 0; i <= n; i++) {
      const t = phase - Math.PI + (2 * Math.PI * i) / n;
      const z = { re: sampleRadius * Math.cos(t), im: sampleRadius * Math.sin(t) };
      const w = mobiusEval(z, params);
      if (w && cFinite(w)) {
        const p = stereographicToSphere(w.re, w.im);
        trace.push({ x: p.x, y: p.y, z: p.z });
      }
    }
    return trace;
  }, [phase, sampleMode, sampleRadius, params]);

  useEffect(() => {
    if (!zRef.current || !wRef.current) return;
    if (layoutMode === "sphere" || layoutMode === "beforeAfter") return;

    renderMobius(zRef.current, wRef.current, params, 220, { drawGrid: showPlaneGrid });
    if (showAxes) {
      zRef.current.drawCurve([[-3.2, 0], [3.2, 0]], "#94a3b8", { width: 1.05, layer: "riemann-z-axis-real" });
      zRef.current.drawCurve([[0, -3.2], [0, 3.2]], "#94a3b8", { width: 1.05, layer: "riemann-z-axis-imag" });
      wRef.current.drawCurve([[-3.2, 0], [3.2, 0]], "#94a3b8", { width: 1.05, layer: "riemann-w-axis-real" });
      wRef.current.drawCurve([[0, -3.2], [0, 3.2]], "#94a3b8", { width: 1.05, layer: "riemann-w-axis-imag" });
    }
    if (showUnitCircle) {
      const uc = buildCirclePolyline({ re: 0, im: 0 }, 1, 220).map((p) => [p.re, p.im] as [number, number]);
      zRef.current.drawCurve(uc, "#7c879f", { width: 1.2, dash: "4 3", layer: "riemann-z-unit-circle" });
    }
    if (showPresetCurve) {
      zRef.current.drawCurve(
        objectCurveZ.map((p) => [p.re, p.im] as [number, number]),
        "#111827",
        { width: 1.8, layer: "riemann-z-preset-curve" }
      );
    }
    if (showMappedCurve) {
      objectCurveWSegments.forEach((seg, index) => {
        wRef.current?.drawCurve(seg, "#0a66c2", { width: 1.7, layer: `riemann-w-mapped-curve-${index}` });
      });
    }

    zRef.current.drawPoints([[sampleZ.re, sampleZ.im]], {
      color: "#111",
      shape: "cross",
      size: 5,
      layer: "riemann-z-point",
    });
    if (sampleW && cFinite(sampleW)) {
      wRef.current.drawPoints([[sampleW.re, sampleW.im]], {
        color: "#0a66c2",
        shape: "cross",
        size: 5,
        layer: "riemann-w-point",
      });
    } else {
      wRef.current.drawPoints([], { layer: "riemann-w-point" });
      wRef.current.drawPoints([[0, 0]], {
        color: "#f57c00",
        shape: "triangle",
        size: 5,
        layer: "riemann-w-infinity-indicator",
      });
    }
  }, [
    layoutMode,
    objectCurveWSegments,
    objectCurveZ,
    params,
    sampleW,
    sampleZ,
    showAxes,
    showMappedCurve,
    showPlaneGrid,
    showPresetCurve,
    showUnitCircle,
  ]);

  const onPickZPoint = useCallback((pt: { re: number; im: number }) => {
    setManualZ({ re: pt.re, im: pt.im });
    setSampleMode("manual");
  }, []);

  const projectionStatus = useMemo(() => {
    const tags: string[] = [];
    const magZ = cAbs(sampleZ);
    if (magZ <= 1e-3) tags.push("zero");
    if (Math.abs(magZ - 1) <= 0.04) tags.push("unit circle");
    if (poleZ && cAbs(cSub(sampleZ, poleZ)) <= 0.05) tags.push("pole");
    if (fixed.values.some((p) => cAbs(cSub(sampleZ, p)) <= 0.05)) tags.push("fixed point");
    if (!tags.length) tags.push("regular");

    const imageTags: string[] = [];
    if (!sampleW || !cFinite(sampleW)) imageTags.push("infinity");
    if (sampleW && cFinite(sampleW)) {
      const magW = cAbs(sampleW);
      if (magW <= 1e-3) imageTags.push("zero");
      if (Math.abs(magW - 1) <= 0.04) imageTags.push("unit circle");
      if (fixed.values.some((p) => cAbs(cSub(sampleW, p)) <= 0.05)) imageTags.push("fixed point");
      if (magW > 8) imageTags.push("near infinity");
    }
    if (!imageTags.length) imageTags.push("regular");
    return { z: tags.join(", "), w: imageTags.join(", ") };
  }, [fixed.values, poleZ, sampleW, sampleZ]);

  const sphereLines = useMemo(() => {
    const lines: RiemannSphereLine[] = [];
    const north = { x: 0, y: 0, z: 1 };

    if (showEquator || showSphereGrid) {
      const n = 220;
      const equator: { x: number; y: number; z: number }[] = [];
      for (let i = 0; i <= n; i++) {
        const t = (2 * Math.PI * i) / n;
        equator.push({ x: Math.cos(t), y: Math.sin(t), z: 0 });
      }
      if (showEquator) lines.push({ points: equator, color: 0x8a8fa3, opacity: 0.7 });
      if (showSphereGrid) {
        const meridianA: { x: number; y: number; z: number }[] = [];
        const meridianB: { x: number; y: number; z: number }[] = [];
        for (let i = 0; i <= n; i++) {
          const t = (2 * Math.PI * i) / n;
          meridianA.push({ x: Math.cos(t), y: 0, z: Math.sin(t) });
          meridianB.push({ x: 0, y: Math.cos(t), z: Math.sin(t) });
        }
        lines.push({ points: meridianA, color: 0xb2b7c8, opacity: 0.38 });
        lines.push({ points: meridianB, color: 0xb2b7c8, opacity: 0.38 });
      }
    }

    if (showPlaneGrid) {
      const half = 1.35;
      lines.push({
        points: [
          { x: -half, y: -half, z: -1 },
          { x: half, y: -half, z: -1 },
          { x: half, y: half, z: -1 },
          { x: -half, y: half, z: -1 },
          { x: -half, y: -half, z: -1 },
        ],
        color: 0x94a3b8,
        opacity: 0.45,
      });
      for (const v of [-0.9, -0.45, 0, 0.45, 0.9]) {
        lines.push({ points: [{ x: -half, y: v, z: -1 }, { x: half, y: v, z: -1 }], color: 0xb9c0ce, opacity: 0.3 });
        lines.push({ points: [{ x: v, y: -half, z: -1 }, { x: v, y: half, z: -1 }], color: 0xb9c0ce, opacity: 0.3 });
      }
      if (showUnitCircle) {
        const ring: { x: number; y: number; z: number }[] = [];
        const samples = 180;
        for (let i = 0; i <= samples; i++) {
          const t = (2 * Math.PI * i) / samples;
          ring.push({ x: Math.cos(t), y: Math.sin(t), z: -1 });
        }
        lines.push({ points: ring, color: 0x6b7280, opacity: 0.62 });
      }
    }

    if (sampleMode === "orbit" && orbitSphereTraceBefore.length >= 2) {
      lines.push({ points: orbitSphereTraceBefore, color: 0x232323, opacity: 0.88 });
    }
    if (sampleMode === "orbit" && orbitSphereTraceAfter.length >= 2) {
      lines.push({ points: orbitSphereTraceAfter, color: 0x0a66c2, opacity: 0.9 });
    }

    if (showPresetCurve) {
      objectCurveSphereBefore.forEach((seg) => lines.push({ points: seg, color: 0x1f2937, opacity: 0.8 }));
    }
    if (showMappedCurve) {
      objectCurveSphereAfter.forEach((seg) => lines.push({ points: seg, color: 0x1d4ed8, opacity: 0.86 }));
    }

    if (showProjectionRays) {
      lines.push({
        points: [north, zSphere, { x: sampleZ.re, y: sampleZ.im, z: -1 }],
        color: 0x111111,
        opacity: 0.4,
      });
      if (sampleW && cFinite(sampleW)) {
        lines.push({
          points: [north, wSphere, { x: sampleW.re, y: sampleW.im, z: -1 }],
          color: 0x0a66c2,
          opacity: 0.42,
        });
      }
    }
    return lines;
  }, [
    objectCurveSphereAfter,
    objectCurveSphereBefore,
    orbitSphereTraceAfter,
    orbitSphereTraceBefore,
    sampleMode,
    sampleW,
    sampleZ,
    showEquator,
    showMappedCurve,
    showPlaneGrid,
    showPresetCurve,
    showProjectionRays,
    showSphereGrid,
    showUnitCircle,
    wSphere,
    zSphere,
  ]);

  const spherePoints = useMemo<RiemannSpherePoint[]>(() => {
    const points: RiemannSpherePoint[] = [];
    if (showPoles) {
      points.push({ x: 0, y: 0, z: 1, color: 0xf57c00, size: 0.075 });
      points.push({ x: 0, y: 0, z: -1, color: 0x7c879f, size: 0.052 });
    }
    points.push({ x: zSphere.x, y: zSphere.y, z: zSphere.z, color: 0x111111, size: 0.07 });
    points.push({ x: wSphere.x, y: wSphere.y, z: wSphere.z, color: 0x0a66c2, size: 0.07 });
    if (showFixedPoints) {
      for (const fp of fixedPointsSphere) {
        points.push({ x: fp.x, y: fp.y, z: fp.z, color: 0x16a34a, size: 0.055 });
      }
    }
    return points;
  }, [fixedPointsSphere, showFixedPoints, showPoles, wSphere, zSphere]);

  const sphereGuides = useMemo<RiemannSphereGuide[]>(
    () => (showSphereGuide ? [{ center: { x: 0, y: 0, z: 0 }, radius: 1, color: 0x9ca3af, opacity: 0.2, wireframe: true }] : []),
    [showSphereGuide]
  );

  const beforeOnlySphereLines = useMemo<RiemannSphereLine[]>(() => {
    const lines: RiemannSphereLine[] = [];
    objectCurveSphereBefore.forEach((seg) => lines.push({ points: seg, color: 0x1f2937, opacity: 0.86 }));
    if (sampleMode === "orbit" && orbitSphereTraceBefore.length >= 2) {
      lines.push({ points: orbitSphereTraceBefore, color: 0x232323, opacity: 0.9 });
    }
    return lines;
  }, [objectCurveSphereBefore, orbitSphereTraceBefore, sampleMode]);

  const afterOnlySphereLines = useMemo<RiemannSphereLine[]>(() => {
    const lines: RiemannSphereLine[] = [];
    objectCurveSphereAfter.forEach((seg) => lines.push({ points: seg, color: 0x1d4ed8, opacity: 0.88 }));
    if (sampleMode === "orbit" && orbitSphereTraceAfter.length >= 2) {
      lines.push({ points: orbitSphereTraceAfter, color: 0x0a66c2, opacity: 0.9 });
    }
    return lines;
  }, [objectCurveSphereAfter, orbitSphereTraceAfter, sampleMode]);

  return (
    <div style={{ display: "grid", gap: 10 }}>
      <div style={cardStyle}>
        <div style={{ fontWeight: 800 }}>Riemann Sphere / Stereographic Projection Lab</div>
        <div style={{ fontSize: 12, opacity: 0.82, marginTop: 4 }}>
          C and C union infinity are visualized as one sphere. This lab links plane formulas to geometric motion on S2.
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(290px, 1fr))", gap: 10 }}>
        <div style={cardStyle}>
          <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>Projection Explorer</div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
            <button type="button" onClick={() => setSampleMode("orbit")} style={pill(sampleMode === "orbit")}>Plane -&gt; sphere (orbit)</button>
            <button type="button" onClick={() => setSampleMode("manual")} style={pill(sampleMode === "manual")}>Plane -&gt; sphere (manual)</button>
          </div>
          {sampleMode === "orbit" ? (
            <div style={{ display: "grid", gap: 8 }}>
              <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11 }}>
                speed
                <input type="range" min={0.2} max={2.2} step={0.1} value={animSpeed} onChange={(e) => setAnimSpeed(Number(e.target.value))} />
                <span style={{ fontFamily: "monospace" }}>{animSpeed.toFixed(1)}</span>
              </label>
              <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11 }}>
                radius
                <input type="range" min={0.3} max={2.1} step={0.1} value={sampleRadius} onChange={(e) => setSampleRadius(Number(e.target.value))} />
                <span style={{ fontFamily: "monospace" }}>{sampleRadius.toFixed(1)}</span>
              </label>
              <button type="button" onClick={() => setAnimating((v) => !v)}>{animating ? "Pause orbit" : "Resume orbit"}</button>
            </div>
          ) : (
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
              <label style={{ fontSize: 11 }}>
                Re(z)
                <input type="number" step={0.05} value={manualZ.re} onChange={(e) => setManualZ((prev) => ({ ...prev, re: Number(e.target.value) || 0 }))} />
              </label>
              <label style={{ fontSize: 11 }}>
                Im(z)
                <input type="number" step={0.05} value={manualZ.im} onChange={(e) => setManualZ((prev) => ({ ...prev, im: Number(e.target.value) || 0 }))} />
              </label>
            </div>
          )}
          <div style={{ display: "grid", gap: 4, fontSize: 11, marginTop: 8 }}>
            <label style={{ display: "flex", gap: 6 }}><input type="checkbox" checked={showProjectionRays} onChange={(e) => setShowProjectionRays(e.target.checked)} />Show stereographic rays</label>
            <label style={{ display: "flex", gap: 6 }}><input type="checkbox" checked={showPlaneGrid} onChange={(e) => setShowPlaneGrid(e.target.checked)} />Show plane grid</label>
            <label style={{ display: "flex", gap: 6 }}><input type="checkbox" checked={showAxes} onChange={(e) => setShowAxes(e.target.checked)} />Show axes</label>
            <label style={{ display: "flex", gap: 6 }}><input type="checkbox" checked={showUnitCircle} onChange={(e) => setShowUnitCircle(e.target.checked)} />Show unit circle</label>
            <label style={{ display: "flex", gap: 6 }}><input type="checkbox" checked={showEquator} onChange={(e) => setShowEquator(e.target.checked)} />Show equator</label>
            <label style={{ display: "flex", gap: 6 }}><input type="checkbox" checked={showPoles} onChange={(e) => setShowPoles(e.target.checked)} />Show north/south poles</label>
          </div>
        </div>

        <div style={cardStyle}>
          <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>Geometry on the Sphere</div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
            <button type="button" onClick={() => setGeometryPreset("unit_circle")} style={pill(geometryPreset === "unit_circle")}>Unit circle</button>
            <button type="button" onClick={() => setGeometryPreset("circle_center0")} style={pill(geometryPreset === "circle_center0")}>Circle at 0</button>
            <button type="button" onClick={() => setGeometryPreset("circle_offset")} style={pill(geometryPreset === "circle_offset")}>Offset circle</button>
            <button type="button" onClick={() => setGeometryPreset("real_axis")} style={pill(geometryPreset === "real_axis")}>Real axis</button>
            <button type="button" onClick={() => setGeometryPreset("imag_axis")} style={pill(geometryPreset === "imag_axis")}>Imag axis</button>
            <button type="button" onClick={() => setGeometryPreset("line_x")} style={pill(geometryPreset === "line_x")}>Line x = const</button>
            <button type="button" onClick={() => setGeometryPreset("line_y")} style={pill(geometryPreset === "line_y")}>Line y = const</button>
          </div>
          {(geometryPreset === "circle_center0" || geometryPreset === "circle_offset") && (
            <label style={{ display: "grid", gap: 4, fontSize: 11, marginBottom: 8 }}>
              radius
              <input type="number" min={0.1} step={0.05} value={presetRadius} onChange={(e) => setPresetRadius(Math.max(0.1, Number(e.target.value) || 0.1))} />
            </label>
          )}
          {geometryPreset === "circle_offset" && (
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 8 }}>
              <label style={{ fontSize: 11 }}>
                center x
                <input type="number" step={0.05} value={presetOffsetX} onChange={(e) => setPresetOffsetX(Number(e.target.value) || 0)} />
              </label>
              <label style={{ fontSize: 11 }}>
                center y
                <input type="number" step={0.05} value={presetOffsetY} onChange={(e) => setPresetOffsetY(Number(e.target.value) || 0)} />
              </label>
            </div>
          )}
          {(geometryPreset === "line_x" || geometryPreset === "line_y") && (
            <label style={{ display: "grid", gap: 4, fontSize: 11, marginBottom: 8 }}>
              constant
              <input type="number" step={0.05} value={presetLineConst} onChange={(e) => setPresetLineConst(Number(e.target.value) || 0)} />
            </label>
          )}
          <div style={{ display: "grid", gap: 4, fontSize: 11 }}>
            <label style={{ display: "flex", gap: 6 }}><input type="checkbox" checked={showPresetCurve} onChange={(e) => setShowPresetCurve(e.target.checked)} />Show object on sphere</label>
            <label style={{ display: "flex", gap: 6 }}><input type="checkbox" checked={showMappedCurve} onChange={(e) => setShowMappedCurve(e.target.checked)} />Show Möbius image on sphere</label>
            <label style={{ display: "flex", gap: 6 }}><input type="checkbox" checked={showSphereGrid} onChange={(e) => setShowSphereGrid(e.target.checked)} />Show meridians / guides</label>
            <label style={{ display: "flex", gap: 6 }}><input type="checkbox" checked={showSphereGuide} onChange={(e) => setShowSphereGuide(e.target.checked)} />Show sphere wireframe</label>
          </div>
          <div style={{ fontSize: 11, opacity: 0.78, marginTop: 8 }}>
            Active object: {objectLabel}
          </div>
        </div>

        <div style={cardStyle}>
          <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>Möbius on the Sphere</div>
          <div style={{ display: "grid", gap: 4, fontSize: 11 }}>
            <div>visual mode: {modeLabel}</div>
            <div>fixed points: {fixed.kind === "all" ? "all points" : fixed.kind === "none" ? "none" : fixed.values.map(cToStr).join(" ; ")}</div>
            <div>
              pole (z -&gt; infinity): {poleZ ? cToStr(poleZ) : "none (c = 0)"}
            </div>
            <div>
              image of infinity f(infinity): {imageInfinity ? cToStr(imageInfinity) : "infinity (c = 0)"}
            </div>
            <div>
              special case: {cAbs2(params.c) <= eps ? "affine map, infinity maps to infinity" : "non-affine map, finite pole exists"}
            </div>
          </div>
          <div style={{ marginTop: 8, display: "flex", gap: 6, flexWrap: "wrap" }}>
            <button type="button" onClick={() => setShowFixedPoints((v) => !v)} style={pill(showFixedPoints)}>
              Fixed points on sphere
            </button>
            <button type="button" onClick={() => setLayoutMode("beforeAfter")} style={pill(layoutMode === "beforeAfter")}>
              Before/After sphere
            </button>
          </div>
          <div style={{ fontSize: 11, opacity: 0.75, marginTop: 8 }}>
            For rotation, scaling, inversion, and Cayley examples, tune a,b,c,d in the Map tab and watch this sphere lab update.
          </div>
        </div>

        <div style={cardStyle}>
          <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>Analysis / Inspector</div>
          <div style={{ display: "grid", gap: 4, fontSize: 11 }}>
            <div><b>selected z:</b> {cToStr(sampleZ)}</div>
            <div><b>|z|:</b> {cAbs(sampleZ).toFixed(6)} · <b>arg(z):</b> {Math.atan2(sampleZ.im, sampleZ.re).toFixed(6)}</div>
            <div><b>sphere (z):</b> X={zSphere.x.toFixed(6)}, Y={zSphere.y.toFixed(6)}, Z={zSphere.z.toFixed(6)}</div>
            <div><b>projected back:</b> {zBackProjected ? cToStr(zBackProjected) : "infinity"}</div>
            <div><b>image f(z):</b> {sampleW && cFinite(sampleW) ? cToStr(sampleW) : "infinity"}</div>
            <div><b>sphere (f(z)):</b> X={wSphere.x.toFixed(6)}, Y={wSphere.y.toFixed(6)}, Z={wSphere.z.toFixed(6)}</div>
            <div><b>inverse from sphere:</b> {wBackProjected ? cToStr(wBackProjected) : "infinity"}</div>
            <div><b>special status z:</b> {projectionStatus.z}</div>
            <div><b>special status image:</b> {projectionStatus.w}</div>
          </div>
          <div style={{ marginTop: 8, fontSize: 11, opacity: 0.75 }}>
            Stereographic formulas: X = 2x/(x^2+y^2+1), Y = 2y/(x^2+y^2+1), Z = (x^2+y^2-1)/(x^2+y^2+1).
          </div>
        </div>
      </div>

      <div style={cardStyle}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
          <div style={{ fontWeight: 800 }}>Center Scene</div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
            <button type="button" onClick={() => setLayoutMode("split")} style={pill(layoutMode === "split")}>Plane + Sphere + Image</button>
            <button type="button" onClick={() => setLayoutMode("overlay")} style={pill(layoutMode === "overlay")}>Sphere above plane</button>
            <button type="button" onClick={() => setLayoutMode("sphere")} style={pill(layoutMode === "sphere")}>Sphere only</button>
            <button type="button" onClick={() => setLayoutMode("beforeAfter")} style={pill(layoutMode === "beforeAfter")}>Before / After sphere</button>
          </div>
        </div>
      </div>

      {layoutMode === "split" && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, minmax(260px, 1fr))", gap: 10, alignItems: "stretch" }}>
          <div style={{ ...cardStyle, marginTop: 0, display: "grid", gap: 6 }}>
            <div style={{ fontWeight: 700, fontSize: 12 }}>Z-plane (domain)</div>
            <div style={{ minHeight: 250, height: "100%" }}>
              <PlanePlot id="svgZMobiusRiemannLab" extent={3} step={1} ref={zRef} style={{ height: "100%" }} onClickPoint={onPickZPoint} />
            </div>
            <div style={{ fontSize: 11, opacity: 0.75 }}>Click to pick selected z in manual mode.</div>
          </div>
          <div style={{ ...cardStyle, marginTop: 0, display: "grid", gap: 6 }}>
            <div style={{ fontWeight: 700, fontSize: 12 }}>Riemann sphere</div>
            <RiemannSpherePlot lines={sphereLines} points={spherePoints} guideSpheres={sphereGuides} style={{ height: 270 }} />
            <div style={{ fontSize: 11, opacity: 0.75 }}>North pole = infinity, south pole = z=0, equator = |z|=1.</div>
          </div>
          <div style={{ ...cardStyle, marginTop: 0, display: "grid", gap: 6 }}>
            <div style={{ fontWeight: 700, fontSize: 12 }}>W-plane (image)</div>
            <div style={{ minHeight: 250, height: "100%" }}>
              <PlanePlot id="svgWMobiusRiemannLab" extent={3} step={1} ref={wRef} style={{ height: "100%" }} />
            </div>
            <div style={{ fontSize: 11, opacity: 0.75 }}>
              w = {sampleW && cFinite(sampleW) ? cToStr(sampleW) : "infinity (pole reached)"}
            </div>
          </div>
        </div>
      )}

      {layoutMode === "overlay" && (
        <div style={{ display: "grid", gap: 10 }}>
          <div style={{ ...cardStyle, marginTop: 0 }}>
            <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>Sphere with projection rays</div>
            <RiemannSpherePlot lines={sphereLines} points={spherePoints} guideSpheres={sphereGuides} style={{ height: 420 }} />
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(2, minmax(260px, 1fr))", gap: 10 }}>
            <div style={{ ...cardStyle, marginTop: 0 }}>
              <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>Z-plane</div>
              <div style={{ minHeight: 220 }}>
                <PlanePlot id="svgZMobiusRiemannOverlay" extent={3} step={1} ref={zRef} style={{ height: "100%" }} onClickPoint={onPickZPoint} />
              </div>
            </div>
            <div style={{ ...cardStyle, marginTop: 0 }}>
              <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>W-plane</div>
              <div style={{ minHeight: 220 }}>
                <PlanePlot id="svgWMobiusRiemannOverlay" extent={3} step={1} ref={wRef} style={{ height: "100%" }} />
              </div>
            </div>
          </div>
        </div>
      )}

      {layoutMode === "sphere" && (
        <div style={{ ...cardStyle, marginTop: 0 }}>
          <RiemannSpherePlot lines={sphereLines} points={spherePoints} guideSpheres={sphereGuides} style={{ height: 440 }} />
          <div style={{ marginTop: 8, fontSize: 12, opacity: 0.78 }}>
            Sphere-only mode: inspect generalized circles, infinity behavior, and mapped trajectories directly on S2.
          </div>
        </div>
      )}

      {layoutMode === "beforeAfter" && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(2, minmax(320px, 1fr))", gap: 10 }}>
          <div style={{ ...cardStyle, marginTop: 0 }}>
            <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>Before Möbius (z on sphere)</div>
            <RiemannSpherePlot lines={beforeOnlySphereLines} points={[{ x: zSphere.x, y: zSphere.y, z: zSphere.z, color: 0x111111, size: 0.072 }]} guideSpheres={sphereGuides} style={{ height: 360 }} />
          </div>
          <div style={{ ...cardStyle, marginTop: 0 }}>
            <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 6 }}>After Möbius (f(z) on sphere)</div>
            <RiemannSpherePlot lines={afterOnlySphereLines} points={[{ x: wSphere.x, y: wSphere.y, z: wSphere.z, color: 0x0a66c2, size: 0.072 }]} guideSpheres={sphereGuides} style={{ height: 360 }} />
          </div>
        </div>
      )}
    </div>
  );
};
